window.MENU_DATA = {"2026-10": {"versione": 1, "mese": "2026-10", "titolo": "Ottobre 2026", "stagione": "autunno", "famiglia": {"descrizione": "2 adulti + 1 porzione adulto per il pranzo del giorno dopo + bimbo di 3 anni + bimbo di 1 anno", "porzioniAdultoEquivalenti": 3.85}, "esclusi": ["funghi", "peperoni", "paprica", "peperoncino"], "intolleranze": ["lattosio (in lista si usano prodotti senza lattosio; in alternativa pastiglia di lattasi)"], "obiettiviSettimanali": {"pesce": [2, 3], "legumi": [2, 3], "carne_bianca": [1, 2], "uova": [0, 1], "carne_rossa": [0, 1], "formaggi": [0, 1]}, "settimane": [{"id": "S1", "dal": "2026-10-01", "al": "2026-10-03", "giornoSpesa": "2026-09-30", "nota": "Solo 2 cene (giovedì e venerdì), sabato pizza. Giovedì si usano le ultime zucchine di stagione."}, {"id": "S2", "dal": "2026-10-04", "al": "2026-10-10", "giornoSpesa": "2026-10-03", "nota": "Domenica 4: al mattino sugo base arancione (2 boccali, 4 vaschette: 550 g in frigo per la frittata di lunedì 5, 870 g in frigo per gli spaghettini di martedì 6, 2 da circa 600 g in congelatore per le pizze di sabato 10 e 17); la sera gnocchi di zucca e ceci e, dopo cena, le patate di lunedì pelate e tagliate in frigo. Lunedì dopo cena prepara e impana le polpettine di lenticchie per martedì. Mercoledì pesto di casa (pinoli), venerdì gamberi (crostacei): vedi note bimbi. Giovedì 8 ragù di casa con la bieta surgelata (in frigo mercoledì sera). Venerdì sera sposta in frigo 1 vaschetta di sugo per la pizza."}, {"id": "S3", "dal": "2026-10-11", "al": "2026-10-17", "giornoSpesa": "2026-10-10", "nota": "Domenica 11: al mattino purea di zucca (5 vaschette da 200 g: 1 in frigo per lunedì 12, 1 in congelatore per mercoledì 14 da passare in frigo martedì sera, 3 jolly); la sera passatelli. Platessa (martedì 13) e nasello (giovedì 15): comprali surgelati e passali in frigo la sera prima. Venerdì 16 latte di cocco: se i bimbi non l'hanno mai assaggiato, faglielo provare prima a pranzo. Nessun crostaceo né frutta a guscio questa settimana. Per lunedì 12 compra petto di pollo intero (lo trita il Bimby), non macinato; 1 confezione di pangrattato da 500 g basta per passatelli e nuggets. Venerdì 16 dopo cena la seconda vaschetta di sugo arancione in frigo per la pizza di sabato 17."}, {"id": "S4", "dal": "2026-10-18", "al": "2026-10-24", "giornoSpesa": "2026-10-17", "nota": "Domenica 18: al mattino la crema di broccoli, porri e spinaci (2 vaschette, entrambe in congelatore: A per il purè verde della trota di mercoledì 21, da passare in frigo martedì sera; B per la pasta e piselli di giovedì 22, da passare in frigo mercoledì sera); la sera zuppa di orzo e borlotti e, dopo, l'impasto dei nuggets di lunedì in frigo. Lunedì sera: ragù di casa (circa 600 g) dal congelatore al frigo per martedì 20. Trota (mer 21) e branzino (ven 23) anche surgelati, in frigo la sera prima. In settimana nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo."}, {"id": "S5", "dal": "2026-10-25", "al": "2026-10-31", "giornoSpesa": "2026-10-24", "nota": "Domenica 25: al mattino la besciamella al cavolfiore senza lattosio (2 vaschette da circa 800 g, entrambe in congelatore: la 1 in frigo martedì 27 sera per le uova di mercoledì 28, la 2 in frigo mercoledì 28 sera per l'orzo cremoso ai ceci di giovedì 29); la sera farro al pesto di casa (pesto in frigo sabato sera). Salmone di lunedì 26 anche surgelato, in frigo domenica sera. Il macinato di pollo di martedì 27 va congelato il giorno della spesa e messo in frigo lunedì sera. Giovedì sera nasello e gamberi surgelati in frigo e verdure del purè pelate e tagliate; i gamberi sono crostacei (vedi nota bimbi di venerdì 30)."}], "generato": "2026-09-29", "giorni": [{"data": "2026-10-01", "tipo": "cena", "piatti": ["r915633"], "categoria": "carne_bianca", "nota": "Ultime zucchine di stagione: la crema di zucchine si mescola al riso e sparisce. Tutto in 40 minuti. Dopo cena pulisci la zucca (250 g di polpa) e taglia 200 g di cimette di cavolfiore: in frigo in un contenitore per domani.", "giorno": "giovedì"}, {"data": "2026-10-02", "tipo": "cena", "piatti": ["c-mac-and-cheese-zucca-cavolfiore"], "categoria": "formaggi", "nota": "Con zucca e cavolfiore già tagliati ieri sera: 40 minuti. Gratinatura solo se avanza tempo (+10 min). Zucca e cavolfiore frullati nella salsa al formaggio senza lattosio, la pasta sembra solo 'al formaggio'.", "giorno": "venerdì"}, {"data": "2026-10-03", "tipo": "pizza", "giorno": "sabato"}, {"data": "2026-10-04", "tipo": "cena", "piatti": ["c-gnocchi-zucca-ceci"], "categoria": "legumi", "nota": "Domenica: al mattino il sugo base arancione (2 boccali, vedi la preparazione della domenica); nel pomeriggio gli gnocchi di zucca e farina di ceci (70 minuti). Dopo cena pela e taglia a cubotti 800 g di patate per domani e tienile in frigo coperte d'acqua fredda.", "giorno": "domenica"}, {"data": "2026-10-05", "tipo": "cena", "piatti": ["r211966", "c-patate-al-forno-rosmarino"], "categoria": "uova", "nota": "Il sugo pizza della frittata è la vaschetta da 550 g di sugo base di ieri (in frigo). Patate pelate e tagliate ieri sera: scolale, asciugale e infornale per prime; intanto la frittata cuoce al Varoma e finisce sotto il grill accanto alle patate: 45 minuti. Dopo cena: impasta, forma e impana le polpettine di lenticchie per domani (circa 40 minuti), crude in frigo.", "giorno": "lunedì"}, {"data": "2026-10-06", "tipo": "cena", "piatti": ["r735962"], "categoria": "legumi", "nota": "La vaschetta da 870 g di sugo base è in frigo da domenica. Le polpettine le hai formate e impanate ieri sera dopo cena (circa 40 minuti): stasera 20 minuti di forno mentre cuociono gli spaghettini, circa 30 minuti.", "giorno": "martedì"}, {"data": "2026-10-07", "tipo": "cena", "piatti": ["r52640"], "categoria": "pesce", "nota": "Martedì sera: in frigo 150 g di pesto di casa e i filetti di sogliola surgelati. Pesto con pinoli (frutta a guscio): ai bimbi solo se già provati (vale anche per il bimbo di 3 anni), altrimenti involtini senza pesto e la loro porzione di riso con la crema di romanesco prelevata prima del pesto.", "giorno": "mercoledì"}, {"data": "2026-10-08", "tipo": "cena", "piatti": ["c-gnocchi-ragu-casa-bietole-finocchi"], "categoria": "carne_rossa", "nota": "Mercoledì sera: ragù classico di casa (circa 600 g) e 200 g di bieta surgelata dal congelatore al frigo. Bieta e finocchi frullati nel sugo, gnocchi pronti in 30 minuti.", "giorno": "giovedì"}, {"data": "2026-10-09", "tipo": "cena", "piatti": ["r768162"], "categoria": "pesce", "nota": "Giovedì sera: gamberi (e, se serve, platessa) surgelati in frigo. Gamberi = crostacei: ai bimbi solo se li hanno già mangiati, altrimenti per chi non li ha provati solo platessa (70 g a testa, sbriciolata nella sua pasta). Dopo cena sposta in frigo 1 vaschetta di sugo base (circa 600 g) per la pizza di domani.", "giorno": "venerdì"}, {"data": "2026-10-10", "tipo": "pizza", "giorno": "sabato"}, {"data": "2026-10-11", "tipo": "cena", "piatti": ["r125528"], "categoria": "uova", "nota": "Domenica: al mattino la purea di zucca (25 minuti al Varoma); la sera passatelli nel brodo cremoso di porri, sedano rapa e finocchi frullati (50 minuti).", "giorno": "domenica"}, {"data": "2026-10-12", "tipo": "cena", "piatti": ["c-pasta-ragu-bianco-pollo-verdure"], "categoria": "carne_bianca", "nota": "Usa 1 vaschetta di purea di zucca di ieri (in frigo). 40 minuti. Dopo cena, per domani: sbuccia e taglia a cubetti di 3 cm 600 g di zucca e 600 g di patate (patate coperte d'acqua fredda) e mettile in frigo, insieme alla platessa surgelata (e alle cimette di cavolfiore, se surgelate).", "giorno": "lunedì"}, {"data": "2026-10-13", "tipo": "cena", "piatti": ["r800501", "r104596"], "categoria": "pesce", "nota": "Lunedì sera dopo cena: sbuccia e taglia a cubetti di 3 cm 600 g di zucca e 600 g di patate (patate coperte d'acqua fredda), in frigo; metti in frigo anche la platessa surgelata (e le cimette di cavolfiore, se surgelate). Stasera: impasto dei nuggets nel Bimby (5 minuti), sciacqua il boccale e avvia subito il purè (32 minuti); intanto forma, impana e inforna i nuggets: 45 minuti.", "giorno": "martedì"}, {"data": "2026-10-14", "tipo": "cena", "piatti": ["r433351"], "categoria": "legumi", "nota": "Usa la vaschetta 2 di purea di zucca (in congelatore da domenica: in frigo martedì sera). Ceci già lessati: 40 minuti.", "giorno": "mercoledì"}, {"data": "2026-10-15", "tipo": "cena", "piatti": ["r822769"], "categoria": "pesce", "nota": "Mercoledì sera: filetti di nasello surgelati in frigo. Una sola cottura (riso nel cestello, verza, topinambur e pesce nel Varoma): 40 minuti.", "giorno": "giovedì"}, {"data": "2026-10-16", "tipo": "cena", "piatti": ["r700542"], "categoria": "legumi", "nota": "Vellutata dolce di patate dolci e lenticchie rosse con bulgur: 40 minuti, niente da preparare il giorno prima. Latte di cocco: se i bimbi non l'hanno mai assaggiato, faglielo provare prima a pranzo. Dopo cena sposta in frigo 1 vaschetta di sugo base (circa 600 g) per la pizza di domani.", "giorno": "venerdì"}, {"data": "2026-10-17", "tipo": "pizza", "giorno": "sabato"}, {"data": "2026-10-18", "tipo": "cena", "piatti": ["c-zuppa-orzo-borlotti"], "categoria": "legumi", "nota": "Domenica: al mattino la crema di broccoli, porri e spinaci (base della settimana: vaschette A e B in congelatore); la sera zuppa di orzo e borlotti con sedano rapa e finocchi frullati (55 minuti). Stasera, dopo la zuppa: impasto dei nuggets nel Bimby (10 minuti), in frigo coperto.", "giorno": "domenica"}, {"data": "2026-10-19", "tipo": "cena", "piatti": ["r84848", "r54838"], "categoria": "carne_bianca", "nota": "L'impasto è già in frigo: avvia subito il purè nel Bimby (35 minuti); intanto forma e impana i nuggets (circa 30, un po' più grandi) e infornali a 200°C per 15-18 minuti: 45 minuti.", "giorno": "lunedì"}, {"data": "2026-10-20", "tipo": "cena", "piatti": ["c-pasta-ragu-casa-crema-arancione"], "categoria": "carne_rossa", "nota": "Lunedì sera: ragù classico di casa (circa 600 g) dal congelatore al frigo. Crema di patate dolci e sedano rapa frullata nel ragù, pasta corta in pentola: 35 minuti.", "giorno": "martedì"}, {"data": "2026-10-21", "tipo": "cena", "piatti": ["r628835"], "categoria": "pesce", "nota": "Martedì sera: vaschetta A di crema di broccoli e filetti di trota dal congelatore al frigo. La crema diventa il purè verde: 40 minuti.", "giorno": "mercoledì"}, {"data": "2026-10-22", "tipo": "cena", "piatti": ["r67902"], "categoria": "legumi", "nota": "Mercoledì sera: la vaschetta B di crema di broccoli dal congelatore al frigo; frullata con i piselli fa da condimento verde. 35 minuti.", "giorno": "giovedì"}, {"data": "2026-10-23", "tipo": "cena", "piatti": ["r377348"], "categoria": "pesce", "nota": "Giovedì sera: filetti di branzino surgelati in frigo. Pizzaiola con sedano rapa e cavolo cappuccio frullati; cous cous pronto in 5 minuti: 35 minuti.", "giorno": "venerdì"}, {"data": "2026-10-24", "tipo": "pizza", "giorno": "sabato"}, {"data": "2026-10-25", "tipo": "cena", "piatti": ["c-farro-pesto-casa-cannellini-broccoli"], "categoria": "legumi", "nota": "Sabato sera: 150 g di pesto di casa in frigo. Al mattino la besciamella di cavolfiore (base della settimana): tutte e due le vaschette in congelatore. La sera farro al pesto con crema di cannellini, broccoli e cavolo nero (40 minuti). Pesto con pinoli: vedi nota del 7.", "giorno": "domenica"}, {"data": "2026-10-26", "tipo": "cena", "piatti": ["r130472"], "categoria": "pesce", "nota": "Domenica sera: salmone surgelato in frigo (o fresco, controlla le lische). Risotto con finocchi, porri e sedano rapa frullati: 35 minuti. Dopo cena sposta in frigo il macinato di pollo (congelato il giorno della spesa) per domani.", "giorno": "lunedì"}, {"data": "2026-10-27", "tipo": "cena", "piatti": ["r827280"], "categoria": "carne_bianca", "nota": "Ragù di pollo con finocchio, cavolo cappuccio e verza tritati finissimi, su polenta cremosa: 40-45 minuti. Dopo cena sposta la vaschetta 1 della besciamella al cavolfiore dal congelatore al frigo per le uova di domani.", "giorno": "martedì"}, {"data": "2026-10-28", "tipo": "cena", "piatti": ["r91412"], "categoria": "uova", "nota": "Uova gratinate sulla vaschetta 1 di besciamella di cavolfiore (in frigo da martedì sera), con la purea di patate: 45 minuti. Dopo cena sposta la vaschetta 2 della besciamella dal congelatore al frigo per l'orzo di domani.", "giorno": "mercoledì"}, {"data": "2026-10-29", "tipo": "cena", "piatti": ["c-orzo-cremoso-ceci-cavolfiore"], "categoria": "legumi", "nota": "Mercoledì sera: la vaschetta 2 di besciamella dal congelatore al frigo; con i ceci diventa la crema che manteca l'orzo (metti subito l'orzo sul fuoco): 40 minuti. Dopo cena pela e taglia a cubetti di 2-3 cm 500 g di patate e 500 g di patate dolci e a rondelle 200 g di carote; tienili in frigo coperti d'acqua fredda per il purè di domani. Metti in frigo anche nasello e gamberi surgelati.", "giorno": "giovedì"}, {"data": "2026-10-30", "tipo": "cena", "piatti": ["r420994", "r751023"], "categoria": "pesce", "nota": "Giovedì sera: nasello e gamberi surgelati in frigo (se un bimbo non ha mai mangiato gamberi, mini-burger di solo nasello: passo 2 della ricetta). Verdure del purè già tagliate da ieri. Prima l'impasto dei burger al Bimby (5 min), sciacqua il boccale e avvia il purè al Varoma (30 min); intanto cuoci i burger in forno a 200°C per 15 minuti su un'unica teglia: 45 minuti.", "giorno": "venerdì"}, {"data": "2026-10-31", "tipo": "pizza", "giorno": "sabato"}], "prep": [{"id": "prep-2026-10-04", "data": "2026-10-04", "ricetta": "r54703", "titolo": "Sugo base arancione (pomodoro, zucca e carote)", "descrizione": "Al mattino 2 boccali di salsa di fila (circa 40 minuti l'uno, quasi senza sorveglianza), frullata liscia e senza sale: circa 2,6 kg. Dividi in 4 vaschette con etichetta e data: 550 g in frigo per la frittata gusto pizza di lunedì 5, 870 g in frigo per gli spaghettini di martedì 6, 2 da circa 600 g in congelatore per le pizze di sabato 10 e 17 (in frigo il venerdì sera). In frigo si conserva 3 giorni.", "usatoIn": ["2026-10-05", "2026-10-06"]}, {"id": "prep-2026-10-11", "data": "2026-10-11", "ricetta": "r507669", "titolo": "Scorta di purea di zucca", "descrizione": "1 kg di polpa di zucca al Varoma per 25 minuti, frullata con pochissima acqua di cottura, senza sale. 5 vaschette da 200 g: 1 in frigo per lunedì 12 (pasta al ragù bianco), 1 in congelatore per mercoledì 14 (pasta risottata ai ceci, in frigo martedì sera); le altre 3 restano in congelatore come jolly per il sugo delle pizze del sabato o per novembre.", "usatoIn": ["2026-10-12", "2026-10-14"]}, {"id": "prep-2026-10-18", "data": "2026-10-18", "ricetta": "r399588", "titolo": "Crema di broccoli e porri (con spinaci)", "descrizione": "Broccoli, porri e spinaci cotti e frullati lisci in una crema verde (circa 1,2 kg di verdura). 2 vaschette, entrambe in congelatore: A (circa 650 g) per il purè verde della trota di mercoledì 21, in frigo martedì sera; B (circa 850 g) per la pasta e piselli di giovedì 22, in frigo mercoledì sera.", "usatoIn": ["2026-10-21", "2026-10-22"]}, {"id": "prep-2026-10-25", "data": "2026-10-25", "ricetta": "c-besciamella-cavolfiore-senza-lattosio", "titolo": "Besciamella al cavolfiore senza lattosio", "descrizione": "Al mattino (circa 55 minuti) 800 g di cimette di cavolfiore al Varoma, poi frullate e addensate con 700 g di latte e 50 g di burro senza lattosio, 60 g di farina e 40 g di Parmigiano, senza sale: circa 1,6 kg. 2 vaschette da circa 800 g (400 g di cavolfiore ciascuna), entrambe in congelatore: la 1 per le uova gratinate di mercoledì 28 (in frigo martedì 27 sera), la 2 per l'orzo cremoso ai ceci e cavolfiore di giovedì 29 (in frigo mercoledì 28 sera).", "usatoIn": ["2026-10-28", "2026-10-29"]}], "alternative": {"pesce": [["r825767"], ["c-risotto-arancione-merluzzo"], ["r796435", "c-pure-patate-cavolfiore"], ["r112239"], ["r212042"]], "legumi": [["r48901"], ["r903868"], ["r803658"], ["r65221"], ["r710519", "c-pure-patate-cavolfiore"]], "carne_bianca": [["c-cous-cous-pollo-crema-arancione"], ["r754585"], ["r109544", "c-pure-patate-cavolfiore"], ["r70733"], ["r541643"]], "uova": [["r761910"], ["r824055", "c-pure-patate-cavolfiore"], ["r142970", "c-pure-patate-cavolfiore"], ["r829420", "c-pure-patate-cavolfiore"]], "carne_rossa": [["c-gnocchi-ragu-casa-sedano-rapa"], ["r48883"], ["r632309"], ["c-polenta-ragu-casa-crema-arancione"]], "formaggi": [["r105730"], ["r54832"], ["r135477"], ["r337638"], ["r48814"]]}, "noteMese": ["Ragù classico di casa: 2 cene (giovedì 8 e martedì 20), circa 600 g ciascuna. Pesto alla genovese di casa: 2 cene (mercoledì 7 e domenica 25), circa 150 g ciascuna. Passali dal congelatore al frigo la sera prima (lo dice la nota del giorno). Tutte e quattro le alternative di carne rossa usano il ragù di casa (gnocchi con crema di sedano rapa, gnocchi alla romana, cottage pie, polenta con crema arancione): se ne scambi una, le cene col ragù restano 2 e non serve comprare carne rossa.", "Allergeni: il pesto contiene pinoli (frutta a guscio) e Parmigiano; i gamberi (venerdì 9 e 30) sono crostacei. Ai bimbi dai questi alimenti solo se li hanno già provati, mai per la prima volta a cena: altrimenti preleva la loro porzione prima del pesto e dai loro solo platessa o nasello. Il latte di cocco (venerdì 16), se i bimbi non l'hanno mai assaggiato, va provato prima a pranzo.", "Pesce: sogliola, platessa, nasello, trota, branzino, salmone e gamberi vanno benissimo surgelati. Mettili in frigo la sera prima e controlla sempre le lische. Nel mese ci sono 7 pesci diversi, nessuno più di 2 volte.", "Zucca: nelle ricette il peso è di polpa pulita, quindi compra circa il 40% in più (delica o mantovana). Le zucchine ci sono solo giovedì 1; poi zucca, cavoli, porri, sedano rapa, finocchi e patate dolci, sempre frullati o nascosti.", "Basi della domenica: sugo arancione (4/10), purea di zucca (11/10), crema di broccoli (18/10), besciamella di cavolfiore (25/10). Etichetta e data su ogni vaschetta; quelle che non si usano entro 3 giorni vanno in congelatore (crema di broccoli e besciamella: tutte e due le vaschette) e passano in frigo la sera prima.", "Lattosio: latte, panna, burro, besciamella e formaggi freschi sempre nella versione senza lattosio; Parmigiano e grana stagionati vanno bene."], "ricette": {"r54703": {"id": "r54703", "fonte": "cookidoo", "titolo": "Salsa al pomodoro", "url": "https://cookidoo.it/recipes/recipe/it-IT/r54703", "tm6": true, "valutazioneCookidoo": [4.8, 336], "tempoMin": 80, "porzioniRicetta": "6 porzioni", "categoria": "vegetale", "ruolo": "base", "cereale": "nessuno", "ingredientiOriginali": ["120 g di cipolle", "50 g di olio extravergine di oliva", "800 g di polpa di pomodoro", "1 cucchiaino di zucchero", "½ cucchiaino di sale", "5 - 10 foglie di basilico fresche"], "passi": ["Domenica 4 al mattino prepara le verdure per 2 boccali, in 2 mucchietti uguali. Ogni mucchietto: 100 g di cipolla a spicchi, 200 g di carote pelate a pezzi di 3 cm e 300 g di polpa di zucca (sbucciata, senza semi) a cubetti di 3 cm.", "Primo boccale: metti nel boccale il primo mucchietto di verdure e trita 10 sec./vel. 5. Riunisci sul fondo con la spatola.", "Aggiungi 40 g di olio e insaporisci 7 min./120°C/vel. 1.", "Aggiungi 800 g di polpa di pomodoro e 5 foglie di basilico, senza zucchero né sale. Cuoci 25 min./100°C/vel. 2 con il cestello sul coperchio al posto del misurino.", "Controlla che carote e zucca siano morbide (se no, altri 5 min./100°C/vel. 2). Lascia intiepidire 5 minuti.", "Con il misurino inserito frulla 1 min./vel. 5-9 aumentando gradualmente, fino a un sugo liscio senza pezzetti. Versalo in una pentola o ciotola capiente.", "Secondo boccale (non serve lavarlo): metti il secondo mucchietto di verdure e trita 10 sec./vel. 5. Riunisci sul fondo con la spatola.", "Aggiungi 40 g di olio e insaporisci 7 min./120°C/vel. 1.", "Aggiungi 800 g di polpa di pomodoro e 5 foglie di basilico: cuoci 25 min./100°C/vel. 2 con il cestello sul coperchio al posto del misurino.", "Lascia intiepidire 5 minuti, poi con il misurino inserito frulla 1 min./vel. 5-9 aumentando gradualmente. Versalo con il primo sugo e mescola: circa 2,6 kg.", "Dividi subito in 4 vaschette con etichetta e data: 550 g ('lun 5 - frittata'), 870 g ('mar 6 - spaghettini') e 2 da circa 600 g ('pizza sab 10' e 'pizza sab 17').", "Fai raffreddare in fretta, al massimo 2 ore fuori dal frigo: puoi appoggiare le vaschette in una bacinella di acqua fredda.", "Metti in frigo le vaschette di lunedì 5 e martedì 6 (si conservano 3 giorni). Le 2 vaschette per la pizza vanno in congelatore (fino a 3 mesi): sposta in frigo la prima venerdì 9 sera e la seconda venerdì 16 sera."], "modifiche": ["Per ogni boccale: 100 g di cipolle, 200 g di carote a pezzi e 300 g di polpa di zucca a cubetti tritati 10 sec./vel. 5, poi insaporiti con 40 g di olio 7 min./120°C/vel. 1.", "Aggiungi 800 g di polpa di pomodoro e 5 foglie di basilico e cuoci 25 min./100°C/vel. 2 con il cestello sul coperchio al posto del misurino (evita gli schizzi).", "Niente zucchero (carote e zucca addolciscono già) e NIENTE sale: il sugo base resta senza sale e si salano solo le porzioni degli adulti al momento. Il basilico è cotto e frullato a vel. 9: non resta nessun pezzetto verde.", "A fine cottura lascia intiepidire 5 minuti e frulla 1 min./vel. 5-9 aumentando gradualmente: sugo liscio arancio-rosso, nessun pezzetto.", "Moltiplicatore 2 = fai la ricetta 2 volte di fila (2 boccali da circa 1,4 kg), NON raddoppiare nello stesso boccale da 2,2 litri.", "Controllo del lotto: 2 boccali danno circa 2,6 kg di sugo con 1,2 kg di verdura (circa 46 g di verdura ogni 100 g di sugo). Le cene della settimana ne usano 1,42 kg: 550 g per la frittata di lunedì 5 (circa 250 g di verdura, il resto della verdura è nell'impasto) e 870 g per gli spaghettini di martedì 6 (circa 400 g di verdura). Avanzano circa 1,2 kg.", "La vaschetta per la frittata passa da circa 300 g a 550 g: con soli 300 g di sugo (circa 140 g di verdura) la cena di lunedì non arrivava ai 400 g di verdura nascosta.", "Il sugo avanzato (2 vaschette da circa 600 g) va in congelatore per la pizza di sabato 10 e di sabato 17 (fino a 3 mesi): mettile in frigo una alla volta, la sera di venerdì 9 e la sera di venerdì 16. In frigo il sugo si conserva al massimo 3 giorni: la vaschetta di martedì 6 è ancora nei tempi."], "verduraNascosta": {"verdure": ["zucca", "carote", "cipolle"], "grammiFamiglia": 1200, "come": "Totale della scorta (2 boccali): circa 2,6 kg di sugo con 1,2 kg di zucca, carote e cipolla cotte nel pomodoro e frullate lisce. Lunedì 5 ne servono 550 g (circa 250 g di verdura) sulla frittata, martedì 6 ne servono 870 g (circa 400 g di verdura) sugli spaghettini.", "trucco": "L'arancio di zucca e carote sparisce nel rosso del pomodoro; frullato a vel. 9 ha la stessa consistenza di una passata."}, "lattosio": "no", "notaLattosio": "Nessun latticino.", "notaBimbi": "Sugo senza sale, adatto anche al bimbo di 1 anno; il Parmigiano solo a tavola. Il basilico è frullato: nessun pezzetto verde.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 2, "ingredienti": [{"nome": "cipolle", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 400, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 600, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa: compra circa il 40% in più"}, {"nome": "polpa di pomodoro", "qta": 1600, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "4 scatole da 400 g"}, {"nome": "olio extravergine di oliva", "qta": 80, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "basilico", "qta": 5, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "circa 10 foglie (5 per boccale), cotte e frullate"}], "accompagnamentoConsigliato": "Lunedì 5: 550 g sulla frittata gusto pizza (r211966). Martedì 6: 870 g sugli spaghettini con polpettine di lenticchie (r735962). Il resto (2 vaschette da circa 600 g) per le pizze di sabato 10 e 17.", "perche": "La salsa al pomodoro più votata di Cookidoo diventa un sugo base arancio-rosso senza sale, con quasi metà del peso in verdura frullata: copre il sugo di due cene feriali e di due pizze del sabato.", "passiCompleti": true, "usataNelMese": false}, "c-besciamella-cavolfiore-senza-lattosio": {"id": "c-besciamella-cavolfiore-senza-lattosio", "fonte": "personalizzata", "titolo": "Besciamella al cavolfiore senza lattosio", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 55, "porzioniRicetta": "circa 1,6 kg (2 vaschette da circa 800 g, ognuna con 400 g di cavolfiore)", "categoria": "vegetale", "ruolo": "base", "cereale": "nessuno", "ingredientiOriginali": [], "passi": ["Domenica 25 al mattino: metti nel boccale asciutto 40 g di Parmigiano Reggiano a pezzi e grattugia 10 sec./vel. 10. Trasferisci in una ciotolina e tieni da parte.", "Dividi il cavolfiore in cimette piccole (circa 3 cm) fino a 800 g e mettile nel recipiente del Varoma. Metti nel boccale 700 g di acqua, posiziona il Varoma chiuso e cuoci 28 min./Varoma/vel. 1: le cimette devono essere tenerissime alla punta del coltello (se serve, altri 5 min./Varoma/vel. 1).", "Togli il Varoma, tieni da parte 100 g di acqua di cottura e svuota il boccale.", "Metti nel boccale il cavolfiore cotto, 700 g di latte senza lattosio, 50 g di burro senza lattosio, 60 g di farina 00 e 2 pizzichi di noce moscata, senza sale. Frulla 40 sec./vel. 5-9 aumentando gradualmente, con il misurino inserito, fino a una crema liscia.", "Riunisci sul fondo con la spatola e cuoci 14 min./90°C/vel. 4, finché la salsa si addensa e vela il cucchiaio. Se è troppo densa aggiungi 2-4 cucchiai dell'acqua di cottura tenuta da parte e mescola 10 sec./vel. 4.", "Aggiungi il Parmigiano grattugiato e mescola 10 sec./vel. 4, poi frulla ancora 20 sec./vel. 8 per una besciamella setosa.", "Pesa e dividi in 2 vaschette uguali da circa 800 g, con pellicola a contatto, etichetta e data. Falla raffreddare in fretta (al massimo 2 ore fuori dal frigo: puoi appoggiare le vaschette in una bacinella di acqua fredda), poi metti entrambe le vaschette in congelatore. Vaschetta 1 ('mercoledì 28 - uova'): martedì 27 sera spostala in frigo. Vaschetta 2 ('giovedì 29 - orzo e ceci'): mercoledì 28 sera spostala in frigo.", "Al momento dell'uso mescolala con una frusta; se dopo il congelamento sembra granulosa, frullala 20 sec./vel. 5 finché torna liscia."], "modifiche": ["Lotto ricalcolato sulle due cene che lo usano (mercoledì 28 e giovedì 29): ognuna usa una vaschetta intera da circa 800 g e deve avere almeno 400 g di verdura nascosta, quindi il cavolfiore passa da 400 a 800 g. Con il lotto precedente (1 kg con 400 g di cavolfiore) ogni cena avrebbe avuto solo 200 g di verdura.", "Latte portato da 500 a 700 g, burro da 40 a 50 g, farina da 50 a 60 g, Parmigiano da 30 a 40 g: il cavolfiore raddoppiato dà già corpo, quindi la parte di besciamella cresce meno.", "Il cavolfiore (800 g) si cuoce nel recipiente del Varoma con 700 g di acqua invece che nel cestello, dove non ci starebbe tutto. Capienza: circa 1,6 kg nel boccale in cottura a 90°C/vel. 4, sotto il limite di 2,2 L; tempo di addensamento portato da 8 a 14 minuti per il volume maggiore.", "Sale eliminato (prima ½ cucchiaino): la base finisce in cene condivise con i bimbi, il sale si aggiunge solo nei piatti degli adulti.", "Uso del lotto: vaschetta 1 (circa 800 g) nelle uova gratinate con purè di mercoledì 28 (r91412), 250 g nel purè e circa 550 g come letto sotto le uova; vaschetta 2 (circa 800 g) nell'orzo cremoso ai ceci e cavolfiore di giovedì 29 (c-orzo-cremoso-ceci-cavolfiore), frullata con i ceci. Non avanza nulla.", "Entrambe le vaschette in congelatore: la vaschetta 1 sarebbe rimasta in frigo circa 3 giorni e mezzo, troppo per una salsa di latte e verdura cotta data anche al bimbo di 1 anno. La vaschetta 1 passa in frigo martedì 27 sera, la vaschetta 2 mercoledì 28 sera."], "verduraNascosta": {"verdure": ["cavolfiore"], "grammiFamiglia": 800, "come": "800 g di cavolfiore cotto al vapore e frullato con latte, burro e farina prima di addensare: ogni vaschetta da circa 800 g contiene 400 g di verdura, la quota di una cena.", "trucco": "Bianco nel bianco: sembra la besciamella delle lasagne; noce moscata e Parmigiano coprono l'odore di cavolo. Un cavolfiore cotto bene non lascia retrogusto."}, "lattosio": "sostituito", "notaLattosio": "Latte e burro senza lattosio; il Parmigiano Reggiano stagionato è naturalmente senza lattosio.", "notaBimbi": "Senza sale: va bene anche per il bimbo di 1 anno, la sapidità arriva dal Parmigiano. Cremosa e liscia, senza pezzi. Nessun allergene della lista (contiene latte senza lattosio e il glutine della farina).", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "cavolfiore", "qta": 800, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso delle cimette: circa 1 cavolfiore grande da 1,3 kg o 2 piccoli"}, {"nome": "latte senza lattosio", "qta": 700, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "burro senza lattosio", "qta": 50, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "farina 00", "qta": 60, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": true, "nota": ""}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "noce moscata", "qta": 2, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}], "accompagnamentoConsigliato": "Base della domenica 25: vaschetta 1 per le uova gratinate su purè di patate (r91412, mercoledì 28); vaschetta 2 per l'orzo cremoso ai ceci e cavolfiore di giovedì 29 (c-orzo-cremoso-ceci-cavolfiore).", "perche": "Cookidoo non ha una besciamella con verdura: questa nasconde 800 g di cavolfiore in una salsa bianca senza lattosio e senza sale che i bimbi riconoscono come 'la besciamella delle lasagne'. Un'ora la domenica mattina dà due vaschette, ognuna con la verdura di una cena intera.", "usataNelMese": false}, "r507669": {"id": "r507669", "fonte": "cookidoo", "titolo": "Scorta di purea di zucca", "url": "https://cookidoo.it/recipes/recipe/it-IT/r507669", "tm6": true, "valutazioneCookidoo": [4.4, 8], "tempoMin": 30, "porzioniRicetta": "1000 g (5 vaschette da 200 g)", "categoria": "vegetale", "ruolo": "base", "cereale": "nessuno", "ingredientiOriginali": ["500 g di acqua", "1000 g di zucca"], "passi": ["Domenica 11 al mattino: lava la zucca (circa 1,4 kg intera), tagliala a fette, togli semi e filamenti e sbucciala con un coltello robusto.", "Taglia la polpa a cubetti di 2-3 cm e pesane 1000 g. Mettili nel recipiente del Varoma (se non stanno in uno strato usa anche il vassoio), lasciando liberi alcuni fori.", "Metti nel boccale 500 g di acqua, senza sale. Posiziona il Varoma chiuso e cuoci 25 min./Varoma/vel. 2.", "Controlla con una forchetta: deve entrare senza sforzo (se no, altri 5 min./Varoma/vel. 2). Togli il Varoma con attenzione.", "Versa l'acqua di cottura in una caraffa, tienine da parte 50 g ed elimina il resto.", "Metti nel boccale la zucca e i 50 g di acqua di cottura. Con il misurino inserito frulla 1 min./vel. 4-9 aumentando gradualmente: purea densa e liscia, senza sale.", "Dividi la purea in 5 vaschette da 200 g e scrivi su ognuna etichetta e data. Lasciale raffreddare al massimo 2 ore fuori dal frigo.", "Vaschetta 1 in frigo per la pasta al ragù bianco di pollo di lunedì 12. Vaschetta 2 in congelatore: martedì 13 sera spostala in frigo per la pasta risottata ai ceci di mercoledì 14.", "Vaschette 3, 4 e 5 in congelatore come jolly (fino a 3 mesi). Scongelale sempre in frigo la sera prima e usale nel sugo delle pizze del sabato (17, 24 o 31) o nelle cene di novembre."], "modifiche": ["Usa zucca a polpa soda e dolce (delica o mantovana): più saporita e meno acquosa.", "Frulla con solo 50 g di acqua di cottura (non 100 g): una purea più densa non allunga sughi e impasti e si usa in più preparazioni.", "Congela in 5 vaschette da 200 g con etichetta e data, invece di 3-4 contenitori: ogni vaschetta è una dose pronta.", "Dosi del lotto verificate sulle cene che lo usano: 200 g nel ragù bianco di pollo di lunedì 12 e 200 g nella pasta risottata ai ceci di mercoledì 14, cioè 400 g su circa 1000 g. Il lotto da 1 kg basta e avanza e non va aumentato: restano 3 vaschette jolly (600 g).", "Vaschette jolly: la zucca è già in 7 cene di ottobre, il massimo previsto per la varietà. Per questo usale nel sugo delle pizze del sabato o a novembre, non in altre cene di ottobre."], "verduraNascosta": {"verdure": ["zucca"], "grammiFamiglia": 1000, "come": "5 vaschette da 200 g di zucca frullata: 1 nel ragù bianco di pollo (lunedì 12), 1 nella crema di ceci allo zafferano (mercoledì 14), 3 jolly in congelatore.", "trucco": "Nel ragù bianco lo rende dorato e cremoso, come se ci fosse più formaggio; nella crema allo zafferano il giallo copre l'arancio; nel sugo della pizza sparisce del tutto."}, "lattosio": "no", "notaLattosio": "Solo zucca e acqua.", "notaBimbi": "Solo zucca e acqua, senza sale né condimenti: adatta a tutti, anche al bimbo di 1 anno. Nessun allergene.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "zucca", "qta": 1000, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa: compra circa il 40% in più (circa 1,4 kg di zucca intera, delica o mantovana)"}], "accompagnamentoConsigliato": "Base della domenica: 1 vaschetta per c-pasta-ragu-bianco-pollo-verdure (lunedì 12) e 1 per r433351 (mercoledì 14); le altre 3 nel sugo della pizza o a novembre.", "perche": "La base più versatile per nascondere la verdura: 30 minuti la domenica mattina, mentre il resto della giornata resta libero per i passatelli della sera, danno 5 dosi da 200 g. Due coprono le cene di lunedì e mercoledì, le altre tre restano pronte in congelatore.", "passiCompleti": true, "usataNelMese": false}, "r104596": {"id": "r104596", "fonte": "cookidoo", "titolo": "Puré aromatico di zucca", "url": "https://cookidoo.it/recipes/recipe/it-IT/r104596", "tm6": true, "valutazioneCookidoo": [4.7, 343], "tempoMin": 45, "porzioniRicetta": "6 porzioni", "categoria": "vegetale", "ruolo": "accompagnamento", "cereale": "patate", "ingredientiOriginali": ["400 g di patate a pasta farinosa", "400 g di zucca", "2 cucchiaini di sale", "200 g acqua", "30 g di burro", "2 pizzichi di foglie di salvia secca"], "passi": ["LA SERA PRIMA, dopo cena. Sbuccia 600 g di zucca (peso della polpa pulita) e 600 g di patate farinose e tagliale a cubetti di 3 cm.", "Metti la zucca in un contenitore chiuso e le patate in una ciotola coperte d'acqua fredda; tieni tutto in frigo fino a domani sera.", "LA SERA DELLA CENA. Prepara prima l'impasto dei nuggets (ricetta abbinata) e sciacqua bene il boccale.", "Scola bene le patate. Metti nel boccale patate e zucca.", "Aggiungi 300 g di acqua e 45 g di burro senza lattosio (oppure 30 g di olio extravergine), SENZA sale.", "Cuoci: 32 min./100°C/vel. 2, con il cestello appoggiato sul coperchio al posto del misurino per evitare schizzi.", "Controlla con una forchetta: patate e zucca devono essere tenerissime. Se no, altri 3 min./100°C/vel. 2.", "Rimetti il misurino e amalgama: 30 sec./vel. 4, non di più (le patate diventerebbero collose).", "Preleva le porzioni dei bimbi: purè senza sale e senza salvia. Per il bimbo di 1 anno va bene così, lascialo solo intiepidire.", "Nel resto del purè aggiungi sale, 3 pizzichi di salvia secca e, a piacere, 1 cucchiaio (10 g) di Parmigiano grattugiato; mescola con la spatola.", "Servi caldo con i nuggets. Metti da parte 1 porzione adulto per il pranzo di domani in un contenitore ermetico: in frigo appena intiepidita; domani scaldala in un pentolino con 1-2 cucchiai di acqua, mescolando."], "modifiche": ["Moltiplicatore 1,5 (nel boccale ci sta): 600 g di patate farinose, 600 g di polpa di zucca, 300 g di acqua; cuoci 32 min./100°C/vel. 2 con il cestello sul coperchio.", "Burro → 45 g di burro senza lattosio (oppure 30 g di olio extravergine).", "Nessun sale in cottura; sale e salvia solo nel purè degli adulti.", "Amalgama 30 sec./vel. 4, non di più: le patate diventerebbero collose. A piacere 1 cucchiaio di Parmigiano nel purè degli adulti.", "Per stare nei 45 minuti di martedì: lunedì sera sbuccia e taglia a cubetti di 3 cm zucca e patate (patate coperte d'acqua fredda) e tienile in frigo; scola bene le patate prima di metterle nel boccale."], "verduraNascosta": {"verdure": ["zucca"], "grammiFamiglia": 600, "come": "600 g di zucca cotti insieme alle patate e montati: sembra un purè di patate giallo.", "trucco": "Chiamalo 'purè del sole': per i bimbi è un purè giallo, liscio e dolce; salvia e un cucchiaio di Parmigiano, solo nella parte degli adulti, coprono il gusto dolce della zucca."}, "lattosio": "sostituito", "notaLattosio": "Burro senza lattosio (oppure olio extravergine: allora nessun latticino).", "notaBimbi": "Consistenza perfetta per il bimbo di 1 anno. Preleva le porzioni dei bimbi subito dopo averlo amalgamato: niente sale né salvia (nessun puntino verde) nel loro purè.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.5, "ingredienti": [{"nome": "patate", "qta": 600, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "a pasta farinosa"}, {"nome": "zucca", "qta": 600, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "burro senza lattosio", "qta": 45, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "oppure 30 g di olio extravergine"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "salvia", "qta": 3, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": "secca, solo nel purè degli adulti"}, {"nome": "parmigiano reggiano", "qta": 10, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "facoltativo: 1 cucchiaio grattugiato, solo nel purè degli adulti"}], "accompagnamentoConsigliato": "Polpette, bocconcini di pollo o filetti di pesce al Varoma (un principale di carne o pesce)", "perche": "Purè molto votato che è già metà zucca: 600 g di verdura nascosta in un contorno che i bimbi mangiano come un normale purè.", "passiCompleti": true, "usataNelMese": true}, "r54838": {"id": "r54838", "fonte": "cookidoo", "titolo": "Purè di verdure", "url": "https://cookidoo.it/recipes/recipe/it-IT/r54838", "tm6": true, "valutazioneCookidoo": [4.6, 37], "tempoMin": 45, "porzioniRicetta": "4 porzioni", "categoria": "vegetale", "ruolo": "accompagnamento", "cereale": "patate", "ingredientiOriginali": ["400 g di verdure", "600 g di patate farinose", "1 - 1 ¼ cucchiaino di sale", "250 g di latte", "30 g di burro"], "passi": ["Sbuccia 600 g di patate farinose e tagliale a pezzi di 2-3 cm.", "Dividi 250 g di cavolfiore in cimette. Pela 150 g di topinambur e taglialo a pezzi.", "Metti nel boccale cavolfiore e topinambur: trita 10 sec./vel. 7 e riunisci sul fondo con la spatola.", "Inserisci la farfalla. Aggiungi le patate, 250 g di latte senza lattosio e 30 g di burro senza lattosio, senza sale: cuoci 30-35 min./95°C/antiorario/vel. 1 senza misurino.", "A fine cottura le patate devono essere tenere. Aggiungi 1 pizzico di noce moscata e, se vuoi, 1 cucchiaio (10 g) di Parmigiano grattugiato; metti il misurino e mescola 30 sec./vel. 4.", "Guarda il purè: se restano puntini di verdura togli la farfalla e dai ancora 10 sec./vel. 6 (non di più, diventerebbe colloso). Poi togli la farfalla.", "Preleva le porzioni dei bimbi, senza sale. Per il bimbo di 1 anno va bene così, liscio e morbido: lascialo intiepidire e, se è troppo denso, aggiungi 1 cucchiaio di latte senza lattosio caldo.", "Solo adesso sala a piacere il purè degli adulti, direttamente nei loro piatti.", "Servi caldo. Per il pranzo di domani metti da parte 1 porzione adulto in un contenitore chiuso e, appena intiepidita, riponila in frigo; scaldala con un goccio di latte senza lattosio."], "modifiche": ["Verdure bianche: 250 g di cavolfiore + 150 g di topinambur pelato (spariscono nel purè; il topinambur sostituisce il sedano rapa, già in altre 3 cene della settimana). Tritale 10 sec./vel. 7 (non 5) per una grana finissima.", "Latte → 250 g di latte senza lattosio; burro → 30 g di burro senza lattosio.", "Niente sale in cottura, solo nei piatti degli adulti dopo aver prelevato le porzioni dei bimbi.", "A fine cottura: 30 sec./vel. 4 con la farfalla; se restano puntini di verdura togli la farfalla e dai ancora 10 sec./vel. 6.", "A piacere 1 cucchiaio di parmigiano (10 g) per coprire il gusto del cavolfiore."], "verduraNascosta": {"verdure": ["cavolfiore", "topinambur"], "grammiFamiglia": 400, "come": "400 g di cavolfiore e topinambur tritati finissimi e cotti con le patate nel latte: il purè resta bianco e cremoso.", "trucco": "Bianco nel bianco: nessuno riconosce il cavolfiore e il topinambur sa di patata dolce; noce moscata e parmigiano coprono l'odore."}, "lattosio": "sostituito", "notaLattosio": "Latte e burro senza lattosio.", "notaBimbi": "Morbido e liscio, adatto al bimbo di 1 anno. Cotto senza sale: preleva le porzioni dei bimbi prima di salare quelle degli adulti. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "cavolfiore", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette"}, {"nome": "topinambur", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pelato: comprane circa 200 g"}, {"nome": "patate", "qta": 600, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "a pasta farinosa"}, {"nome": "latte senza lattosio", "qta": 250, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "burro senza lattosio", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "parmigiano reggiano", "qta": 10, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "facoltativo, 1 cucchiaio"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "noce moscata", "qta": 1, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}], "accompagnamentoConsigliato": "Polpette, cotolette di pollo al forno, filetti di pesce o polpettone (un principale di carne o pesce)", "perche": "Ricetta nata per mettere 400 g di verdura in un purè classico: con cavolfiore e topinambur resta bianco e i bimbi non se ne accorgono.", "passiCompleti": true, "usataNelMese": true}, "r751023": {"id": "r751023", "fonte": "cookidoo", "titolo": "Purè di patate e carote al rosmarino", "url": "https://cookidoo.it/recipes/recipe/it-IT/r751023", "tm6": true, "valutazioneCookidoo": [4.7, 200], "tempoMin": 45, "porzioniRicetta": "6 porzioni", "categoria": "vegetale", "ruolo": "accompagnamento", "cereale": "patate", "ingredientiOriginali": ["550 g acqua", "200 g di carota", "500 g di patate americane dolci", "500 g patata", "1 cucchiaino di sale", "1 - 2 pizzichi di pepe nero macinato", "2 - 3 pizzichi di rosmarino secco in polvere", "30 g olio extravergine di oliva"], "passi": ["Scola patate, patate dolci e carote pelate e tagliate ieri sera e tenute in frigo coperte d'acqua. Se non l'hai fatto: pela e taglia 500 g di patate e 500 g di patate dolci a cubetti di 2-3 cm e 200 g di carote a rondelle di 1 cm.", "Metti nel boccale pulito 500 g di acqua, senza sale. Inserisci il cestello e mettici dentro le carote.", "Posiziona il Varoma, distribuisci nel recipiente patate e patate dolci lasciando liberi alcuni fori, chiudi e cuoci 30 min./Varoma/vel. 1. Intanto, se fai i burger di pesce, torna alla loro scheda.", "Controlla con una forchetta: patate e carote devono essere tenerissime (se no, altri 5 min./Varoma/vel. 1). Togli con attenzione il Varoma ed estrai il cestello con la spatola.", "Tieni da parte in una tazza 50 g di acqua di cottura e svuota il boccale.", "Metti nel boccale le carote cotte con i 50 g di acqua e frullale da sole 10 sec./vel. 6. Riunisci sul fondo: non devono restare puntini arancioni (se serve, altri 5 sec./vel. 6).", "Inserisci la farfalla e aggiungi patate, patate dolci, 30 g di olio e 2 pizzichi di rosmarino secco in polvere, senza sale né pepe: 30 sec./vel. 3,5. Togli la farfalla.", "Trasferisci il purè in una ciotola e preleva le porzioni dei bimbi: è già adatto anche al bimbo di 1 anno, basta lasciarlo intiepidire.", "Solo ora aggiungi sale e, a piacere, pepe nei piatti degli adulti, senza rosmarino sopra.", "Servi il purè caldo (con i burger di pesce, se li hai fatti). Metti da parte 1 porzione adulto per il pranzo di domani in un contenitore chiuso in frigo: scaldala al microonde con 1 cucchiaio di acqua, mescolando a metà."], "modifiche": ["Prima, senza farfalla, frulla da sole le carote cotte con 50 g di acqua di cottura 10 sec./vel. 6 (niente puntini arancioni), poi metti la farfalla e aggiungi patate, patate dolci, olio e rosmarino in polvere.", "Pepe: togli (a piacere solo nel piatto degli adulti).", "Niente sale nel purè: sale solo nei piatti degli adulti.", "Rosmarino solo secco in polvere dentro il purè (2 pizzichi), niente aghi né rosmarino cosparso sopra.", "Patate, patate dolci e carote pelate e tagliate la sera prima (giovedì 29) e tenute in frigo coperte d'acqua fredda: venerdì la cena con i burger resta nei 45 minuti."], "verduraNascosta": {"verdure": ["carote", "patate dolci"], "grammiFamiglia": 700, "come": "Carote e patate dolci cotte a vapore e montate con le patate: un purè arancione, liscio e dolce.", "trucco": "Le carote spariscono nel colore della patata dolce, che è naturalmente dolce e ai bimbi piace molto; chiamalo 'purè arancione'."}, "lattosio": "no", "notaLattosio": "Solo olio extravergine, nessun latticino.", "notaBimbi": "Dolce e morbido, ideale per il bimbo di 1 anno; senza sale né pepe (si aggiungono solo nei piatti degli adulti).", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "carote", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "patate dolci", "qta": 500, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "patate", "qta": 500, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver servito i bimbi"}, {"nome": "rosmarino secco in polvere", "qta": 2, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}], "accompagnamentoConsigliato": "Bocconcini di pollo o tacchino, pesce al Varoma, polpette (un principale di carne o pesce)", "perche": "Purè senza lattosio molto votato, già pieno di verdure arancioni (700 g tra carote e patate dolci) e tutto a vapore nel Varoma.", "passiCompleti": true, "usataNelMese": true}, "r84848": {"id": "r84848", "fonte": "cookidoo", "titolo": "Nuggets di pollo", "url": "https://cookidoo.it/recipes/recipe/it-IT/r84848", "tm6": true, "valutazioneCookidoo": [4.8, 1135], "tempoMin": 40, "porzioniRicetta": "20 pezzi", "categoria": "carne_bianca", "ruolo": "principale", "cereale": "pane", "ingredientiOriginali": ["200 g di petto di pollo", "½ cucchiaino di sale", "½ cucchiaino di aglio in polvere", "2 fette di pane bianco in cassetta", "60 g di formaggio fresco spalmabile", "60 g di latte", "olio per frittura", "1 uovo", "50 g acqua", "100 g di pangrattato"], "passi": ["La sera prima (domenica 18, dopo la zuppa: circa 15 minuti) prepara l'impasto. Dividi 150 g di cavolfiore in cimette, pela 100 g di carote e tagliale a rondelle; taglia 400 g di petto di pollo a pezzi di 3 cm e 4 fette di pane in cassetta (100 g) a pezzi.", "Metti nel boccale pulito cavolfiore e carote: trita 5 sec./vel. 6 e riunisci sul fondo con la spatola.", "Aggiungi il pollo e, se vuoi, ½ cucchiaino di aglio in polvere, senza sale: trita 5 sec./vel. 7. Riunisci sul fondo con la spatola.", "Aggiungi il pane, 120 g di formaggio spalmabile senza lattosio, 60 g di latte senza lattosio e 40 g di pangrattato: frulla 10 sec./vel. 7.", "Controlla l'impasto con la spatola: deve essere morbido ma da poterlo formare con le mani. Se è molto molle aggiungi altri 20 g di pangrattato e mescola 10 sec./antiorario/vel. 4.", "Trasferisci l'impasto in una ciotola, copri bene e mettilo in frigo fino a domani sera.", "Il giorno dopo (lunedì) avvia prima il purè di verdure nel Bimby (ricetta a parte). Poi accendi il forno ventilato a 200°C e fodera una teglia grande con carta forno.", "Prepara la panatura: in una ciotola sbatti 2 uova con 100 g di acqua; in un piatto fondo metti 200 g di pangrattato.", "Con le mani inumidite forma circa 30 palline un po' più grandi di una noce e schiacciale a forma di nugget, spesse circa 1,5 cm.", "Passa ogni nugget nell'uovo e poi nel pangrattato, premendo bene, e disponilo sulla teglia senza sovrapporli.", "Spennella i nuggets con 30 g di olio e inforna a 200°C ventilato per 15-18 minuti, girandoli a metà cottura con una paletta.", "Controlla la cottura: fuori dorati e dentro non più rosa (aprine uno al centro della teglia). Se serve, lasciali ancora 2-3 minuti.", "Preleva le porzioni dei bimbi, senza sale né ketchup. Per il bimbo di 1 anno taglia i nuggets a strisce sottili e lasciali intiepidire; ai bimbi dai un cucchiaio di purè per intingere.", "Servi con il purè di verdure. Sale ed eventuale ketchup solo nei piatti degli adulti.", "Per il pranzo di domani metti da parte 1 porzione adulto (circa 7 nuggets) in un contenitore chiuso e, appena intiepidita, riponila in frigo. Domani scaldali 5-8 minuti in forno a 180°C o in padella, così tornano croccanti."], "modifiche": ["Raddoppiare la ricetta (400 g di pollo): circa 30 nuggets un po' più grandi, più veloci da formare e impanare.", "Aggiungere all'impasto 150 g di cavolfiore crudo e 100 g di carote tritati finissimi (5 sec./vel. 6) prima del pollo, e 40 g di pangrattato in più per assorbire l'umidità (altri 20 g se l'impasto resta molle).", "Formaggio spalmabile e latte nella versione senza lattosio; latte ridotto a 60 g (invece di 120 della dose doppia) perché le verdure crude portano già umidità e l'impasto deve restare facile da formare.", "Cuocere in forno a 200°C invece di friggere (più leggero per i bimbi e meno lavoro in settimana).", "Niente sale nell'impasto: si sala solo nei piatti degli adulti. Aglio in polvere dimezzato (½ cucchiaino per la dose doppia) e facoltativo.", "Impasto preparato la sera prima (domenica 18, dopo la zuppa) e tenuto in frigo coperto: lunedì il Bimby cuoce il purè mentre formi, impani e inforni i nuggets, e la cena sta nei 45 minuti."], "verduraNascosta": {"verdure": ["cavolfiore", "carote"], "grammiFamiglia": 250, "come": "Cavolfiore e carote crudi tritati finissimi e frullati con pollo, pane e formaggio: scompaiono nell'impasto rosato sotto la panatura.", "trucco": "La panatura dorata copre tutto; ketchup solo per gli adulti, ai bimbi un cucchiaio di purè per intingere. Con il purè di patate, cavolfiore e topinambur si superano i 400 g di verdura."}, "lattosio": "sostituito", "notaLattosio": "Formaggio spalmabile e latte senza lattosio; pangrattato senza latte.", "notaBimbi": "Per il bimbo di 1 anno tagliare i nuggets a strisce; cotti in forno sono morbidi e senza sale. Verificare che siano ben cotti al centro. Contengono uovo (panatura). Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo (usa pangrattato semplice, senza semi).", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 2, "ingredienti": [{"nome": "petto di pollo", "qta": 400, "unita": "g", "reparto": "carne", "dispensa": false, "nota": ""}, {"nome": "cavolfiore", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette crude"}, {"nome": "carote", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "pane in cassetta", "qta": 100, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "4 fette, senza latte (leggi l'etichetta)"}, {"nome": "formaggio spalmabile senza lattosio", "qta": 120, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "latte senza lattosio", "qta": 60, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "uova", "qta": 2, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": "per la panatura"}, {"nome": "pangrattato", "qta": 260, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "200 g panatura + 40 g impasto + 20 g se l'impasto resta molle"}, {"nome": "aglio in polvere", "qta": 0.5, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "facoltativo"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "per spennellare"}], "accompagnamentoConsigliato": "Purè di verdure (r54838: patate, cavolfiore e topinambur con latte e burro senza lattosio), che cuoce nel Bimby mentre formi e inforni i nuggets.", "perche": "I nuggets più votati di Cookidoo (4.8 su oltre 1100 recensioni), pronti in 40 minuti e perfetti per nascondere cavolfiore e carote.", "passiCompleti": true, "usataNelMese": true}, "r541643": {"id": "r541643", "fonte": "cookidoo", "titolo": "Crema di verdure e polpette di tacchino (TM6)", "url": "https://cookidoo.it/recipes/recipe/it-IT/r541643", "tm6": true, "valutazioneCookidoo": [4.7, 284], "tempoMin": 60, "porzioniRicetta": "4 porzioni", "categoria": "carne_bianca", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["400 g di petto di tacchino", "6 rametti di prezzemolo fresco, le foglioline lavate ed asciugate", "50 g di Parmigiano Reggiano", "½ spicchio di aglio", "1 uovo", "60 g di yogurt greco", "½ cucchiaino di sale", "1 pizzico di pepe nero macinato", "50 g di pane bianco", "60 g di cipolla", "1 spicchio di aglio", "30 g di olio extravergine di oliva", "500 g di verdure miste", "400 g di acqua", "1 cucchiaino di dado per brodo vegetale fatto in casa"], "passi": ["Tritare il tacchino: 5 sec./vel. 9, trasferire in una ciotola.", "Tritare prezzemolo, Parmigiano e aglio: Frullare/10 sec.", "Aggiungere tacchino, pane ammollato, uovo, yogurt (senza lattosio), sale e pepe: 10 sec./antiorario/vel. 4.", "Formare polpettine (Ø 2,5-3 cm) e sistemarle tra recipiente e vassoio del Varoma. Pulire il boccale.", "Tritare cipolla e aglio: 5 sec./vel. 5, aggiungere l'olio e insaporire 3 min./120°C/vel. 1.", "(mod.) Unire zucca, carote e cavolfiore a pezzi, 250 g di acqua e il dado; posizionare il Varoma e cuocere 30 min./Varoma/vel. 1.", "Togliere il Varoma e frullare 1 min. fino a crema densa.", "(mod.) Condire con la crema la pasta cotta in pentola, aggiungere Parmigiano e servire con le polpettine."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Erbe verdi (prezzemolo, basilico, erba cipollina) solo sui piatti degli adulti.", "Verdure miste = 200 g di zucca + 150 g di carote + 150 g di cavolfiore (arancio e bianco spariscono nella crema).", "Ridurre l'acqua a 250 g: si ottiene una crema densa da usare come sugo per 320 g di pasta corta cotta in pentola, invece di servirla come vellutata.", "Yogurt greco nella versione senza lattosio.", "Dado vegetale fatto in casa o iposodico; salare le porzioni adulte a parte.", "Tempo 60 minuti: meglio nel fine settimana o in una sera con più tempo."], "verduraNascosta": {"verdure": ["zucca", "carote", "cavolfiore", "cipolle"], "grammiFamiglia": 500, "come": "Le verdure cuociono sotto le polpette e vengono frullate in una crema arancione densa che condisce la pasta.", "trucco": "Presentarla come 'pasta cremosa arancione col formaggio' e mantecare con Parmigiano: niente pezzi, niente verde."}, "lattosio": "sostituito", "notaLattosio": "Yogurt greco senza lattosio; Parmigiano naturalmente senza lattosio.", "notaBimbi": "Polpettine a vapore molto morbide; per il bimbo di 1 anno tagliarle in 4. Pasta e crema dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "fesa di tacchino", "qta": 400, "unita": "g", "reparto": "carne", "dispensa": false, "nota": "petto di tacchino"}, {"nome": "prezzemolo", "qta": 10, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo sui piatti degli adulti"}, {"nome": "parmigiano reggiano", "qta": 70, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "50 g impasto + 20 g per mantecare"}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "uova", "qta": 1, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "yogurt greco senza lattosio", "qta": 60, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "pane", "qta": 50, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "raffermo"}, {"nome": "cipolle", "qta": 60, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "zucca", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "cavolfiore", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "fatto in casa o iposodico"}, {"nome": "pasta corta", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "cotta in pentola"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}], "accompagnamentoConsigliato": "Già completa: la crema di verdure fa da sugo alla pasta.", "perche": "Tra le ricette TM6 più apprezzate (4.7 su 284 recensioni): polpette e crema cuociono insieme, e usata come sugo la crema nasconde mezzo chilo di verdura.", "usataNelMese": false}, "r754585": {"id": "r754585", "fonte": "cookidoo", "titolo": "Straccetti di pollo con patate e carote", "url": "https://cookidoo.it/recipes/recipe/it-IT/r754585", "tm6": true, "valutazioneCookidoo": [4.7, 184], "tempoMin": 45, "porzioniRicetta": "4 porzioni", "categoria": "carne_bianca", "ruolo": "completo", "cereale": "patate", "ingredientiOriginali": ["20 g di erbe aromatiche", "½ spicchio di aglio", "3 pizzichi di sale", "2 pizzichi di pepe nero macinato", "80 g di pangrattato", "60 g di olio extravergine di oliva", "500 g di petto di pollo", "30 g di cipolla", "300 g di acqua", "200 g di polpa di pomodoro a pezzi", "300 g di patate", "150 g di carote"], "passi": ["Rivestire recipiente e vassoio del Varoma con carta forno bagnata e strizzata, lasciando libere le fessure.", "Frullare erbe aromatiche, aglio, sale, pepe, pangrattato e 30 g di olio: Frullare/15 sec.; trasferire in una ciotola.", "Passare gli straccetti di pollo nel pangrattato aromatico, distribuirli nel Varoma e irrorare d'olio.", "(mod.) Tritare cipolla, carote e zucca: 5 sec./vel. 5, aggiungere 30 g di olio e insaporire 3 min./120°C/vel. 1.", "(mod.) Unire 250 g di acqua, la polpa di pomodoro e un pizzico di sale; posizionare il cestello con le patate a cubetti (600 g), il Varoma e cuocere 25 min./Varoma/vel. 2.", "Togliere Varoma e cestello; (mod.) frullare la salsa 30 sec./vel. 8 fino a crema liscia.", "Servire straccetti e patate con la salsa arancione (patate schiacciate a purè per i bimbi)."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Erbe verdi (prezzemolo, basilico, erba cipollina) solo sui piatti degli adulti.", "Le carote non vanno nel cestello a pezzi ma nel boccale con la salsa, insieme a 200 g di zucca, e a fine cottura si frulla tutto: salsa vellutata arancio-rossa.", "Patate aumentate a 600 g (cubetti di 2 cm nel cestello) per avere la base di amido di tutta la famiglia.", "Pollo ridotto a 400 g (sufficiente per 2 adulti + pranzo + 2 bimbi).", "Acqua ridotta a 250 g per non riempire troppo il boccale; se le patate non stanno nel cestello cuocerne 150-200 g in pentola.", "Poco sale: salare a fine cottura le porzioni degli adulti."], "verduraNascosta": {"verdure": ["carote", "zucca", "cipolle"], "grammiFamiglia": 400, "come": "Carote e zucca cuociono nella salsa di pomodoro e vengono frullate: diventano un sugo liscio per il pollo impanato.", "trucco": "Servire la salsa come 'intingolo' per gli straccetti croccanti e le patate: arancio nel rosso non si nota."}, "lattosio": "no", "notaLattosio": "Nessun latticino.", "notaBimbi": "Straccetti morbidi al vapore: per il bimbo di 1 anno tagliarli a pezzetti piccoli e schiacciare le patate con la salsa. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "petto di pollo", "qta": 400, "unita": "g", "reparto": "carne", "dispensa": false, "nota": "a straccetti"}, {"nome": "prezzemolo", "qta": 10, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo sui piatti degli adulti"}, {"nome": "rosmarino", "qta": 5, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "erbe aromatiche"}, {"nome": "salvia", "qta": 5, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "erbe aromatiche"}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": "ne serve mezzo"}, {"nome": "pangrattato", "qta": 80, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 60, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "cipolle", "qta": 30, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "polpa di pomodoro", "qta": 200, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "patate", "qta": 600, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}], "accompagnamentoConsigliato": "Già completa (patate + pollo + salsa di verdure). Facoltativo: 1 fetta di pane a testa.", "perche": "Cena completa in un solo ciclo Bimby da 40-45 minuti, molto apprezzata (4.7 su 184 recensioni); impanatura croccante e salsa che nasconde 400 g di verdura.", "usataNelMese": false}, "r915633": {"id": "r915633", "fonte": "cookidoo", "titolo": "Bocconcini di pollo con crema di zucchine e riso basmati", "url": "https://cookidoo.it/recipes/recipe/it-IT/r915633", "tm6": true, "valutazioneCookidoo": [4.4, 165], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "carne_bianca", "ruolo": "completo", "cereale": "riso", "ingredientiOriginali": ["250 g di riso basmati", "50 g di cipolla", "45 g di olio extravergine di oliva", "100 g di patata", "350 g di zucchine", "4 foglie di basilico fresco", "550 g di acqua", "1 cucchiaino di dado per brodo vegetale", "10 g di sale", "1 pizzico di pepe nero macinato", "700 g di petto di pollo", "1 cucchiaino di paprika dolce", "2 cucchiai di farina tipo 00"], "passi": ["Prepara le verdure: sbuccia 50 g di cipolla e 100 g di patate e tagliale a pezzi. Pela 450 g di zucchine (peso già pelate) e tagliale a pezzi. Se non trovi più zucchine, usa 450 g di polpa di zucca.", "Taglia 400 g di petto di pollo a bocconcini di circa 2 cm.", "Metti nel boccale asciutto 30 g di Parmigiano Reggiano a pezzi: 10 sec./vel. 10. Trasferiscilo in una ciotolina e tienilo da parte.", "Posiziona il cestello nel boccale e pesaci 300 g di riso basmati. Toglilo con la spatola, sciacqua il riso sotto l'acqua fredda e tienilo da parte.", "Metti nel boccale la cipolla: 5 sec./vel. 5. Riunisci sul fondo con la spatola.", "Aggiungi 30 g di olio extravergine e insaporisci: 3 min./120°C/vel. 1.", "Unisci patate e zucchine (niente basilico): 6 sec./vel. 5. Riunisci sul fondo con la spatola.", "Aggiungi 650 g di acqua e 1 cucchiaino di dado vegetale senza sale, SENZA sale né pepe. Inserisci il cestello con il riso e chiudi con il coperchio (il livello resta sotto la tacca dei 2,2 L).", "In una ciotola condisci i bocconcini con 15 g di olio, ½ cucchiaino di curcuma e 2 cucchiai di farina, senza sale e senza erbe. Distribuiscili tra recipiente e vassoio del Varoma e chiudi con il coperchio.", "Posiziona il Varoma e cuoci: 20 min./Varoma/vel. 2. Il pollo deve essere bianco anche al centro e il riso tenero; se serve, altri 3 min./Varoma/vel. 2.", "Togli il Varoma e tieni il pollo coperto. Estrai il cestello con la spatola e versa il riso in una ciotola grande.", "Frulla la verdura rimasta nel boccale: 30 sec./vel. 5-10 aumentando gradualmente, con il misurino, fino a una crema liscia senza pezzetti.", "Versa la crema sul riso, aggiungi il Parmigiano grattugiato e mescola bene: diventa un risotto cremoso. Se è troppo denso, aggiungi 1-2 cucchiai di acqua calda.", "Preleva le porzioni dei bimbi, senza sale: riso cremoso e bocconcini. Per il bimbo di 1 anno taglia i bocconcini piccolissimi o sfilacciali con la forchetta e mescolali al riso; per il bimbo di 3 anni tagliali a pezzetti.", "Metti da parte 1 porzione adulto per il pranzo di domani (riso e bocconcini) in un contenitore ermetico: in frigo appena intiepidita, entro 1 ora; domani scaldala in padella con 2 cucchiai di acqua o al microonde, finché è ben calda. Poi servi gli adulti: sale e pepe solo nei loro piatti e, se piace, qualche ago di rosmarino tritato finissimo."], "modifiche": ["Togliere la paprika dolce (esclusa): usare ½ cucchiaino di curcuma. Niente erbe sul pollo: rosmarino tritato solo nei piatti degli adulti.", "Pollo ridotto da 700 g a 400 g; riso aumentato a 300 g con 650 g di acqua.", "Zucchine aumentate a 450 g (peso pelate) e sbucciate; basilico tolto: la crema resta chiarissima e non verde. Da metà ottobre, quando le zucchine finiscono, sostituirle con 450 g di zucca (come nella versione TM7 della stessa ricetta) oppure con 250 g di cavolfiore + 200 g di porri.", "Mescolare la crema direttamente nel riso con Parmigiano: diventa un 'risotto cremoso' e la verdura non si vede.", "Niente sale in cottura (né nell'acqua né sul pollo): riso, crema e pollo restano senza sale per i bimbi, gli adulti salano nel piatto. Solo 1 cucchiaino di dado vegetale senza sale aggiunto (non il dado Bimby classico).", "Controllare il livello: con 300 g di riso e 650 g di acqua nel boccale ci sono circa 1,3 kg più il cestello, sotto la tacca dei 2,2 L: non superarla."], "verduraNascosta": {"verdure": ["zucchine", "patate", "cipolle"], "grammiFamiglia": 450, "come": "Zucchine pelate e patata cuociono sotto il riso e vengono frullate in una crema liscia, poi mescolata al riso.", "trucco": "Con le zucchine pelate e la patata la crema è chiarissima: mescolata al riso con il Parmigiano sembra un risotto al formaggio. Con la zucca diventa un 'risotto giallo'."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano (naturalmente senza lattosio).", "notaBimbi": "Bocconcini cotti a vapore, teneri: per il bimbo di 1 anno tagliarli piccolissimi o sfilacciarli nel riso cremoso.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "riso basmati", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "cipolle", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 45, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "patate", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "zucchine", "qta": 450, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "le ultime di stagione; peso pelate: compra circa 520 g e sbucciale"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale aggiunto (non il dado Bimby classico)"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "petto di pollo", "qta": 400, "unita": "g", "reparto": "carne", "dispensa": false, "nota": "a bocconcini"}, {"nome": "curcuma", "qta": 0.5, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "al posto della paprika"}, {"nome": "farina 00", "qta": 2, "unita": "cucchiai", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "parmigiano reggiano", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "per mantecare"}, {"nome": "rosmarino", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "rametto, facoltativo, solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "Già completa (riso + pollo + crema di verdure).", "perche": "Piatto unico TM6 da 40 minuti in un solo ciclo (riso nel cestello, pollo nel Varoma, crema nel boccale), molto adatto alle sere feriali di inizio ottobre.", "passiCompleti": true, "usataNelMese": true}, "r109544": {"id": "r109544", "fonte": "cookidoo", "titolo": "Hamburger di pollo", "url": "https://cookidoo.it/recipes/recipe/it-IT/r109544", "tm6": true, "valutazioneCookidoo": [4.4, 30], "tempoMin": 40, "porzioniRicetta": "4 pezzi", "categoria": "carne_bianca", "ruolo": "principale", "cereale": "pane", "ingredientiOriginali": ["500 g di petto di pollo", "1 cucchiaio olio extravergine di oliva", "sale grosso"], "passi": ["(mod.) Mettere nel boccale carote, cavolfiore, Parmigiano e pangrattato: 5 sec./vel. 7.", "Aggiungere il petto di pollo a pezzi e tritare: 8 sec./vel. 10 (mod.: 8 sec./vel. 8 con le verdure).", "Formare gli hamburger con un coppapasta (6 da Ø 9 cm per gli adulti e 4 mini per i bimbi), compattando col dorso di un cucchiaio.", "Coprire e riporre in frigorifero 15-20 minuti.", "Ungere una padella antiaderente e cuocere a fuoco medio 5-6 minuti per lato, (mod.) fino a cottura completa.", "Spolverizzare con poco sale grosso (solo adulti) e servire nel panino morbido."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Pollo ridotto a 400 g (moltiplicatore 0,75).", "Aggiungere all'impasto 150 g di carote e 100 g di cavolfiore crudo tritati finissimi, più 30 g di Parmigiano e 30 g di pangrattato per legare.", "Cuocere il pollo sempre fino a cottura completa (non 'media' come indicato nella ricetta).", "Servire nei panini morbidi con un velo di ketchup: cena 'da fast food' fatta in casa."], "verduraNascosta": {"verdure": ["carote", "cavolfiore"], "grammiFamiglia": 250, "come": "Carote e cavolfiore crudi tritati finissimi e mescolati al pollo tritato nel boccale.", "trucco": "Nel panino con il ketchup nessuno guarda l'interno; con patate al forno o purè di patate e zucca si superano i 400 g di verdura."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano (naturalmente senza lattosio); verificare che i panini non contengano latte.", "notaBimbi": "Mini burger per i bimbi; per il bimbo di 1 anno sbriciolarlo o tagliarlo a pezzetti, con pane morbido senza crosta. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 0.75, "ingredienti": [{"nome": "petto di pollo", "qta": 400, "unita": "g", "reparto": "carne", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "cavolfiore", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette crude"}, {"nome": "parmigiano reggiano", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "pangrattato", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 15, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "sale grosso", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "panini morbidi per hamburger", "qta": 200, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "senza latte"}], "accompagnamentoConsigliato": "Patate al forno oppure purè di patate e zucca (500 g di patate + 200 g di zucca).", "perche": "Base semplicissima da arricchire con verdure tritate: i bimbi amano l'hamburger nel panino ed è pronto in 40 minuti.", "usataNelMese": false}, "c-pasta-ragu-bianco-pollo-verdure": {"id": "c-pasta-ragu-bianco-pollo-verdure", "fonte": "personalizzata", "titolo": "Pasta al ragù bianco di pollo con verdure nascoste", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 40, "porzioniRicetta": "famiglia (2 adulti + 1 porzione pranzo + 2 bimbi)", "categoria": "carne_bianca", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": [], "passi": ["Grattugia 40 g di Parmigiano Reggiano a pezzi nel boccale asciutto: 10 sec./vel. 10 e mettilo da parte in una ciotolina.", "Metti 380 g di petto di pollo a cubetti, ben freddo, nel boccale e trita Turbo/0,5 sec. 3-4 volte; trasferisci in una ciotola.", "Metti nel boccale 50 g di cipolla, 150 g di carote a pezzi e 50 g di sedano: trita 10 sec./vel. 8. Riunisci sul fondo con la spatola e ripeti 5 sec./vel. 8 per un trito finissimo.", "Aggiungi 30 g di olio extravergine di oliva e insaporisci: 5 min./120°C/vel. 1, con il cestello al posto del misurino.", "Aggiungi il pollo tritato e rosola: 5 min./120°C/antiorario/vel. 1, con il cestello al posto del misurino.", "Aggiungi 1 vaschetta di purea di zucca (200 g), 100 g di acqua, 1 cucchiaino di dado vegetale senza sale, 100 g di latte senza lattosio e 1 pizzico di noce moscata, senza sale: cuoci 20 min./100°C/antiorario/vel. 1, con il cestello al posto del misurino. Se a fine cottura è troppo liquido prosegui 3-5 min./Varoma/antiorario/vel. 1.", "Nel frattempo cuoci 320 g di pasta corta in pentola in acqua senza sale (per il bimbo di 1 anno pastina a parte, sempre senza sale): la pasta non sta nel boccale insieme al ragù.", "Condisci la pasta con il ragù e il Parmigiano grattugiato e preleva subito le porzioni dei bimbi.", "Solo nei piatti degli adulti: sale a piacere e, se ti piace, un pizzico di rosmarino fresco tritato. Servi."], "modifiche": ["Zucca: al posto dei 200 g di zucca cruda usa 1 vaschetta di purea di zucca (200 g, r507669) preparata domenica: si scioglie nel ragù e lo rende cremoso e dorato. Acqua ridotta a 100 g.", "Per un ragù ancora più 'invisibile': a fine cottura preleva metà del ragù, frullalo 10 sec./vel. 6 e rimescolalo al resto.", "Pollo: petto intero tritato nel Bimby al momento, non macinato comprato: si compra sabato e si usa lunedì, e il macinato di pollame va consumato entro circa 24 ore.", "Parmigiano grattugiato all'inizio, con il boccale ancora asciutto, e tenuto da parte fino al momento di condire.", "Rosmarino tolto dal trito del soffritto (niente puntini verdi per i bimbi): a piacere, tritato fresco solo sui piatti degli adulti.", "Nessun sale in cottura e al massimo 1 cucchiaino di dado vegetale senza sale.", "Acqua della pasta senza sale; gli adulti salano nel piatto."], "verduraNascosta": {"verdure": ["zucca", "carote", "sedano", "cipolle"], "grammiFamiglia": 450, "come": "1 vaschetta di purea di zucca (200 g) sciolta nel ragù bianco più un trito finissimo di carote, sedano e cipolla (250 g) cotto con il pollo.", "trucco": "La purea rende il ragù bianco dorato e cremoso, come se ci fosse più formaggio."}, "lattosio": "sostituito", "notaLattosio": "Latte senza lattosio; Parmigiano naturalmente senza lattosio. Si può usare solo acqua (lattosio 'no').", "notaBimbi": "Consistenza morbida adatta anche al bimbo di 1 anno (pastina o formato piccolo per lui, cotta in acqua senza sale). Ragù e pasta senza sale e senza rosmarino: sale e rosmarino solo nei piatti degli adulti, dopo aver servito i bimbi. Nessun allergene tra crostacei, molluschi, frutta a guscio o sesamo.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "petto di pollo", "qta": 380, "unita": "g", "reparto": "carne", "dispensa": false, "nota": "intero: lo trita il Bimby lunedì (passo 2); il macinato fresco non regge 2 giorni. Scegli una confezione che scada da lunedì 12 in poi"}, {"nome": "cipolle", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "sedano", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "rosmarino", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "facoltativo, solo adulti: qualche ago tritato fresco sul piatto"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale aggiunto (fatto in casa)"}, {"nome": "latte senza lattosio", "qta": 100, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "noce moscata", "qta": 1, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "pasta corta", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "cotta in pentola in acqua senza sale"}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "a pezzi, grattugiato nel Bimby all'inizio"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti, dopo aver servito i bimbi"}], "accompagnamentoConsigliato": "Già completa. Usa 1 vaschetta di purea di zucca (r507669).", "perche": "Su Cookidoo non c'è una pasta al pollo TM6 in italiano adatta (quelle cremose pollo-broccoli sono solo TM7): un ragù bianco è il modo più semplice per unire pasta, pollo e 450 g di verdura invisibile in 40 minuti.", "usataNelMese": true}, "r142970": {"id": "r142970", "fonte": "cookidoo", "titolo": "Frittata di spinaci al forno", "url": "https://cookidoo.it/recipes/recipe/it-IT/r142970", "tm6": true, "valutazioneCookidoo": [4.5, 398], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "uova", "ruolo": "completo", "cereale": "pane", "ingredientiOriginali": ["100 g di spinaci baby freschi", "40 g di cipollotto verde", "60 g Parmigiano reggiano grattugiato", "20 g di pangrattato", "1 pizzico di sale", "1 pizzico di pepe nero macinato", "6 uova"], "passi": ["Accendi il forno ventilato a 190°C e fodera con carta forno una teglia di circa 25x35 cm. Metti nel boccale 90 g di Parmigiano a pezzi: 10 sec./vel. 10 e trasferiscilo in una ciotola.", "Metti nel boccale 60 g di cipolla a pezzi: trita 3 sec./vel. 5. Aggiungi 350 g di spinaci freschi lavati e ben sgocciolati (in 2 volte se non entrano) e 10 g di olio: cuoci 8 min./120°C/vel. 1 senza misurino, per far evaporare l'acqua.", "Aggiungi il Parmigiano, 40 g di pangrattato e 9 uova, senza sale: frulla 30 sec./vel. 5 fino a un composto verde e liscio.", "Versa il composto nella teglia e livellalo.", "Cuoci in forno a 190°C per 20-25 minuti, finché il centro è ben rappreso (lo stecchino deve uscire asciutto).", "Lascia intiepidire 5 minuti e taglia a quadrotti. Servi con 190 g di pane: ai bimbi quadrotti senza sale, gli adulti salano e pepano nel piatto."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Ricetta x1,5 (9 uova) in una teglia di circa 25x35 cm: la frittata è più bassa e cuoce in 20-25 minuti.", "Verdura: spinaci portati a 350 g e 60 g di cipolla (al posto del cipollotto verde), stufati 8 minuti nel boccale prima di frullarli con le uova, così la frittata non diventa acquosa e non ha pezzi verdi.", "Pangrattato portato a 40 g.", "Niente sale nel composto (l'originale ne mette un pizzico): basta il Parmigiano; gli adulti salano nel piatto dopo aver servito i bimbi.", "Cena completa con 190 g di pane (nella lista della spesa): circa 40 minuti in tutto, senza lavoro anticipato."], "verduraNascosta": {"verdure": ["spinaci", "cipolle"], "grammiFamiglia": 410, "come": "Spinaci e cipolla stufati e frullati con uova e Parmigiano: la frittata è verde e uniforme, senza pezzi.", "trucco": "Chiamala 'frittata di Shrek' o 'torta verde' e tagliala a quadrotti o con le formine: si mangia con le mani, con il pane."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano, naturalmente senza lattosio.", "notaBimbi": "Uova ben cotte: il centro deve essere sodo. Per il bimbo di 1 anno quadrotti piccoli e morbidi e pane morbido senza crosta. Senza sale per entrambi i bimbi. Contiene uova e Parmigiano. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 3, "moltiplicatore": 1.5, "ingredienti": [{"nome": "spinaci", "qta": 350, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "freschi, baby o in foglie"}, {"nome": "cipolle", "qta": 60, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "parmigiano reggiano", "qta": 90, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "pangrattato", "qta": 40, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "uova", "qta": 9, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 10, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "pane", "qta": 190, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "Già completa con il pane (190 g, incluso negli ingredienti).", "perche": "Frittata al forno molto votata (4,5 su 398) in cui la verdura è già frullata nelle uova: in teglia bassa cuoce in 20-25 minuti e con il pane è una cena completa in circa 40 minuti.", "usataNelMese": false}, "r211966": {"id": "r211966", "fonte": "cookidoo", "titolo": "Frittata gusto pizza", "url": "https://cookidoo.it/recipes/recipe/it-IT/r211966", "tm6": true, "valutazioneCookidoo": [4.3, 162], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "uova", "ruolo": "principale", "cereale": "nessuno", "ingredientiOriginali": ["30 g di Parmigiano Reggiano", "6 uova", "50 g di latte intero", "1 pizzico di sale", "500 g acqua", "220 g di pomodorini", "170 g di mozzarella", "foglie di basilico fresche"], "passi": ["Prima prepara e inforna le patate al forno (ricetta abbinata): cuociono 35-40 minuti a 200°C sul ripiano basso. Il boccale resta pulito e asciutto per la frittata.", "Taglia 250 g di mozzarella senza lattosio a dadini e lasciala sgocciolare in un colino. Sbuccia 200 g di patate dolci e tagliale a pezzi.", "Fodera il recipiente e il vassoio del Varoma con carta forno bagnata e ben strizzata, senza coprire le aperture frontali del vassoio.", "Metti nel boccale 45 g di Parmigiano Reggiano a pezzi: 10 sec./vel. 10.", "Aggiungi le patate dolci: 10 sec./vel. 8. Riunisci sul fondo con la spatola.", "Aggiungi 9 uova e 75 g di latte senza lattosio, SENZA sale: 20 sec./vel. 5, fino a un composto liscio e dorato.", "Dividi il composto tra il recipiente e il vassoio del Varoma (due frittate sottili) e chiudi con il coperchio. Sciacqua il boccale.", "Metti nel boccale 600 g di acqua, posiziona il Varoma e cuoci: 22 min./Varoma/vel. 1. Le frittate devono essere rapprese anche al centro; se serve, altri 3 min./Varoma/vel. 1.", "Intanto scalda in un pentolino la vaschetta da 550 g di sugo base arancione (in frigo da domenica): 8-10 minuti a fuoco medio, mescolando, finché è bollente e un po' più denso. Fodera una teglia con carta forno.", "Togli il Varoma con attenzione e trasferisci le frittate sulla teglia, aiutandoti con la carta forno.", "Spalma il sugo caldo sulle frittate e distribuisci sopra la mozzarella ben sgocciolata. Niente sale né origano per ora.", "Passa il forno su grill: frittate sul ripiano alto per 5-7 minuti, finché la mozzarella fila. Le patate finiscono la cottura sul ripiano basso.", "Taglia le frittate a spicchi, come una pizza.", "Preleva le porzioni dei bimbi, senza sale né erbe, con le patate dell'angolo senza sale. Per il bimbo di 1 anno taglia lo spicchio a pezzetti piccoli e aspetta che la mozzarella sia tiepida e non più filante; schiaccia le patate con la forchetta.", "Metti da parte 1 porzione adulto per il pranzo di domani (spicchi e patate) in un contenitore ermetico: in frigo appena intiepidita; domani 5 minuti in forno a 180°C o in padella coperta. Poi servi gli adulti: sale, origano e qualche foglia di basilico solo sui loro spicchi."], "modifiche": ["Ricetta x1,5 (9 uova) cotta in due frittate sottili (vassoio + recipiente del Varoma).", "Sugo base: al posto dei pomodorini (e del sugo pizza con carote, cipolla, olio e passata) usa 550 g di sugo base arancione (r54703, la vaschetta in frigo da domenica), scaldato e addensato in un pentolino: contiene già circa 250 g di zucca, carote e cipolla frullate.", "Verdura in più nell'impasto: 200 g di patate dolci crude tritate 10 sec./vel. 8 e frullate con le uova 20 sec./vel. 5. Cuociono nei 22-25 minuti di vapore, hanno il colore dell'uovo e portano la cena a circa 450 g di verdura nascosta.", "Latte e mozzarella nella versione senza lattosio.", "Niente sale nell'impasto (Parmigiano e sugo bastano): sale, origano e basilico solo sugli spicchi degli adulti, dopo aver prelevato quelli dei bimbi.", "Frittate al vapore senza guarnizione; sugo caldo e mozzarella si aggiungono solo alla fine, 5-7 minuti sotto il grill.", "Accompagna con le patate al forno (c-patate-al-forno-rosmarino): infornale per prime; negli ultimi 5-7 minuti il forno passa al grill e gratina le frittate sul ripiano alto. Circa 45 minuti in tutto."], "verduraNascosta": {"verdure": ["zucca", "carote", "cipolle", "patate dolci"], "grammiFamiglia": 450, "come": "550 g di sugo base arancione (circa 250 g di zucca, carote e cipolla cotte nel pomodoro e frullate) spalmati come sugo pizza, più 200 g di patate dolci frullate crude nell'impasto delle uova e cotte al vapore.", "trucco": "Le patate dolci frullate hanno lo stesso colore dell'uovo e rendono la frittata più morbida; sopra, sugo rosso liscio e mozzarella filante: si mangia a spicchi come una pizza."}, "lattosio": "sostituito", "notaLattosio": "Latte e mozzarella senza lattosio; Parmigiano naturalmente senza lattosio.", "notaBimbi": "Uova al vapore ben cotte e morbide, impasto e sugo senza sale. Per il bimbo di 1 anno pezzetti piccoli e mozzarella tiepida (non filante bollente). Origano, basilico e sale solo sugli spicchi degli adulti.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 1.5, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 45, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "uova", "qta": 9, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "latte senza lattosio", "qta": 75, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "patate dolci", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso sbucciate, frullate nell'impasto"}, {"nome": "mozzarella senza lattosio", "qta": 250, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "origano", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "secco, solo sugli spicchi degli adulti"}, {"nome": "basilico", "qta": 5, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo sugli spicchi degli adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}], "accompagnamentoConsigliato": "c-patate-al-forno-rosmarino", "perche": "Gusto 'pizza' che i bimbi adorano: il sugo base di domenica fa da sugo pizza senza cucinare altro, le patate dolci spariscono nelle uova e la frittata al vapore è ben cotta e morbida.", "passiCompleti": true, "usataNelMese": true}, "r829420": {"id": "r829420", "fonte": "cookidoo", "titolo": "Muffin frittatine Parmigiano Reggiano e verdure", "url": "https://cookidoo.it/recipes/recipe/it-IT/r829420", "tm6": true, "valutazioneCookidoo": [4.5, 53], "tempoMin": 45, "porzioniRicetta": "12 pezzi", "categoria": "uova", "ruolo": "principale", "cereale": "nessuno", "ingredientiOriginali": ["olio extravergine di oliva", "100 g di Parmigiano Reggiano", "100 g pomodorini", "150 g di zucchine", "8 foglie di basilico fresco", "6 uova"], "passi": ["Preriscalda il forno a 180°C ventilato.", "Grattugia 100 g di Parmigiano a pezzi: 10 sec./vel. 10 e tienilo da parte.", "Metti nel boccale 200 g di polpa di zucca a pezzi, 150 g di carote a pezzi e 150 g di cimette di cavolfiore: trita 10 sec./vel. 7 e riunisci sul fondo con la spatola. Aggiungi 15 g di olio e stufa 10 min./120°C/vel. 1 senza misurino, finché le verdure sono morbide e asciutte (se attaccano al fondo aggiungi 2 cucchiai di acqua).", "Frulla 20 sec./vel. 5-8 aumentando gradualmente fino a una crema densa e liscia; lascia intiepidire 3-5 minuti a boccale aperto mentre ungi 18 stampi da muffin (2 teglie) con il resto dell'olio.", "Aggiungi 9 uova e il Parmigiano: 15 sec./vel. 4, fino a un composto arancio-dorato omogeneo, senza sale.", "Riempi gli stampi per 3/4 e cuoci 22-25 minuti su 2 ripiani (scambia le teglie a metà), finché i muffin sono gonfi, dorati e ben rappresi al centro: lo stecchino deve uscire asciutto.", "Fai intiepidire 5 minuti su una gratella. Servi i muffin dei bimbi così e sala leggermente solo quelli degli adulti, nel piatto."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Erbe verdi (prezzemolo, basilico, erba cipollina) solo sui piatti degli adulti.", "Ricetta x1,5 (9 uova, 18 muffin).", "Cucinata senza base della domenica: al posto di pomodorini, zucchine e basilico (fuori stagione e niente foglie verdi per i bimbi) 200 g di polpa di zucca cruda, 150 g di carote e 150 g di cavolfiore, tritati finissimi e stufati direttamente nel boccale (la zucca sostituisce la vaschetta di purea di zucca della versione con la base).", "Verdure stufate 10 min./120°C/vel. 1 senza misurino, così perdono l'acqua e i muffin non si bagnano, poi frullate in crema prima di aggiungere le uova: composto liscio, senza pezzetti.", "Parmigiano 100 g e nessun sale nell'impasto: gli adulti salano il loro muffin nel piatto. Niente pesto: senza frutta secca, adatti anche al bimbo di 1 anno.", "18 muffin cotti insieme su 2 teglie in forno ventilato (non in 2 infornate), per stare nei 45 minuti. Chiamali 'muffin dorati al formaggio'.", "Con il purè (c-pure-patate-cavolfiore) il Bimby serve due volte: per stare nei 45 minuti fai i passi 2-4 la sera prima (circa 15 minuti) e tieni in frigo, coperti, la crema di verdure e il Parmigiano. La sera della cena aggiungi le uova alla crema fredda (passo 5), inforna e, mentre i muffin cuociono, prepara il purè nel boccale sciacquato.", "Se nel mese la zucca compare già in molte cene, usa 200 g di patata dolce al posto della zucca: stesso colore e stessa cottura."], "verduraNascosta": {"verdure": ["zucca", "carote", "cavolfiore"], "grammiFamiglia": 500, "come": "200 g di zucca, 150 g di carote e 150 g di cavolfiore stufati e frullati in crema, poi montati con le uova: muffin arancio-dorati senza pezzetti.", "trucco": "Chiamali 'muffin dorati al formaggio': la forma da tortina e la crosticina di Parmigiano li fanno mangiare con le mani."}, "lattosio": "no", "notaLattosio": "Solo uova e Parmigiano Reggiano (naturalmente senza lattosio).", "notaBimbi": "Senza frutta secca e senza sale aggiunto: adatti anche al bimbo di 1 anno, tagliati a spicchi. Uova ben cotte: il centro deve essere rappreso. Nessun allergene tra quelli da segnalare (contengono uova e Parmigiano). Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.5, "ingredienti": [{"nome": "olio extravergine di oliva", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "15 g per stufare + un filo per gli stampi"}, {"nome": "parmigiano reggiano", "qta": 100, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa: compra circa il 40% in più (circa 280 g di zucca intera, delica o mantovana)"}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "cavolfiore", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette"}, {"nome": "uova", "qta": 9, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "c-pure-patate-cavolfiore", "perche": "Muffin di sola frittata (niente farina né latte) della sezione alimentazione infantile, da mangiare con le mani, con 500 g di verdura frullata dentro. Senza base della domenica: zucca, carote e cavolfiore si stufano direttamente nel boccale, in circa 45 minuti.", "usataNelMese": false}, "r91412": {"id": "r91412", "fonte": "cookidoo", "titolo": "Uova con purea profumata", "url": "https://cookidoo.it/recipes/recipe/it-IT/r91412", "tm6": true, "valutazioneCookidoo": [4.1, 78], "tempoMin": 45, "porzioniRicetta": "4 porzioni", "categoria": "uova", "ruolo": "completo", "cereale": "patate", "ingredientiOriginali": ["4 uova", "60 g di pancetta di maiale", "10 foglie di basilico fresco", "600 g di patate", "200 g di latte", "150 g di acqua", "1 pizzico di sale", "1 pizzico di pepe macinato fresco", "30 g di burro", "30 g di Parmigiano reggiano grattugiato"], "passi": ["La vaschetta 1 di besciamella al cavolfiore deve essere in frigo da ieri sera. Accendi il forno a 200°C e ungi con poco olio una pirofila di circa 25x30 cm.", "Metti nel boccale asciutto 30 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10. Trasferiscilo in una ciotolina e tienilo da parte.", "Mescola con una frusta la besciamella (circa 800 g) finché torna liscia; se resta granulosa frullala nel boccale 20 sec./vel. 5. Mettine 250 g in una ciotola: serviranno per il purè.", "Stendi il resto della besciamella (circa 550 g) nella pirofila, coprila con alluminio e infornala: si scalda mentre cuociono patate e uova.", "Pela 760 g di patate e tagliale a cubetti di 2 cm. Sciacqua il boccale.", "Ungi 8 stampini monoporzione con poco olio e rompi un uovo in ciascuno. Sistemali nel recipiente e nel vassoio del Varoma.", "Metti nel boccale le patate e 700 g di acqua, senza sale. Posiziona il Varoma chiuso con le uova e cuoci 22 min./Varoma/vel. 1.", "Quando al Bimby mancano 5 minuti togli l'alluminio dalla pirofila e porta il forno in modalità grill a 220°C.", "Togli il Varoma con attenzione: albume e tuorlo devono essere completamente rappresi, mai liquidi. Se non lo sono, rimetti il Varoma e cuoci ancora 3 min./Varoma/vel. 1.", "Scola le patate in un colino, tenendo da parte in una tazza 50 g di acqua di cottura.", "Rimetti le patate nel boccale, inserisci la farfalla e aggiungi i 250 g di besciamella e 1 pizzico di noce moscata: 30 sec./vel. 3,5. Poi scalda 2 min./90°C/vel. 2; se il purè è troppo denso aggiungi un po' di acqua di cottura.", "Togli la pirofila dal forno. Sulla besciamella calda distribuisci il purè a cucchiaiate formando 8 nidi e sforma un uovo al centro di ciascuno (passa un coltellino lungo il bordo dello stampino).", "Cospargi con il Parmigiano grattugiato e gratina 4-5 minuti sotto il grill, finché è dorato.", "Preleva le porzioni dei bimbi, senza sale. Per il bimbo di 1 anno schiaccia l'uovo con la forchetta, mescolalo al purè e alla besciamella e lascia intiepidire.", "Solo ora sala e pepa i piatti degli adulti e, a piacere, aggiungi qualche foglia di basilico spezzettata.", "Servi subito. Metti da parte 1 nido con l'uovo e un po' di besciamella per il pranzo di domani, in un contenitore chiuso in frigo: scaldalo al microonde coperto 2-3 minuti, finché è ben caldo."], "modifiche": ["Il cavolfiore arriva dalla besciamella al cavolfiore di domenica 25 (c-besciamella-cavolfiore-senza-lattosio): usa tutta la vaschetta 1, circa 800 g con 400 g di cavolfiore, congelata domenica e passata in frigo martedì 27 sera. 250 g mantecano il purè al posto di latte e burro; circa 550 g, scaldati in forno, fanno da letto cremoso per le uova gratinate. Dalla spesa sono tolti cavolfiore, latte e burro.", "Dosi per la famiglia: uova raddoppiate (8, in stampini al Varoma per 22 minuti più il grill, completamente rapprese) e patate portate da 600 a 760 g.", "Patate lessate in 700 g di acqua senza sale (non più in latte e acqua) e poi scolate: il purè si fa con la besciamella.", "Pancetta eliminata (niente salumi per i bimbi): uova, Parmigiano e besciamella bastano per una cena completa.", "Basilico non più tritato nel purè: solo fresco sui piatti degli adulti, a piacere (niente erbe verdi visibili per i bimbi).", "Finale gratinato: purè a nidi sulla besciamella calda, uovo al centro, 30 g di Parmigiano e 4-5 minuti di grill. La besciamella si scalda in forno mentre il Bimby cuoce patate e uova, così la cena resta nei 45 minuti.", "Niente sale né pepe in cottura: solo nei piatti degli adulti dopo aver servito i bimbi.", "Purè montato con la farfalla (30 sec./vel. 3,5) invece di schiacciarlo a vel. 4 senza farfalla, che lo renderebbe colloso."], "verduraNascosta": {"verdure": ["cavolfiore"], "grammiFamiglia": 400, "come": "Il cavolfiore è frullato nella besciamella di domenica (vaschetta 1, circa 800 g con 400 g di cavolfiore): 250 g mantecano il purè di patate, il resto fa da letto cremoso sotto le uova gratinate.", "trucco": "Bianco su bianco: sembra purè con la besciamella delle lasagne; noce moscata e Parmigiano gratinato coprono l'odore del cavolo. Chiamali 'nidi con l'uovo'."}, "lattosio": "sostituito", "notaLattosio": "La besciamella di base è fatta con latte e burro senza lattosio; Parmigiano Reggiano stagionato naturalmente senza lattosio.", "notaBimbi": "Uova cotte 22 minuti al Varoma e poi gratinate: tuorlo e albume completamente rappresi, mai tuorlo liquido; per il bimbo di 1 anno schiaccia l'uovo nel purè. Niente sale né pepe nei piatti dei bimbi (besciamella e purè sono senza sale); basilico solo sugli adulti. Nessun allergene della lista (contiene uovo, latte senza lattosio e il glutine della farina della besciamella).", "scongelare": "besciamella al cavolfiore, vaschetta 1 (circa 800 g): dal congelatore al frigo", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.3, "ingredienti": [{"nome": "uova", "qta": 8, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "patate", "qta": 760, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "farinose, da purè"}, {"nome": "parmigiano reggiano", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 10, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "per stampini e pirofila"}, {"nome": "noce moscata", "qta": 1, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "basilico", "qta": 5, "unita": "g", "reparto": "frutta_verdura", "dispensa": true, "nota": "facoltativo, solo sui piatti degli adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver servito i bimbi"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}], "accompagnamentoConsigliato": "Già completa (patate, uova e cavolfiore nascosto nella besciamella); a piacere una fetta di pane.", "perche": "Cena completa in 45 minuti: la besciamella al cavolfiore di domenica fa sia da purè cremoso sia da letto per le uova gratinate, quindi i 400 g di verdura sono già pronti e la sera restano solo patate e uova al Varoma.", "passiCompleti": true, "usataNelMese": true}, "r824055": {"id": "r824055", "fonte": "cookidoo", "titolo": "Rotolo di frittata", "url": "https://cookidoo.it/recipes/recipe/it-IT/r824055", "tm6": true, "valutazioneCookidoo": [4.1, 102], "tempoMin": 50, "porzioniRicetta": "4 porzioni", "categoria": "uova", "ruolo": "principale", "cereale": "nessuno", "ingredientiOriginali": ["15 g di Parmigiano Reggiano", "2 fili di erba cipollina fresca", "5 uova", "2 pizzichi di sale", "2 pizzichi di pepe nero macinato", "500 g di acqua", "80 g di provola", "80 g di prosciutto cotto"], "passi": ["(mod.) Mettere nel boccale zucca e carote a pezzi con 10 g di olio: 5 sec./vel. 5, poi 6 min./120°C/vel. 1 senza misurino.", "Aggiungere Parmigiano ed erba cipollina, uova, sale e pepe: 20 sec./vel. 6 (composto liscio).", "Foderare vassoio e recipiente del Varoma con carta forno bagnata e strizzata; dividere il composto tra i due.", "Mettere 600 g di acqua nel boccale, posizionare il Varoma e cuocere 5 min./Varoma/vel. 1.", "Disporre prosciutto cotto e mozzarella senza lattosio (al posto della provola) sulle frittate, richiudere e cuocere ancora 22-25 min./Varoma/vel. 1.", "Arrotolare ogni frittata dal lato lungo aiutandosi con la carta forno, chiudere a caramella e lasciare intiepidire.", "Tagliare a girelle e servire."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Erbe verdi (prezzemolo, basilico, erba cipollina) solo sui piatti degli adulti.", "Niente prosciutto cotto: per i bimbi niente insaccati (si può aggiungere solo nelle porzioni degli adulti).", "Ricetta x1,5 (8 uova) divisa in due rotoli (vassoio + recipiente del Varoma).", "Aggiungere 150 g di zucca e 100 g di carote stufate e frullate con le uova.", "Provola sostituita con mozzarella senza lattosio ben strizzata.", "Cottura portata a 27-30 minuti totali per avere le uova ben cotte."], "verduraNascosta": {"verdure": ["zucca", "carote"], "grammiFamiglia": 250, "come": "Le verdure stufate e frullate con le uova colorano la frittata in modo uniforme, senza pezzi.", "trucco": "Le girelle con prosciutto e formaggio filante sembrano 'sushi di frittata' e attirano i bimbi; con purè o patate si arriva a 400 g di verdura."}, "lattosio": "sostituito", "notaLattosio": "Mozzarella senza lattosio al posto della provola; Parmigiano naturalmente senza lattosio.", "notaBimbi": "Girelle morbide al vapore; per il bimbo di 1 anno tagliarle a pezzetti. Prosciutto cotto in piccola quantità. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.5, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 25, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "erba cipollina", "qta": 3, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo sui piatti degli adulti"}, {"nome": "uova", "qta": 8, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "zucca", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "carote", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 10, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "mozzarella senza lattosio", "qta": 120, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "al posto della provola"}], "accompagnamentoConsigliato": "Purè di patate e zucca o patate al forno, più pane (190 g).", "perche": "Rotolo al vapore senza forno, divertente da tagliare a girelle, che con la modifica nasconde 250 g di verdura nelle uova.", "usataNelMese": false}, "r761910": {"id": "r761910", "fonte": "cookidoo", "titolo": "Frittata di pasta avanzata", "url": "https://cookidoo.it/recipes/recipe/it-IT/r761910", "tm6": true, "valutazioneCookidoo": [4.7, 34], "tempoMin": 45, "porzioniRicetta": "4 porzioni", "categoria": "uova", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["60 g di Parmigiano Reggiano, a pezzi", "3 rametti di prezzemolo fresco, le foglioline lavate ed asciugate", "50 g di latte", "4 uova", "1 pizzico di sale", "1 pizzico di pepe nero macinato", "80 g di pancetta affumicata", "80 g di provola", "300 g di pasta", "20 g olio extravergine di oliva"], "passi": ["(mod.) Crema: tritare zucca, carote e cipolla 5 sec./vel. 5, aggiungere 10 g di olio e 100 g di acqua e cuocere 15 min./100°C/vel. 1; frullare 30 sec./vel. 8 e lasciare intiepidire in una ciotola. Intanto cuocere la pasta in pentola (o usare pasta avanzata).", "Grattugiare il Parmigiano: 10 sec./vel. 10.", "Aggiungere prezzemolo, latte senza lattosio, uova, sale, pepe e la crema di verdure: 20 sec./vel. 5.", "(mod.) Unire prosciutto cotto e mozzarella senza lattosio a dadini: 10 sec./antiorario/vel. 2; versare in una ciotola con la pasta scolata e mescolare.", "(mod.) Versare in una teglia 30x20 cm foderata e unta (o in 2 padelle da 24 cm come da ricetta).", "Cuocere in forno a 190°C per 25-30 minuti (in padella: 8-10 min per lato col coperchio) finché ben rappresa e dorata.", "Servire tiepida a quadrotti."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Erbe verdi (prezzemolo, basilico, erba cipollina) solo sui piatti degli adulti.", "Niente prosciutto cotto: per i bimbi niente insaccati (si può aggiungere solo nelle porzioni degli adulti).", "Ricetta raddoppiata: 8 uova e circa 600 g di pasta cotta (250 g di pasta secca).", "Aggiungere una crema di 250 g di zucca + 150 g di carote + 50 g di cipolla frullata con le uova: frittata 'arancione al formaggio'.", "Pancetta affumicata sostituita con prosciutto cotto; provola sostituita con mozzarella senza lattosio; latte senza lattosio.", "Cottura in forno in teglia grande (più comoda per la dose doppia).", "Ottima per riciclare la pasta in bianco avanzata della sera prima."], "verduraNascosta": {"verdure": ["zucca", "carote", "cipolle"], "grammiFamiglia": 450, "come": "Zucca e carote cotte e frullate in crema e mescolate al composto di uova che lega la pasta.", "trucco": "Il colore arancio sembra dato dal formaggio: presentarla come 'pasta al forno croccante' tagliata a quadrotti."}, "lattosio": "sostituito", "notaLattosio": "Latte e mozzarella senza lattosio; Parmigiano naturalmente senza lattosio.", "notaBimbi": "Quadrotti morbidi e ben cotti; per il bimbo di 1 anno usare un formato di pasta piccolo e tagliare a pezzetti. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 2, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 120, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "prezzemolo", "qta": 10, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo sui piatti degli adulti"}, {"nome": "latte senza lattosio", "qta": 100, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "uova", "qta": 8, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "mozzarella senza lattosio", "qta": 120, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "al posto della provola"}, {"nome": "pasta corta", "qta": 250, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "secca, circa 600 g da cotta; o pasta avanzata"}, {"nome": "olio extravergine di oliva", "qta": 40, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "zucca", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "cipolle", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}], "accompagnamentoConsigliato": "Già completa (pasta + uova + crema di verdure).", "perche": "Piatto unico molto amato dai bimbi (4.7 su 34), veloce e ottimo per riciclare la pasta; la crema arancione nasconde 450 g di verdura.", "usataNelMese": false}, "r632309": {"id": "r632309", "fonte": "cookidoo", "titolo": "Cottage pie col ragù di casa (pasticcio di carne e purè)", "url": "https://cookidoo.it/recipes/recipe/it-IT/r632309", "tm6": true, "valutazioneCookidoo": [4.2, 138], "tempoMin": 80, "porzioniRicetta": "4 porzioni", "categoria": "carne_rossa", "ruolo": "completo", "cereale": "patate", "ingredientiOriginali": ["100 g di cipolle", "30 g di burro", "450 g di carne trita di manzo", "½ - 1 cucchiaino di sale", "2 pizzichi di pepe nero macinato", "1 cucchiaio di vino di Madeira", "1000 g di patate a pasta farinosa", "1 cucchiaino di sale", "350 g di latte", "50 g di burro", "30 g di pangrattato"], "passi": ["Sera prima (circa 40 minuti): sposta in frigo il ragù di casa. Con la farfalla cuoci 800 g di patate a pezzi, 250 g di cimette di cavolfiore e 350 g di latte senza lattosio, senza sale: 30 min./95°C/vel. 1 con il cestello sul coperchio.", "Aggiungi 30 g di burro senza lattosio e monta: 30 sec./vel. 3. Metti il purè in un contenitore, lascia intiepidire, copri e tieni in frigo.", "Sera della cena: scalda il forno a 200°C e ungi una pirofila di circa 30x20 cm con poco burro senza lattosio o olio. Nel boccale asciutto grattugia 30 g di Parmigiano: 10 sec./vel. 10 e tieni da parte.", "Metti nel boccale 100 g di cipolle, 150 g di carote, 50 g di sedano e 150 g di polpa di zucca a pezzi: trita 10 sec./vel. 7 e riunisci sul fondo. Aggiungi 20 g di olio e insaporisci 5 min./120°C/vel. 1 senza misurino.", "Aggiungi 600 g di ragù classico di casa scongelato, 1 cucchiaio di concentrato di pomodoro e 100 g di passata, senza sale né vino: cuoci 10 min./100°C/antiorario/vel. 1 senza misurino, fino a un sugo morbido. Versa nella pirofila.", "Stendi sopra il purè a cucchiaiate, livellalo e rigalo con una forchetta; cospargi con il Parmigiano e 30 g di pangrattato.", "Inforna a 200°C per 20-25 minuti, finché la superficie è dorata e il ripieno bolle ai bordi; riposo 5 minuti.", "Preleva le porzioni dei bimbi; gli adulti salano e pepano nel piatto se serve."], "modifiche": ["Carne: al posto di 450 g di macinato di manzo, sale e Madeira usa 600 g di ragù classico di casa scongelato (la carne rossa del mese è solo il ragù di casa). Niente Madeira né altro alcol.", "Verdura nel ripieno: trita con le cipolle anche 150 g di carote, 50 g di sedano e 150 g di zucca: 10 sec./vel. 7; insaporisci 5 min./120°C/vel. 1 con 20 g di olio al posto del burro, poi cuoci 10 min./100°C/antiorario/vel. 1 con il ragù, 1 cucchiaio di concentrato di pomodoro e 100 g di passata (sugo morbido).", "Purè: 800 g di patate + 250 g di cimette di cavolfiore con 350 g di latte senza lattosio, 30 min./95°C/vel. 1 con la farfalla, senza sale; monta con 30 g di burro senza lattosio.", "In superficie 30 g di Parmigiano grattugiato e pangrattato al posto dei fiocchetti di burro; pirofila unta con burro senza lattosio o olio.", "Niente sale nel ripieno né nel purè (ragù di casa e Parmigiano sono già saporiti): gli adulti salano e pepano nel piatto dopo aver servito i bimbi.", "Per stare nei 45 minuti in una sera feriale: il purè si cuoce la sera prima (circa 40 minuti, passi 1-2) e si tiene in frigo; la sera della cena bastano ripieno, montaggio e 20-25 minuti di forno (circa 45 minuti). Il ragù passa in frigo la sera prima, insieme alla preparazione del purè."], "verduraNascosta": {"verdure": ["carote", "zucca", "sedano", "cipolle", "cavolfiore"], "grammiFamiglia": 700, "come": "Carote, zucca e sedano tritati finissimi e cotti nel ragù di casa col pomodoro; cavolfiore cotto con le patate e montato nel purè.", "trucco": "Bianco nel bianco: il cavolfiore sparisce nel purè; sotto la crosta dorata il ripieno sembra solo ragù."}, "lattosio": "sostituito", "notaLattosio": "Latte e burro senza lattosio; Parmigiano stagionato ok.", "notaBimbi": "Morbidissimo, ideale per il bimbo di 1 anno; lascia intiepidire la parte centrale che resta molto calda. Nessun sale aggiunto: il ragù di casa è già saporito. Se il tuo ragù contiene pancetta o salsiccia, ai bimbi dai più purè e meno ripieno. Nessun allergene tra quelli da segnalare.", "scongelare": "ragù classico di casa, circa 600 g", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "cipolle", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "sedano", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa: compra circa il 40% in più (circa 210 g di zucca intera)"}, {"nome": "olio extravergine di oliva", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "ragù classico di casa", "qta": 600, "unita": "g", "reparto": "surgelati", "dispensa": false, "casa": true, "nota": "dal tuo freezer"}, {"nome": "concentrato di pomodoro", "qta": 1, "unita": "cucchiai", "reparto": "dispensa", "dispensa": true, "nota": "1 tubetto basta per tutto il mese"}, {"nome": "passata di pomodoro", "qta": 100, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "patate", "qta": 800, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "a pasta farinosa"}, {"nome": "cavolfiore", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette"}, {"nome": "latte senza lattosio", "qta": 350, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "burro senza lattosio", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "30 g nel purè + pirofila"}, {"nome": "pangrattato", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "pepe nero", "qta": 1, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto, dopo aver servito i bimbi"}], "accompagnamentoConsigliato": "", "perche": "Ragù e purè in un'unica teglia: il formato 'nascondi-verdura' per eccellenza. Col ragù classico di casa al posto della carne fresca rispetta la regola 'carne rossa solo col ragù di casa', e con il purè cotto la sera prima sta nei 45 minuti.", "usataNelMese": false}, "r105730": {"id": "r105730", "fonte": "cookidoo", "titolo": "Risotto arancione con zucca e carota", "url": "https://cookidoo.it/recipes/recipe/it-IT/r105730", "tm6": true, "valutazioneCookidoo": [4.5, 370], "tempoMin": 35, "porzioniRicetta": "4 porzioni", "categoria": "formaggi", "ruolo": "completo", "cereale": "riso", "ingredientiOriginali": ["40 g di Parmigiano Reggiano", "200 g di polpa di zucca", "150 g di carote", "1 cucchiaino di foglie di salvia secca", "1 cucchiaino di sale", "20 g di olio extravergine di oliva", "40 g di burro", "320 g di riso Carnaroli", "100 g di vino bianco", "700 g acqua", "1 dado per brodo vegetale (dose per 0,5 l)"], "passi": ["Metti nel boccale 70 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10; tieni da parte.", "Metti nel boccale 250 g di polpa di zucca e 150 g di carote a pezzi: trita 10 sec./vel. 8. Aggiungi 20 g di olio e insaporisci 5 min./120°C/vel. 1; trasferisci il trito in una ciotola.", "Metti nel boccale 20 g di burro senza lattosio e 320 g di riso carnaroli: tosta 3 min./120°C/antiorario/vel. 1 senza misurino.", "Aggiungi 50 g di acqua (al posto del vino): 1 min./100°C/antiorario/vel. 1.", "Aggiungi il trito di verdure, 700 g di acqua calda e 1 cucchiaino raso di dado vegetale senza sale: cuoci 13 min./100°C/antiorario/vel. 1 con il cestello al posto del misurino; riposo 1 minuto. Niente sale.", "Manteca con il Parmigiano, 20 g di burro senza lattosio e 150 g di ricotta senza lattosio: 1 min./antiorario/vel. 1.", "Preleva le porzioni dei bimbi; gli adulti salano nel piatto se serve."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Zucca 250 g + carote 150 g tritate 10 sec./vel. 8 (invece di 5 sec./vel. 7): in cottura si sciolgono in una crema arancione.", "Burro → burro senza lattosio.", "Più proteine: Parmigiano 70 g e, a fine cottura, 150 g di ricotta senza lattosio (o stracchino senza lattosio) nella mantecatura.", "Vino → acqua, così il bimbo di 1 anno mangia la stessa cosa.", "Salvia eliminata (niente puntini verdi nel piatto dei bimbi); niente zenzero.", "Niente sale nel trito né in cottura; dado vegetale senza sale (1 cucchiaino raso): gli adulti salano nel piatto dopo aver servito i bimbi."], "verduraNascosta": {"verdure": ["zucca", "carote"], "grammiFamiglia": 400, "come": "Zucca e carote tritate finissime e cotte con il riso: si sciolgono nella crema del risotto.", "trucco": "Chiamalo 'risotto arancione del sole': il colore è tutto, non si vede nessun pezzo."}, "lattosio": "sostituito", "notaLattosio": "Burro e ricotta senza lattosio; Parmigiano stagionato ok.", "notaBimbi": "Consistenza cremosa perfetta per il bimbo di 1 anno; lascia intiepidire. Porzioni dei bimbi senza sale. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 70, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "burro senza lattosio", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "riso carnaroli", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "ricotta senza lattosio", "qta": 150, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "o stracchino senza lattosio"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale, 1 cucchiaino raso"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "", "perche": "Risotto veloce da sera feriale in cui zucca e carote diventano crema; con la ricotta diventa un piatto unico più proteico.", "usataNelMese": false}, "r54832": {"id": "r54832", "fonte": "cookidoo", "titolo": "Risotto alla parmigiana", "url": "https://cookidoo.it/recipes/recipe/it-IT/r54832", "tm6": true, "valutazioneCookidoo": [4.7, 1264], "tempoMin": 35, "porzioniRicetta": "4 porzioni", "categoria": "formaggi", "ruolo": "completo", "cereale": "riso", "ingredientiOriginali": ["40 g di Parmigiano Reggiano, a pezzi", "30 g di scalogno", "40 g di burro", "10 g di olio extravergine di oliva", "320 g di riso per risotto", "60 g di vino bianco secco", "820 g di acqua", "1 dado per brodo (dose per 0,5 l)", "½ - 1 cucchiaino di sale"], "passi": ["Grattugia 80 g di Parmigiano a pezzi: 10 sec./vel. 10 e tieni da parte.", "Metti nel boccale 100 g di porri (parte bianca) a rondelle e 300 g di cimette di cavolfiore: trita 10 sec./vel. 8 e riunisci sul fondo con la spatola.", "Aggiungi 20 g di burro senza lattosio e 10 g di olio: insaporisci 5 min./120°C/vel. 1 senza misurino.", "Aggiungi 320 g di riso carnaroli e tosta 3 min./120°C/antiorario/vel. 1 senza misurino; sfuma con 60 g di acqua (niente vino): 1 min./100°C/antiorario/vel. 1.", "Aggiungi 750 g di acqua e 1 cucchiaino raso di dado vegetale senza sale, niente sale: cuoci 13-14 min./100°C/antiorario/vel. 1 con il cestello sul coperchio al posto del misurino; riposo 1 minuto.", "Manteca con 20 g di burro senza lattosio e il Parmigiano, mescolando con la spatola, e servi subito: prima le porzioni dei bimbi.", "Facoltativo: nei piatti degli adulti mescola il prosciutto cotto a dadini piccoli; gli adulti salano nel piatto se serve."], "modifiche": ["Al posto dello scalogno trita 100 g di porri (parte bianca) e 300 g di cimette di cavolfiore: 10 sec./vel. 8; insaporisci 5 min./120°C/vel. 1 con burro e olio, poi tosta il riso.", "Riduci l'acqua a 750 g (le verdure rilasciano liquido) e cuoci 13-14 min.", "Burro → burro senza lattosio; Parmigiano 80 g invece di 40 g (più proteine).", "Facoltativo per un piatto più completo: 100 g di prosciutto cotto a dadini piccoli, solo nei piatti degli adulti.", "Vino → acqua; dado vegetale senza sale, max 1 cucchiaino; niente sale in cottura: gli adulti salano nel piatto dopo aver servito i bimbi."], "verduraNascosta": {"verdure": ["cavolfiore", "porri"], "grammiFamiglia": 400, "come": "Cavolfiore e porro tritati finissimi e cotti con il riso: si disfano nella crema del risotto bianco.", "trucco": "Bianco su bianco: sembra un normale risotto al Parmigiano, solo più cremoso."}, "lattosio": "sostituito", "notaLattosio": "Burro senza lattosio; Parmigiano stagionato naturalmente senza lattosio.", "notaBimbi": "Cremoso e morbido, adatto al bimbo di 1 anno. Nessun sale aggiunto (dado vegetale senza sale, max 1 cucchiaino). Prosciutto cotto solo nei piatti degli adulti. Nessun allergene tra quelli da segnalare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 80, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "porri", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "parte bianca"}, {"nome": "cavolfiore", "qta": 300, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette"}, {"nome": "burro senza lattosio", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 10, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "riso carnaroli", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale, max 1 cucchiaino"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto, dopo aver servito i bimbi"}, {"nome": "prosciutto cotto", "qta": 100, "unita": "g", "reparto": "carne", "dispensa": false, "nota": "facoltativo, solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "", "perche": "Il risotto più votato di Cookidoo diventa un 'risotto bianco' con 400 g di cavolfiore e porro invisibili, in 35 minuti.", "usataNelMese": false}, "r135477": {"id": "r135477", "fonte": "cookidoo", "titolo": "Pasta al forno veloce", "url": "https://cookidoo.it/recipes/recipe/it-IT/r135477", "tm6": true, "valutazioneCookidoo": [4.8, 1452], "tempoMin": 45, "porzioniRicetta": "6 porzioni", "categoria": "formaggi", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["150 g di Parmigiano Reggiano", "300 g di mozzarella", "2 pizzichi di pepe", "1 spicchio di aglio", "50 g di cipolla", "50 g di gambo di sedano", "50 g di carota", "60 g di olio extravergine di oliva", "600 g di polpa di pomodoro", "2 cucchiaini di sale", "500 g di acqua", "400 g di pasta secca"], "passi": ["Metti nel boccale 110 g di Parmigiano a pezzi e 250 g di mozzarella senza lattosio ben scolata: trita 10 sec./vel. 10 e tieni da parte.", "Metti nel boccale 40 g di cipolla, 40 g di sedano, 190 g di carote, 200 g di polpa di zucca e, se vuoi, 1 spicchio d'aglio: trita 10 sec./vel. 7.", "Aggiungi 45 g di olio e insaporisci 4 min./120°C/vel. 1 con il cestello al posto del misurino.", "Aggiungi 450 g di polpa di pomodoro, senza sale: cuoci 10 min./100°C/vel. 2; intanto scalda il forno a 250°C. Poi frulla 30 sec./vel. 8 fino a un sugo liscio.", "Aggiungi 425 g di acqua e porta a ebollizione 5 min./100°C/vel. 1.", "Aggiungi 300 g di pasta corta: cuoci 10 min./100°C/antiorario/vel. 1 (controlla la cottura); trasferisci in una pirofila e mescola con metà dei formaggi.", "Copri con i formaggi rimasti e gratina 10 minuti a 250°C.", "Lascia intiepidire 5 minuti; preleva le porzioni dei bimbi, poi gli adulti salano e pepano nel piatto."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Dose ×0,75 (pasta 300 g) per la famiglia.", "Soffritto con 190 g di carote e 200 g di zucca (sedano e cipolla 40 g), tritati 10 sec./vel. 7; dopo i 10 minuti di cottura del pomodoro il sugo si frulla 30 sec./vel. 8 PRIMA di aggiungere l'acqua.", "Acqua 425 g perché il sugo è più denso; controlla la cottura della pasta.", "Mozzarella → mozzarella senza lattosio ben scolata.", "Niente prosciutto né mortadella (niente insaccati per i bimbi): le proteine sono Parmigiano e mozzarella.", "Niente sale nel sugo né nella pasta e niente pepe nei formaggi: sale e pepe solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi; aglio facoltativo."], "verduraNascosta": {"verdure": ["carote", "zucca", "sedano", "cipolle"], "grammiFamiglia": 470, "come": "Carote e zucca cotte nel sugo di pomodoro e frullate prima di cuocerci dentro la pasta.", "trucco": "Arancio nel rosso: il sugo sembra solo pomodoro, e la crosta di formaggio fa il resto."}, "lattosio": "sostituito", "notaLattosio": "Mozzarella senza lattosio; Parmigiano stagionato ok.", "notaBimbi": "Pasta corta piccola (ditali, sedanini) per il bimbo di 1 anno; lascia intiepidire e taglia a pezzetti i fili di mozzarella. Porzioni dei bimbi senza sale. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 0.75, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 110, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "mozzarella senza lattosio", "qta": 250, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "2 da 125 g"}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": "facoltativo"}, {"nome": "cipolle", "qta": 40, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "sedano", "qta": 40, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 190, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "olio extravergine di oliva", "qta": 45, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "polpa di pomodoro", "qta": 450, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "pasta corta", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "", "perche": "Pasta al forno con la pasta cotta direttamente nel sugo del Bimby: 45 minuti, una sola pentola, voto 4,8 su quasi 1500 recensioni.", "usataNelMese": false}, "r337638": {"id": "r337638", "fonte": "cookidoo", "titolo": "Gnocchi alla sorrentina", "url": "https://cookidoo.it/recipes/recipe/it-IT/r337638", "tm6": true, "valutazioneCookidoo": [4.6, 218], "tempoMin": 85, "porzioniRicetta": "8 porzioni", "categoria": "formaggi", "ruolo": "completo", "cereale": "gnocchi", "ingredientiOriginali": ["100 g di Parmigiano Reggiano, a pezzi", "1000 g di acqua", "800 g di patate a pasta farinosa", "350 - 400 g di farina tipo 00", "60 g di uova", "½ - 1 cucchiaino di sale", "50 g di cipolla", "1 spicchio di aglio", "30 g di olio extravergine di oliva", "450 g di pomodori pelati", "1 cucchiaino raso di zucchero", "½ cucchiaino di sale", "5 foglie di basilico fresche", "8 fette di mozzarella"], "passi": ["Grattugia il Parmigiano: 15 sec./vel. 10.", "Acqua nel boccale e patate a fette nel Varoma: 30 min./Varoma/vel. 1; svuota il boccale.", "Frulla le patate con 50 g di farina 20 sec./vel. 5; aggiungi farina rimasta, uova, 50 g di Parmigiano e sale: 25 sec./vel. 3.", "Salsa: trita cipolla, aglio e olio 5 sec./vel. 7, insaporisci 3 min./120°C/vel. 1; aggiungi pelati, zucchero, sale e basilico e cuoci 20 min./100°C/vel. 1.", "Intanto forma gli gnocchi (rotolini Ø 2 cm tagliati a pezzi di 1,5 cm) e rigali con la forchetta.", "Lessa gli gnocchi in acqua salata finché affiorano; frulla la salsa 20 sec./vel. 7 e condisci.", "Distribuisci in tegamini con Parmigiano e mozzarella e gratina in forno a 200°C per 5 minuti."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Erbe verdi (prezzemolo, basilico, erba cipollina) solo sui piatti degli adulti.", "Dose ×0,75 (patate 600 g) per la famiglia; una pirofila unica invece di 8 tegamini.", "Salsa: trita con cipolla e aglio anche 150 g di carote e 250 g di zucca: 10 sec./vel. 7, insaporisci 5 min./120°C/vel. 1; usa 400 g di pelati (1 barattolo) + 100 g di passata e cuoci 25 min./100°C/vel. 1.", "Frulla la salsa 40 sec./vel. 8 (invece di 20 sec./vel. 7) per nascondere completamente le verdure.", "Mozzarella → mozzarella senza lattosio (circa 170 g).", "Gli gnocchi si possono preparare la domenica e congelare crudi su un vassoio infarinato: la sera si cuociono direttamente da congelati.", "Zucchero solo se il pomodoro è acido; sale ridotto, porzione bimbi prima di salare."], "verduraNascosta": {"verdure": ["zucca", "carote", "cipolle"], "grammiFamiglia": 440, "come": "Zucca e carote cotte nella salsa di pomodoro e frullate lisce.", "trucco": "La mozzarella filante e la salsa frullata rossa fanno sembrare tutto il classico piatto della nonna."}, "lattosio": "sostituito", "notaLattosio": "Mozzarella senza lattosio; Parmigiano stagionato ok.", "notaBimbi": "Gnocchi tagliati a metà per il bimbo di 1 anno; uovo ben cotto nell'impasto lessato. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 0.75, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 75, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "patate", "qta": 600, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "a pasta farinosa"}, {"nome": "farina 00", "qta": 280, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "più quella per la spianatoia"}, {"nome": "uova", "qta": 1, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "cipolle", "qta": 40, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": "facoltativo"}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "olio extravergine di oliva", "qta": 25, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "polpa di pomodoro", "qta": 400, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "1 barattolo"}, {"nome": "passata di pomodoro", "qta": 100, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "zucchero", "qta": 1, "unita": "pizzichi", "reparto": "dispensa", "dispensa": true, "nota": "facoltativo"}, {"nome": "basilico", "qta": null, "unita": "q.b.", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo sui piatti degli adulti"}, {"nome": "mozzarella senza lattosio", "qta": 170, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}], "accompagnamentoConsigliato": "", "perche": "Gnocchi gratinati con mozzarella filante, un classico da domenica che i bimbi adorano, con salsa frullata ricca di zucca e carote.", "usataNelMese": false}, "r48814": {"id": "r48814", "fonte": "cookidoo", "titolo": "Gattò di patate", "url": "https://cookidoo.it/recipes/recipe/it-IT/r48814", "tm6": true, "valutazioneCookidoo": [4.7, 1048], "tempoMin": 90, "porzioniRicetta": "6 porzioni", "categoria": "formaggi", "ruolo": "completo", "cereale": "patate", "ingredientiOriginali": ["100 g di Provolone", "100 g di Gruviera", "40 g di pecorino", "30 g di Parmigiano Reggiano", "1000 g di patate a pasta farinosa", "350 g di latte", "1 cucchiaino di sale", "30 g di burro", "1 pizzico di pepe nero macinato", "2 uova", "150 g di salame napoletano", "20 g di pangrattato"], "passi": ["Taglia a dadini 125 g di mozzarella senza lattosio e lasciala scolare in un colino. Rassoda 2 uova in un pentolino (9 minuti dal bollore), raffreddale e sbucciale.", "Grattugia pecorino e Parmigiano a pezzi: 10 sec./vel. 10 e tieni da parte. Trita 100 g di Gruviera a pezzi: Turbo 1 sec. per 3-4 volte e tienila da parte separata.", "Con la farfalla cuoci 800 g di patate a pezzi, 400 g di cimette di cavolfiore e 350 g di latte senza lattosio, senza sale: 30 min./95°C/vel. 1 con il cestello sul coperchio.", "Aggiungi 30 g di burro senza lattosio, i formaggi grattugiati (tienine da parte 2 cucchiai) e 1 pizzico di pepe: 30 sec./vel. 3; unisci 2 uova crude: 10 sec./vel. 3.", "In una pirofila di circa 30x20 cm unta con poco burro senza lattosio: metà purè, mozzarella senza lattosio a dadini e Gruviera, uova sode a fette, resto del purè. Il prosciutto cotto a dadini (facoltativo) va solo sulla parte degli adulti, circa 3/4 della pirofila: segna con uno stuzzicadenti il lato dei bimbi, senza prosciutto.", "Copri con il formaggio grattugiato tenuto da parte, 20 g di pangrattato e 10 g di burro senza lattosio a fiocchetti; forno statico già caldo a 180°C per 30 minuti, poi riposo 10-15 minuti.", "Preleva le porzioni dei bimbi dal lato senza prosciutto; gli adulti salano nel piatto se serve."], "modifiche": ["Patate 800 g + 400 g di cimette di cavolfiore cotti insieme nel latte senza lattosio, senza sale: 30 min./95°C/vel. 1 con la farfalla; il cavolfiore sparisce nel purè.", "Niente salame (insaccato, spesso piccante): al suo posto, facoltativo, 150 g di prosciutto cotto a dadini solo nella parte degli adulti; i bimbi hanno uova sode e formaggi.", "Provolone → mozzarella senza lattosio a dadini, ben asciutta; Gruviera, pecorino e Parmigiano stagionati sono naturalmente quasi privi di lattosio.", "Burro → burro senza lattosio; 2 uova sode a fette tra gli strati per più proteine.", "Niente sale nel purè (i formaggi sono già sapidi), pepe solo 1 pizzico: gli adulti salano nel piatto dopo aver servito i bimbi.", "Tempo: circa 90 minuti in tutto, quindi solo nel weekend o con il purè preparato la sera prima. Per una sera feriale: la sera prima fai i passi 1-5 (circa 45 minuti), copri la pirofila e tienila in frigo; la sera della cena accendi subito il forno a 200°C ventilato e inforna 30-35 minuti, finché è caldo al centro e dorato: circa 45 minuti in tutto, quasi tutti di forno."], "verduraNascosta": {"verdure": ["cavolfiore"], "grammiFamiglia": 400, "come": "Cavolfiore cotto con le patate nel latte e montato nel purè del gattò.", "trucco": "Bianco nel bianco con cuore filante: nessuno distingue il cavolfiore dalle patate."}, "lattosio": "sostituito", "notaLattosio": "Latte, burro e mozzarella senza lattosio; Gruviera, pecorino e Parmigiano stagionati ok.", "notaBimbi": "Morbido e filante, ottimo per il bimbo di 1 anno: taglia a pezzetti i fili di formaggio fuso. Uova sode ben cotte. Niente salumi per i bimbi: il prosciutto cotto (facoltativo) sta solo nella parte degli adulti. Nessun sale aggiunto. Nessun allergene tra quelli da segnalare (contiene uova e formaggi).", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "mozzarella senza lattosio", "qta": 125, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "ben asciutta, a dadini"}, {"nome": "gruviera", "qta": 100, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "pecorino", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "stagionato"}, {"nome": "parmigiano reggiano", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "patate", "qta": 800, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "a pasta farinosa"}, {"nome": "cavolfiore", "qta": 400, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette"}, {"nome": "latte senza lattosio", "qta": 350, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "burro senza lattosio", "qta": 45, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "30 g nel purè + pirofila + 10 g a fiocchetti"}, {"nome": "pepe nero", "qta": 1, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "uova", "qta": 4, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": "2 nell'impasto + 2 sode"}, {"nome": "prosciutto cotto", "qta": 150, "unita": "g", "reparto": "carne", "dispensa": false, "nota": "facoltativo, a dadini, solo nella parte degli adulti"}, {"nome": "pangrattato", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto, dopo aver servito i bimbi"}], "accompagnamentoConsigliato": "", "perche": "Il gattò napoletano con cuore filante è irresistibile per i bimbi e nasconde 400 g di cavolfiore nel purè. Dura circa 90 minuti: va bene nel weekend, oppure in settimana montandolo la sera prima e infornandolo la sera della cena.", "usataNelMese": false}, "c-mac-and-cheese-zucca-cavolfiore": {"id": "c-mac-and-cheese-zucca-cavolfiore", "fonte": "personalizzata", "titolo": "Mac and cheese arancione con zucca e cavolfiore (senza lattosio)", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 45, "porzioniRicetta": "4 porzioni (famiglia: 2 adulti + 1 porzione extra + 2 bimbi)", "categoria": "formaggi", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": [], "passi": ["Metti nel boccale 80 g di Parmigiano Reggiano e 100 g di Emmental a pezzi: 10 sec./vel. 10. Trasferisci in una ciotola e tieni da parte.", "Senza lavare il boccale metti 250 g di polpa di zucca e 200 g di cimette di cavolfiore a pezzi di 3 cm (già pulite e tagliate la sera prima, se puoi) e 20 g di olio extravergine di oliva: 8 sec./vel. 6. Riunisci sul fondo con la spatola.", "Insaporisci: 3 min./120°C/vel. 1.", "Aggiungi 400 g di latte senza lattosio, 300 g di acqua e 1 pizzico di noce moscata: cuoci 15 min./100°C/vel. 1 con il cestello al posto del misurino.", "Frulla: 1 min./vel. 5-9 aumentando gradualmente la velocità, con il misurino inserito, fino a ottenere una crema liscia arancione chiaro.", "Aggiungi 250 g di acqua bollente e 320 g di ditalini, mescola con la spatola e cuoci per il tempo indicato sulla confezione + 2 min./100°C/antiorario/vel. 1, con il cestello al posto del misurino. A metà cottura stacca la pasta dal fondo con la spatola; se la crema si asciuga troppo aggiungi 50-100 g di acqua calda.", "Aggiungi 2/3 dei formaggi grattugiati: 30 sec./antiorario/vel. 1. Lascia riposare 2 minuti a boccale chiuso: la salsa si addensa.", "Preleva le porzioni dei bimbi (senza sale), poi gli adulti salano nel piatto solo se serve (poco: i formaggi sono sapidi). Servi subito con il formaggio rimasto. Gratinatura facoltativa, fuori dai 45 minuti: versa in una pirofila, copri con il formaggio rimasto e 2 cucchiai di pangrattato e gratina 8-10 minuti sotto il grill a 220°C."], "modifiche": ["Per stare nei 45 minuti: la sera prima, dopo cena, pulisci la zucca (250 g di polpa) e taglia 200 g di cimette di cavolfiore e tienili in frigo in un contenitore; così la cena si fa in circa 40 minuti. La gratinatura è facoltativa (+10 minuti).", "Niente dado: latte e formaggi (Parmigiano ed Emmental) bastano a dare sapore e sono già sapidi.", "Boccale: il totale (circa 1,7 kg) sta nel TM6; non aumentare la dose oltre 350 g di pasta, altrimenti cuoci la pasta in pentola e condiscila con la crema."], "verduraNascosta": {"verdure": ["zucca", "cavolfiore"], "grammiFamiglia": 450, "come": "Zucca e cavolfiore cotti nel latte e frullati diventano la salsa al formaggio in cui cuoce la pasta.", "trucco": "Il colore arancio è quello del cheddar dei mac and cheese americani: per i bimbi è solo 'pasta al formaggio'."}, "lattosio": "sostituito", "notaLattosio": "Latte senza lattosio; Parmigiano ed Emmental stagionato (con 'naturalmente privo di lattosio' in etichetta) sono naturalmente senza lattosio.", "notaBimbi": "Pasta piccola (ditalini) comoda per il bimbo di 1 anno; porzione prelevata prima di salare, servita tiepida.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 80, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "emmental", "qta": 100, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "stagionato, con \"naturalmente privo di lattosio\" in etichetta (es. Emmentaler DOP)"}, {"nome": "zucca", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "cavolfiore", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette: 1 cavolfiore piccolo o 200 g di cimette surgelate"}, {"nome": "olio extravergine di oliva", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "latte senza lattosio", "qta": 400, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "noce moscata", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "1 pizzico"}, {"nome": "pasta corta", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "ditalini: formato piccolo, comodo per il bimbo di 1 anno"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto"}, {"nome": "pangrattato", "qta": 2, "unita": "cucchiai", "reparto": "dispensa", "dispensa": true, "nota": "facoltativo, per gratinare"}], "accompagnamentoConsigliato": "", "perche": "Cena feriale in 45 minuti (circa 40 con zucca e cavolfiore tagliati la sera prima) tutta nel boccale, gusto 'formaggioso' amato dai bimbi con 450 g di verdura invisibile; su Cookidoo i mac and cheese sono solo in inglese o spagnolo.", "usataNelMese": true}, "r433351": {"id": "r433351", "fonte": "cookidoo", "titolo": "Pasta risottata con crema di ceci, rosmarino e zafferano", "url": "https://cookidoo.it/recipes/recipe/it-IT/r433351", "tm6": true, "valutazioneCookidoo": [4.3, 555], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["370 g di ceci bianchi lessi", "2 rametti di rosmarino fresco, gli aghi lavati ed asciugati", "30 g olio extravergine di oliva", "630 g acqua", "1 bustina di zafferano in polvere", "2 cucchiaini di sale", "320 g di pasta secca tipo conchiglie"], "passi": ["Scola e sciacqua 570 g di ceci lessati e dividili: 380 g per la crema e 190 g in una ciotola a parte. Pela 200 g di carote e tagliale a pezzi.", "Metti nel boccale asciutto 40 g di Parmigiano Reggiano a pezzi: 10 sec./vel. 10. Trasferiscilo in una ciotolina.", "In un padellino scalda 30 g di olio con 1 rametto di rosmarino intero, 2 minuti a fuoco dolce. Togli e butta il rametto: resta il profumo, senza aghi verdi.", "Metti nel boccale le carote e l'olio al rosmarino: 5 sec./vel. 5. Riunisci sul fondo con la spatola.", "Aggiungi 100 g di acqua e cuoci: 10 min./100°C/vel. 1.", "Aggiungi la vaschetta di purea di zucca (200 g, in frigo da ieri sera) e i 380 g di ceci: 30 sec./vel. 5-8 aumentando gradualmente, fino a una crema liscia.", "Aggiungi 530 g di acqua e 1 bustina di zafferano, SENZA sale: 8 min./100°C/vel. 1.", "Unisci 320 g di pasta corta piccola e cuoci per i minuti indicati sulla confezione/100°C/antiorario/vel. 1, con il cestello sul coperchio al posto del misurino. Se diventa troppo densa, aggiungi 50-100 g di acqua calda dal foro del coperchio.", "Intanto schiaccia bene con una forchetta i 190 g di ceci tenuti da parte: interi sono pericolosi per i bimbi sotto i 4 anni.", "Versa la pasta in una ciotola grande, unisci i ceci schiacciati e il Parmigiano e mescola. Lascia riposare 2 minuti: diventa più cremosa.", "Preleva le porzioni dei bimbi, senza sale. Per il bimbo di 1 anno schiaccia un po' la pasta con la forchetta e controlla che non restino ceci interi.", "Metti da parte 1 porzione adulto per il pranzo di domani in un contenitore ermetico: in frigo appena intiepidita; domani scaldala in padella con 3-4 cucchiai di acqua, perché si addensa. Poi servi gli adulti: sale solo nei loro piatti."], "modifiche": ["Verdura: 1 vaschetta di purea di zucca (200 g, r507669) più 200 g di carote cotte e frullate nella crema di ceci (il giallo dello zafferano copre l'arancio).", "Ceci aumentati da 370 a 570 g (circa 2 lattine e mezzo sgocciolate) per la quota di legumi della famiglia: 380 g frullati nella crema e 190 g schiacciati con la forchetta e uniti alla fine.", "Rosmarino solo in infusione nell'olio (tolto prima di cuocere): profumo senza puntini verdi.", "Sale eliminato dalla cottura: gli adulti salano nel piatto.", "Mantecatura finale con 40 g di Parmigiano Reggiano (naturalmente senza lattosio), grattugiato all'inizio nel boccale asciutto.", "Acqua: 100 g per cuocere le carote più 530 g con lo zafferano (630 g, come l'originale). In cottura circa 1,8 kg: sta nel boccale da 2,2 L.", "Pasta di formato piccolo (conchigliette o ditalini) per tutti: cuoce dentro la crema, quindi non si può fare un formato diverso per il bimbo di 1 anno."], "verduraNascosta": {"verdure": ["zucca", "carote"], "grammiFamiglia": 400, "come": "1 vaschetta di purea di zucca e 200 g di carote cotte, frullate con i ceci in una crema gialla che cuoce insieme alla pasta.", "trucco": "Lo zafferano rende tutto giallo 'risotto': l'arancio di zucca e carote non si distingue."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano stagionato, naturalmente senza lattosio.", "notaBimbi": "Per entrambi i bimbi (sotto i 4 anni) i ceci interi sono schiacciati con la forchetta (rischio soffocamento); pasta di formato piccolo per tutti, per il bimbo di 1 anno schiacciala un po' con la forchetta. Niente sale in cottura (solo nei piatti degli adulti) e niente puntini di rosmarino. Nessun allergene tra crostacei, molluschi, frutta a guscio o sesamo.", "scongelare": "1 vaschetta di purea di zucca (200 g) dal congelatore: in frigo la sera prima", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "ceci lessati", "qta": 570, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "peso sgocciolato, circa 2 lattine e mezzo: per esempio 2 lattine da 400 g più 1 lattina piccola"}, {"nome": "carote", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "rosmarino", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "1 rametto intero, solo per profumare l'olio (poi si toglie)"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "zafferano", "qta": 1, "unita": "pz", "reparto": "spezie_condimenti", "dispensa": true, "nota": "bustina"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "pasta corta", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "conchigliette o ditalini (formato piccolo per tutti)"}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "a pezzi"}], "accompagnamentoConsigliato": "Già completa. Usa 1 vaschetta di purea di zucca (r507669).", "perche": "Piatto unico cremoso da 45 minuti per le sere feriali, in cui zucca e carote spariscono nella crema gialla allo zafferano.", "passiCompleti": true, "usataNelMese": true}, "r48901": {"id": "r48901", "fonte": "cookidoo", "titolo": "Pasta e fagioli", "url": "https://cookidoo.it/recipes/recipe/it-IT/r48901", "tm6": true, "valutazioneCookidoo": [4.8, 2167], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["1 scalogno", "30 g di pancetta di maiale", "1 rametto di rosmarino fresco", "50 g di olio extravergine di oliva", "30 g di carota", "30 g di sedano", "450 g di fagioli borlotti", "100 g di passata di pomodoro", "1000 g di acqua", "1 dado per brodo vegetale (dose per 0,5 l)", "200 g di pasta secca corta", "1 cucchiaio raso di sale", "2 pizzichi di pepe nero macinato", "4 cucchiai di Parmigiano Reggiano"], "passi": ["Metti nel boccale 40 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10; tieni da parte.", "Metti nel boccale 30 g di scalogno: trita 5 sec./vel. 7 e riunisci sul fondo. Aggiungi 40 g di olio e insaporisci 3 min./120°C/vel. 1.", "Unisci 100 g di carote, 30 g di sedano, 250 g di polpa di zucca a pezzi, 250 g di fagioli borlotti lessati e 120 g di passata: frulla 20 sec./vel. 7 fino a una crema liscia e riunisci sul fondo.", "Aggiungi 800 g di acqua e 1 cucchiaino raso di dado vegetale senza sale (se l'hai, anche una crosta di Parmigiano ben pulita): cuoci 20 min./100°C/vel. 1.", "Intanto cuoci 250 g di ditalini in pentola in acqua senza sale e scolali al dente.", "Aggiungi nel boccale i 300 g di fagioli rimasti: 2 min./100°C/antiorario/vel. 1. Togli la crosta di Parmigiano, versa la minestra in una zuppiera, unisci i ditalini e lascia riposare 5 minuti.", "Preleva le porzioni dei bimbi e, per entrambi, schiaccia con la forchetta i fagioli interi; gli adulti aggiungono sale, pepe e olio a crudo nel piatto. Servi con il Parmigiano grattugiato."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Pancetta e rosmarino eliminati (niente insaccati e niente aghi verdi nei piatti dei bimbi); per più sapore una crosta di Parmigiano ben pulita in cottura, da togliere prima di servire.", "Aggiunti 250 g di zucca e carote portate a 100 g, frullate con parte dei fagioli e la passata nella base.", "Fagioli portati da 450 a 550 g e pasta da 200 a 250 g per la famiglia.", "Acqua ridotta da 1250 a 800 g per restare nei 2,2 L del boccale (se si addensa troppo aggiungi acqua calda alla fine).", "Dado vegetale senza sale (1 cucchiaino raso); niente sale nell'acqua della pasta né in cottura: sale e pepe solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Ditalini cotti a parte in pentola e uniti nella zuppiera: nel boccale restano meno di 2 kg e la pasta non si gonfia dentro."], "verduraNascosta": {"verdure": ["zucca", "carote", "sedano", "scalogno"], "grammiFamiglia": 410, "come": "Zucca, carote e sedano vengono frullati crudi con parte dei fagioli e la passata: diventano la base cremosa della minestra.", "trucco": "Il colore mattone di fagioli e pomodoro copre l'arancio della zucca; servila ben cremosa con il Parmigiano sopra."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano, naturalmente senza lattosio.", "notaBimbi": "Per entrambi i bimbi (sotto i 4 anni) schiaccia i fagioli interi con la forchetta (rischio soffocamento); per il piccolo ditalini piccoli o frulla la sua porzione. Porzioni dei bimbi senza sale. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.25, "ingredienti": [{"nome": "scalogno", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "circa 30 g"}, {"nome": "olio extravergine di oliva", "qta": 50, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "40 g in cottura + un filo a crudo per gli adulti"}, {"nome": "carote", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "sedano", "qta": 30, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "fagioli borlotti lessati", "qta": 550, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "sgocciolati, oppure 190 g secchi lessati"}, {"nome": "passata di pomodoro", "qta": 120, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale, 1 cucchiaino raso"}, {"nome": "pasta corta", "qta": 250, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "ditalini"}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "", "perche": "La ricetta legumi più votata di Cookidoo (4,8 su oltre 2000 recensioni): minestra cremosa tutto-in-uno dove zucca e carote finiscono frullate nella base.", "usataNelMese": false}, "r803658": {"id": "r803658", "fonte": "cookidoo", "titolo": "Lasagne alle lenticchie", "url": "https://cookidoo.it/recipes/recipe/it-IT/r803658", "tm6": true, "valutazioneCookidoo": [4.8, 12], "tempoMin": 100, "porzioniRicetta": "6 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["70 g di Parmigiano reggiano", "200 g di carote", "200 g di sedano rapa", "80 g di cipolle", "2 spicchi di aglio", "20 g di olio di oliva", "200 g di acqua", "200 g di vino rosso", "1 scatola di polpa di pomodoro a pezzi", "200 g di lenticchie", "20 g di concentrato di pomodoro", "2 rametti di maggiorana fresca", "1 foglia di alloro secca", "1 ½ cucchiaino di sale", "4 pizzichi di pepe macinato", "750 g di latte intero", "50 g di burro, non salato", "70 g di farina", "1 cucchiaino di sale", "2 pizzichi di noce moscata in polvere", "12 pasta secca, tipo lasagna"], "passi": ["Grattugia il Parmigiano 10 sec./vel. 10 e tieni da parte.", "Trita carote, sedano rapa, cipolle e aglio 6 sec./vel. 5; aggiungi l'olio e cuoci 7 min./120°C/vel. 2 senza misurino.", "Aggiungi 200 g di acqua, 200 g di brodo vegetale (al posto del vino), polpa, lenticchie, concentrato, maggiorana e alloro: cuoci 35 min./100°C/antiorario/vel. 1 con il cestello sul coperchio. Togli le erbe, sala a fine cottura dopo aver tenuto da parte la porzione dei bimbi. Trasferisci e lava il boccale.", "(Modifica) Besciamella al cavolfiore: metti nel boccale 750 g di latte senza lattosio e 200 g di cimette di cavolfiore, cuoci 15 min./98°C/vel. 1, poi frulla 40 sec./vel. 9 aumentando gradualmente.", "Aggiungi farina, burro senza lattosio, sale e noce moscata: mescola 10 sec./vel. 5, poi cuoci 8 min./90°C/vel. 3 finché si addensa. Preriscalda il forno a 200°C.", "In una pirofila 20x30 cm alterna besciamella, sfoglie, ragù e besciamella; termina con besciamella e Parmigiano.", "Cuoci 35 min a 200°C e lascia riposare 5-10 min prima di tagliare."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Vino rosso sostituito con brodo vegetale iposodico", "Besciamella con latte e burro senza lattosio e con 200 g di cavolfiore frullato dentro", "Sale del ragù aggiunto a fine cottura dopo aver prelevato la porzione dei bimbi; pepe solo per adulti", "Ideale per sabato/domenica: gli avanzi sono perfetti per il pranzo del giorno dopo"], "verduraNascosta": {"verdure": ["carote", "sedano rapa", "cipolle", "cavolfiore"], "grammiFamiglia": 680, "come": "Carote, sedano rapa e cipolle sono tritati e cotti nel ragù di lenticchie; il cavolfiore è frullato nella besciamella.", "trucco": "Bianco nel bianco e arancio nel rosso: nessun pezzo visibile. Le lasagne sono 'piatto della festa', nessuno sospetta."}, "lattosio": "sostituito", "notaLattosio": "Latte e burro senza lattosio nella besciamella; Parmigiano naturalmente senza lattosio.", "notaBimbi": "Taglia a pezzetti e lascia intiepidire; per il bimbo di 1 anno prendi la parte centrale più morbida. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 70, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "sedano rapa", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito"}, {"nome": "cipolle", "qta": 80, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "aglio", "qta": 2, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "per 200 g di brodo al posto del vino"}, {"nome": "polpa di pomodoro", "qta": 400, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "1 scatola"}, {"nome": "lenticchie secche", "qta": 200, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "concentrato di pomodoro", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "1 tubetto basta per tutto il mese"}, {"nome": "maggiorana", "qta": 2, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "rametti freschi"}, {"nome": "alloro", "qta": 1, "unita": "pz", "reparto": "spezie_condimenti", "dispensa": true, "nota": "foglia"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "latte senza lattosio", "qta": 750, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "intero"}, {"nome": "burro senza lattosio", "qta": 50, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "farina 00", "qta": 70, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "noce moscata", "qta": 2, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "lasagne secche", "qta": 250, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "12 sfoglie"}, {"nome": "cavolfiore", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette"}], "accompagnamentoConsigliato": "", "perche": "Piatto della domenica che nasconde 680 g di verdure tra ragù e besciamella; gli avanzi coprono il pranzo del giorno dopo.", "usataNelMese": false}, "r735962": {"id": "r735962", "fonte": "cookidoo", "titolo": "Spaghettini al sugo con polpettine di lenticchie", "url": "https://cookidoo.it/recipes/recipe/it-IT/r735962", "tm6": true, "valutazioneCookidoo": [3.8, 4], "tempoMin": 30, "porzioniRicetta": "10 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["80 g di cipollotto", "150 g di sedano", "150 g di carota", "50 g olio extravergine di oliva", "300 g di lenticchie rosse", "530 g di acqua", "30 g di concentrato di pomodoro", "2 cucchiaini di sale", "4 uova", "200 g di pangrattato", "600 g di polpa di pomodoro a pezzi", "2 cucchiaini zucchero", "50 g di panna da cucina (18% di grassi circa)", "500 g di spaghettini", "60 g di peperone rosso", "2 - 3 olive nere denocciolate"], "passi": ["LA SERA PRIMA, dopo cena (circa 40 minuti). Pulisci e taglia a pezzi 30 g di cipolla, 60 g di sedano e 60 g di carote. Mettili nel boccale: 7 sec./vel. 5. Riunisci sul fondo con la spatola.", "Aggiungi 15 g di olio extravergine e insaporisci: 3 min./120°C/vel. 2.", "Unisci 225 g di lenticchie rosse sciacquate, 400 g di acqua e 20 g di concentrato di pomodoro, SENZA sale: 13 min./98°C/antiorario/vel. 2.", "Aggiungi 75 g di pangrattato e 1 uovo: 30 sec./antiorario/vel. 4. Mescola bene con la spatola: l'impasto è morbido ma si modella.", "Trasferisci l'impasto in una ciotola larga e fallo raffreddare 10 minuti in congelatore. Intanto lava il boccale.", "Prepara la panatura: sbatti 2 uova in un piatto fondo e metti 75 g di pangrattato in un piatto piano.", "Con le mani umide forma 18-20 polpette da circa 45 g (Ø 4 cm). Passale prima nell'uovo e poi nel pangrattato.", "Metti le polpette crude su un vassoio, coprile con pellicola e tienile in frigo fino alla sera dopo.", "LA SERA DELLA CENA. Accendi il forno ventilato a 200°C e fodera una teglia con carta forno unta con 10 g di olio. Metti sul fuoco una pentola d'acqua per la pasta, SENZA sale.", "Disponi le polpette sulla teglia e cuocile in forno a 200°C per 20 minuti, girandole a metà, finché sono dorate e ben calde al centro.", "Intanto metti nel boccale la vaschetta da 870 g di sugo base arancione (in frigo da domenica) e 40 g di panna senza lattosio (facoltativa): 8 min./100°C/vel. 1.", "Cuoci 320 g di spaghettini nell'acqua senza sale per il tempo indicato sulla confezione e scolali.", "Condisci gli spaghettini con il sugo caldo e aggiungi le polpette.", "Preleva le porzioni dei bimbi, senza sale. Per il bimbo di 1 anno taglia gli spaghettini corti con le forbici e le polpette a pezzetti; per il bimbo di 3 anni taglia le polpette in quattro.", "Metti da parte 1 porzione adulto per il pranzo di domani (spaghettini con sugo e 4-5 polpette) in un contenitore ermetico: in frigo appena intiepidita; domani scaldala in padella con 2-3 cucchiai di acqua. Poi servi gli adulti: sale e pepe solo nei loro piatti."], "modifiche": ["Dose a 0,75 (la ricetta da 10 porzioni è pensata per porzioni piccole): lenticchie rosse 225 g, pasta 320 g.", "Sugo base: il sugo della ricetta (trito, zucca, polpa e zucchero) è sostituito da 1 vaschetta di sugo base arancione (r54703, circa 870 g), scaldata con la panna senza lattosio.", "Il trito serve solo per le polpettine: 30 g di cipolla, 60 g di sedano e 60 g di carote tritati 7 sec./vel. 5 e insaporiti con 15 g di olio.", "Polpette cotte in forno (200°C, 20 minuti, girate a metà) invece che fritte; panna da cucina sostituita con panna senza lattosio (o eliminata).", "Eliminata la decorazione con peperone rosso; olive facoltative e tagliate finissime.", "Niente sale nell'impasto né nell'acqua: sale e pepe solo sui piatti degli adulti.", "Polpette pronte dalla sera prima (impasto, forma e panatura dopo cena, circa 40 minuti: 3 di soffritto, 13 di cottura, 10 in congelatore, poi formatura e doppia panatura; poi crude in frigo): la sera della cena solo 20 minuti di forno mentre scaldi il sugo e cuoci gli spaghettini (circa 30 minuti).", "Formato: l'impasto pesa circa 850 g, quindi 18-20 polpette da circa 45 g (Ø 4 cm)."], "verduraNascosta": {"verdure": ["zucca", "carote", "cipolle", "sedano"], "grammiFamiglia": 550, "come": "1 vaschetta di sugo base (400 g di zucca, carote e cipolla frullate) per condire, più 150 g di cipolla, sedano e carote tritati dentro le polpettine di lenticchie.", "trucco": "Le polpettine dorate sembrano di carne e il sugo è liscio come una passata."}, "lattosio": "sostituito", "notaLattosio": "Solo panna senza lattosio (facoltativa); nessun altro latticino.", "notaBimbi": "Per il bimbo di 1 anno spezza gli spaghettini e taglia le polpette a pezzetti; sono morbide. Uova ben cotte in forno. Impasto, sugo e acqua della pasta senza sale: sale e pepe solo sui piatti degli adulti.", "scongelare": "nulla dal freezer (il sugo base da 870 g è già in frigo da domenica); dopo cena prepara e impana le polpettine di lenticchie per domani (passi 1-4, circa 40 minuti) e tienile crude in frigo, coperte", "gradimentoBimbiStimato": 5, "moltiplicatore": 0.75, "ingredienti": [{"nome": "cipolle", "qta": 30, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "sedano", "qta": 60, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 60, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 25, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "15 g nel trito + 10 g per ungere la teglia"}, {"nome": "lenticchie rosse decorticate", "qta": 225, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "secche"}, {"nome": "concentrato di pomodoro", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "1 tubetto basta per tutto il mese"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, al piatto"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto"}, {"nome": "uova", "qta": 3, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": "1 nell'impasto, 2 per la panatura"}, {"nome": "pangrattato", "qta": 150, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "75 g nell'impasto + 75 g per la panatura"}, {"nome": "panna senza lattosio", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "facoltativa"}, {"nome": "spaghetti", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "spaghettini"}], "accompagnamentoConsigliato": "Già completa. Usa 1 vaschetta di sugo base arancione (r54703).", "perche": "Spaghetti con polpette al sugo, il piatto che piace di più ai bimbi, con lenticchie e 430 g di verdure tutte nascoste; poche recensioni ma è una ricetta Cookidoo pensata per i bambini.", "passiCompleti": true, "usataNelMese": true}, "r710519": {"id": "r710519", "fonte": "cookidoo", "titolo": "Polpette di lenticchie rosse e carote con salsa schug", "url": "https://cookidoo.it/recipes/recipe/it-IT/r710519", "tm6": true, "valutazioneCookidoo": [4.5, 239], "tempoMin": 40, "porzioniRicetta": "12 pezzi", "categoria": "legumi", "ruolo": "principale", "cereale": "nessuno", "ingredientiOriginali": ["1 cucchiaino di semi di cumino", "1 cucchiaino di semi di cardamomo", "1 cucchiaino di pepe nero in grani", "3 spicchi di aglio", "2 peperoncini verdi freschi", "4 rametti di coriandolo fresco", "10 rametti di prezzemolo fresco, le foglioline lavate ed asciugate", "40 g di succo di limone, spremuto fresco", "60 g di olio di oliva", "½ cucchiaino di sale", "65 g di Parmigiano Reggiano", "350 g di carote", "1 spicchio di aglio", "3 rametti di prezzemolo fresco, le foglioline lavate ed asciugate", "80 g di scalogno", "20 g di olio di oliva", "340 g di lenticchie rosse", "120 g di pangrattato", "2 uova", "½ cucchiaino di sale", "½ cucchiaino di pepe nero macinato", "½ cucchiaino di cumino in polvere", "olio di arachidi"], "passi": ["Salta completamente la salsa schug (contiene peperoncini). Preriscalda il forno a 200°C e fodera una teglia.", "Grattugia il Parmigiano 10 sec./vel. 10 e tieni da parte.", "Trita carote, aglio, prezzemolo e scalogno 3-5 sec./vel. 7 (in 2 volte se il boccale è pieno). Riunisci sul fondo.", "Aggiungi 30 g di olio e insaporisci 5 min./120°C/vel. 1.", "Unisci lenticchie lessate sgocciolate, pangrattato, Parmigiano, uova, sale e 1 pizzico di cumino: mescola 10 sec./vel. 5 (in 2 volte se serve).", "Con le mani umide forma 18 polpette (o 30 più piccole per i bimbi), schiacciale leggermente, passale nel pangrattato e disponile in teglia; spennellale d'olio.", "Cuoci in forno 20-25 min a 200°C girandole a metà (invece di friggerle)."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Erbe verdi (prezzemolo, basilico, erba cipollina) solo sui piatti degli adulti.", "Eliminata la salsa schug (peperoncini verdi, coriandolo, cardamomo)", "Cumino ridotto a un pizzico, niente pepe per i bimbi", "Dose 1,5x per la famiglia; con lenticchie già lessate (in scatola) si sta nei 40 minuti", "Cottura al forno invece della frittura in olio di arachidi", "Servire con salsa allo yogurt senza lattosio o ketchup al posto dello schug"], "verduraNascosta": {"verdure": ["carote", "scalogno"], "grammiFamiglia": 620, "come": "Mezzo chilo di carote tritate finissime e rosolate diventa la base dell'impasto insieme alle lenticchie.", "trucco": "Impanale nel pangrattato: la crosticina dorata nasconde l'arancio; chiamale 'crocchette'."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano, naturalmente senza lattosio.", "notaBimbi": "Per il bimbo di 1 anno fai polpette piccole e morbide e tagliale a pezzetti; puoi lasciare il cumino fuori dalla sua porzione. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.5, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 100, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 500, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "prezzemolo", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo sui piatti degli adulti"}, {"nome": "scalogno", "qta": 120, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 60, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "30 per rosolare, 30 per spennellare"}, {"nome": "lenticchie lessate", "qta": 510, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "in scatola sgocciolate, oppure 255 g di lenticchie rosse secche lessate"}, {"nome": "pangrattato", "qta": 220, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "180 nell'impasto, 40 per la panatura"}, {"nome": "uova", "qta": 3, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "cumino", "qta": 1, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": "in polvere, facoltativo"}], "accompagnamentoConsigliato": "Pane (circa 190 g) oppure patate al forno o purè (circa 760 g di patate); salsa allo yogurt senza lattosio facoltativa", "perche": "Polpette molto votate (4,5 su 239) in cui l'ingrediente principale dopo le lenticchie sono 500 g di carote, del tutto nascoste nell'impasto.", "usataNelMese": false}, "r65221": {"id": "r65221", "fonte": "cookidoo", "titolo": "Zuppa di lenticchie e zucca", "url": "https://cookidoo.it/recipes/recipe/it-IT/r65221", "tm6": true, "valutazioneCookidoo": [4.4, 487], "tempoMin": 45, "porzioniRicetta": "6 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "pane", "ingredientiOriginali": ["1 cucchiaino di semi di cumino", "1 cipolla bianca", "1 spicchio di aglio", "20 g di olio extravergine di oliva", "1000 g di acqua", "1 cucchiaio di dado per brodo vegetale", "500 g di zucca", "1 cucchiaino raso di sale", "200 g di lenticchie rosse, secche", "pepe"], "passi": ["Metti nel boccale 30 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10; tieni da parte. Facoltativo: polverizza 1 pizzico di semi di cumino 10 sec./vel. 8 (oppure omettilo).", "Aggiungi 100 g di cipolla, 1 spicchio d'aglio, 150 g di carote a pezzi e 20 g di olio: trita 5 sec./vel. 7, riunisci sul fondo e insaporisci 5 min./120°C/vel. 1.", "Unisci 900 g di acqua, 1 cucchiaino raso di dado vegetale senza sale e 500 g di polpa di zucca a pezzi: cuoci 20 min./100°C/antiorario/vel. 1. Niente sale.", "Aggiungi 200 g di lenticchie rosse decorticate sciacquate: cuoci 12-15 min./100°C/antiorario/vel. 1. Intanto tosta 190 g di pane a cubetti in forno o in padella, senza sale.", "Frulla 40 sec./vel. 5-8 aumentando gradualmente: diventa una vellutata liscia.", "Preleva le porzioni dei bimbi (al piccolo pane morbido ammollato nella crema al posto dei crostini); gli adulti salano e pepano nel piatto. Servi con i crostini e il Parmigiano grattugiato."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Frullata a fine cottura per ottenere una crema liscia, senza pezzi visibili.", "Aggiunti 150 g di carote.", "Cumino ridotto a un pizzico o eliminato, pepe solo per gli adulti.", "Acqua ridotta a 900 g per una crema più densa.", "Servita con crostini di pane (190 g) tostati senza sale e Parmigiano per completare il pasto.", "Dado ridotto da 1 cucchiaio a 1 cucchiaino raso di dado vegetale senza sale; niente sale in cottura: gli adulti salano nel piatto dopo aver prelevato le porzioni dei bimbi."], "verduraNascosta": {"verdure": ["zucca", "carote", "cipolle"], "grammiFamiglia": 750, "come": "Zucca, carote e cipolla cuociono con le lenticchie rosse e vengono frullate in una crema arancione.", "trucco": "Crostini croccanti da 'pescare' e Parmigiano sopra: per i bimbi è la 'zuppa arancione con i crostini'."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano a piacere, naturalmente senza lattosio.", "notaBimbi": "Perfetta per il bimbo di 1 anno: crema morbida con pane morbido ammollato (i crostini croccanti solo per il bimbo di 3 anni e gli adulti). Lenticchie completamente frullate. Porzioni dei bimbi senza sale. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 3, "moltiplicatore": 1, "ingredienti": [{"nome": "cumino", "qta": 1, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": "semi, facoltativo"}, {"nome": "cipolle", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "1 cipolla bianca"}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale, 1 cucchiaino raso"}, {"nome": "zucca", "qta": 500, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "lenticchie rosse decorticate", "qta": 200, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "secche"}, {"nome": "pane", "qta": 190, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "per i crostini, tostati senza sale"}, {"nome": "parmigiano reggiano", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "", "perche": "Vellutata veloce (45 min) e molto votata, con 750 g di verdure e lenticchie rosse che si sciolgono; completa con i crostini.", "usataNelMese": false}, "r67902": {"id": "r67902", "fonte": "cookidoo", "titolo": "Pasta e piselli", "url": "https://cookidoo.it/recipes/recipe/it-IT/r67902", "tm6": true, "valutazioneCookidoo": [4.7, 739], "tempoMin": 35, "porzioniRicetta": "4 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["30 g di Parmigiano Reggiano", "30 g di olio extravergine di oliva", "30 g di cipolla", "100 g di pancetta di maiale", "350 g di piselli surgelati", "700 g di acqua", "1 cucchiaino di sale", "1 cucchiaio di dado per brodo vegetale", "350 g di pasta tipo ditalini", "1 pizzico di pepe"], "passi": ["Il giorno prima (mercoledì sera) sposta dal congelatore al frigo la vaschetta B di crema di broccoli e porri (circa 850 g). Stasera tienila a portata di mano.", "Metti sul fuoco una pentola con circa 3 litri di acqua per la pasta, senza sale, e copri.", "Nel boccale asciutto grattugia 50 g di Parmigiano a pezzi: 10 sec./vel. 10. Trasferiscilo in una ciotolina.", "Metti nel boccale 30 g di olio e 50 g di cipolla a pezzi: trita 5 sec./vel. 7 e riunisci sul fondo con la spatola.", "Insaporisci 3 min./120°C/vel. 1 (niente pancetta).", "Aggiungi 500 g di piselli surgelati (non serve scongelarli), 250 g di acqua e ½ cucchiaino di dado vegetale senza sale, senza sale: cuoci 12 min./100°C/vel. 1.", "Aggiungi la crema della vaschetta B e scalda 4 min./90°C/vel. 1.", "Intanto, quando l'acqua della pentola bolle, butta 320 g di ditalini e cuocili per il tempo indicato sulla confezione.", "Finito il riscaldamento, con il misurino inserito frulla 40 sec./vel. 5-8 aumentando gradualmente: crema verde liscia, senza piselli interi.", "Scola la pasta tenendo da parte un mestolo di acqua di cottura e rimettila nella pentola.", "Versa nella pentola la crema verde e il Parmigiano e mescola 1 minuto a fuoco basso. Se è troppo densa allunga con l'acqua di cottura.", "Preleva le porzioni dei bimbi, senza prosciutto e senza sale. Per il bimbo di 1 anno controlla che i ditalini siano ben morbidi (se serve schiacciali un po' con la forchetta) e lascia intiepidire.", "Solo adesso unisci nella pentola 100 g di prosciutto cotto a cubetti, sala e pepa la pasta degli adulti e mescola.", "Servi subito. Per il pranzo di domani metti da parte 1 porzione adulto in un contenitore chiuso e, appena intiepidita, riponila in frigo; si addensa, scaldala con qualche cucchiaio di acqua."], "modifiche": ["Base della domenica: usa la vaschetta B di crema di broccoli e porri (r399588, circa 850 g, con circa 680 g di broccoli, porri e spinaci) al posto dei porri e degli spinaci freschi: si scalda con i piselli cotti e si frulla tutto insieme.", "Piselli frullati in crema con la base invece di lasciarli interi (niente palline verdi visibili).", "Pancetta sostituita con 100 g di prosciutto cotto a cubetti, solo nei piatti degli adulti: si unisce dopo aver prelevato le porzioni dei bimbi (niente salumi ai bimbi).", "Piselli aumentati a 500 g, pasta ridotta a 320 g, Parmigiano 50 g.", "Pasta cotta in pentola invece che nel boccale: nel boccale restano circa 1,7 kg (soffritto, piselli, acqua e crema della base), con la pasta e la sua acqua si supererebbero i 2,2 kg.", "Niente sale nella cottura né nell'acqua della pasta e solo ½ cucchiaino di dado senza sale (un po' di dado c'è già nella base): si sala solo dopo aver prelevato le porzioni dei bimbi."], "verduraNascosta": {"verdure": ["broccoli", "porri", "spinaci", "cipolle"], "grammiFamiglia": 730, "come": "La vaschetta B di crema di broccoli, porri e spinaci (circa 680 g di verdura) si scalda con i piselli cotti e la cipolla e si frulla: diventa la crema verde che condisce i ditalini.", "trucco": "Verde nel verde: chiamala 'pasta di Hulk' e completa con il Parmigiano; i cubetti di prosciutto cotto vanno solo agli adulti."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano, naturalmente senza lattosio.", "notaBimbi": "Crema liscia (piselli frullati, nessun legume intero) e ditalini piccoli, adatta al bimbo di 1 anno. Niente prosciutto ai bimbi: si unisce solo alla pasta degli adulti dopo aver prelevato le porzioni dei bimbi, prima di sale e pepe. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo.", "scongelare": "crema di broccoli e porri, vaschetta B (circa 850 g): dal congelatore al frigo", "gradimentoBimbiStimato": 3, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 50, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "cipolle", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "piselli surgelati", "qta": 500, "unita": "g", "reparto": "surgelati", "dispensa": false, "nota": "non serve scongelarli"}, {"nome": "dado vegetale", "qta": 0.5, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale"}, {"nome": "pasta corta", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "ditalini"}, {"nome": "prosciutto cotto", "qta": 100, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "a cubetti, senza polifosfati (banco frigo); solo adulti"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver prelevato le porzioni dei bimbi"}], "accompagnamentoConsigliato": "Piatto unico.", "perche": "Cena di legumi veloce (35 minuti) e molto votata (4,7 su 739): con la crema di broccoli della domenica frullata insieme ai piselli diventa una pasta cremosa che nasconde circa 700 g di verdure verdi.", "passiCompleti": true, "usataNelMese": true}, "c-gnocchi-zucca-ceci": {"id": "c-gnocchi-zucca-ceci", "fonte": "personalizzata", "titolo": "Gnocchi di zucca e farina di ceci al sugo di pomodoro e carote", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 70, "porzioniRicetta": "famiglia (circa 4 porzioni adulto)", "categoria": "legumi", "ruolo": "completo", "cereale": "gnocchi", "ingredientiOriginali": [], "passi": ["Metti nel boccale 50 g di Parmigiano Reggiano a pezzi e grattugia: 10 sec./vel. 10. Trasferisci in una ciotola.", "Metti nel boccale 500 g di acqua. Posiziona il recipiente del Varoma con 600 g di zucca pulita a cubetti di 2 cm e il vassoio con 400 g di patate pelate a fette di 1 cm. Chiudi e cuoci: 30 min./Varoma/vel. 1.", "Togli il Varoma, apri il coperchio e lascia intiepidire 10 minuti perché zucca e patate perdano umidità (serve a non aggiungere troppa farina). Svuota e asciuga il boccale.", "Metti nel boccale zucca e patate: schiaccia 10 sec./vel. 4. Aggiungi 180 g di farina di ceci, 150 g di farina 00, 30 g di Parmigiano grattugiato, 1 uovo e 2 pizzichi di noce moscata: impasta 1 min./modalità Impasto (spiga). L'impasto deve essere morbido ma non appiccicoso: se serve aggiungi farina 00 a cucchiaiate e impasta 20 sec./spiga.", "Trasferisci su una spianatoia ben infarinata, forma cilindri di Ø 2 cm e taglia tocchetti di 2 cm. Disponili su un vassoio infarinato senza sovrapporli (si possono congelare crudi sul vassoio e poi passarli in un sacchetto).", "Lava il boccale. Metti 150 g di carote e 50 g di cipolla a pezzi: trita 5 sec./vel. 5. Riunisci sul fondo, aggiungi 30 g di olio extravergine di oliva e insaporisci: 3 min./120°C/vel. 1.", "Aggiungi 500 g di passata di pomodoro e 4 foglie di basilico: cuoci 15 min./100°C/vel. 1 con il cestello al posto del misurino. Frulla 30 sec./vel. 8 aumentando gradualmente per un sugo liscio. Preleva la porzione dei bimbi, poi sala il resto con ½ cucchiaino di sale.", "Intanto porta a bollore una pentola capiente di acqua SENZA sale e cuoci gli gnocchi in 2-3 volte, scolandoli con una schiumarola 1 minuto dopo che sono venuti a galla.", "Condisci gli gnocchi dei bimbi con il sugo senza sale prelevato prima e quelli degli adulti con il sugo salato; completa con i restanti 20 g di Parmigiano. Servi subito."], "modifiche": ["Acqua degli gnocchi senza sale: il sale va solo nel sugo degli adulti, dopo aver prelevato quello dei bimbi."], "verduraNascosta": {"verdure": ["zucca", "carote", "cipolle"], "grammiFamiglia": 800, "come": "La zucca è dentro l'impasto degli gnocchi (che diventano arancioni); carote e cipolla sono frullate nel sugo di pomodoro.", "trucco": "Gnocchi arancioni in sugo rosso sembrano normali gnocchi al pomodoro; fai aiutare i bimbi a tagliare i tocchetti."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano, naturalmente senza lattosio.", "notaBimbi": "Gnocchi morbidi, perfetti per il bimbo di 1 anno (tagliali a metà); l'uovo cuoce bene nell'acqua bollente. Acqua degli gnocchi senza sale e sugo dei bimbi prelevato prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 50, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 600, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "patate", "qta": 400, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "a pasta farinosa"}, {"nome": "farina di ceci", "qta": 180, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "farina 00", "qta": 200, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "150 nell'impasto, il resto per la spianatoia"}, {"nome": "uova", "qta": 1, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "noce moscata", "qta": 2, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "cipolle", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "passata di pomodoro", "qta": 500, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "basilico", "qta": 3, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "4 foglie"}, {"nome": "sale fino", "qta": 0.5, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nel sugo degli adulti, dopo aver prelevato quello dei bimbi"}], "accompagnamentoConsigliato": "", "perche": "Copre la voce 'gnocchi colorati' con un legume (180 g di farina di ceci), dato che le ricette Cookidoo di gnocchi di ceci hanno voti bassi (2,8-3,5); ottimi per il weekend e si congelano.", "usataNelMese": true}, "r212042": {"id": "r212042", "fonte": "cookidoo", "titolo": "Polpette di merluzzo con salsa di pomodoro all'acciuga", "url": "https://cookidoo.it/recipes/recipe/it-IT/r212042", "tm6": true, "valutazioneCookidoo": [4.3, 329], "tempoMin": 60, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["40 g di pane", "40 g di latte", "6 rametti di prezzemolo fresco", "2 pezzi di scorza di limone", "400 g di filetti di merluzzo", "1 uovo", "1 ½ cucchiaino di sale", "20 g olio extravergine di oliva", "1 spicchio di aglio", "50 g di cipolla", "3 - 4 filetti di acciuga sott'olio", "600 g di passata di pomodoro"], "passi": ["Ammolla il pane nel latte in una ciotola e tieni da parte.", "Trita prezzemolo e scorza di limone: 5 sec./vel. 8.", "Aggiungi merluzzo, uovo, ½ cucchiaino di sale e pane strizzato: 10 sec./vel. 6.", "Con le mani unte forma 12 polpette (Ø 4 cm) e disponile nel recipiente del Varoma unto.", "Trita aglio, cipolla, olio e acciughe: 5 sec./vel. 7.", "Aggiungi la passata e 1 cucchiaino di sale, posiziona il Varoma e cuoci 20 min./Varoma/vel. 1.", "Servi le polpette calde irrorate con la salsa."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Erbe verdi (prezzemolo, basilico, erba cipollina) solo sui piatti degli adulti.", "Ricetta x1,5: 600 g di merluzzo, 18 polpette piccole (Ø 3-4 cm) distribuite tra recipiente e vassoio del Varoma; cottura allungata a 25 min./Varoma/vel. 1.", "Niente acciughe (troppo sapide per il bimbo di 1 anno): nel boccale solo aglio e cipolla.", "Verdura nell'impasto: trita 100 g di carota insieme a prezzemolo e scorza di limone (10 sec./vel. 8) prima di aggiungere il merluzzo.", "Verdura nel sugo: trita con aglio e cipolla 200 g di carote e 200 g di polpa di zucca (10 sec./vel. 7), soffriggi con l'olio 5 min./120°C/vel. 1, poi aggiungi la passata; tolto il Varoma, frulla la salsa 30 sec./vel. 4-8 progressivo con il misurino inserito.", "Latte senza lattosio per ammollare il pane.", "Per la cena completa cuoci 300 g di pasta corta in pentola e condiscila con metà del sugo; le polpette si servono con il resto.", "Sale ridotto: ½ cucchiaino nell'impasto e 1 cucchiaino nel sugo in tutto; gli adulti aggiustano a tavola."], "verduraNascosta": {"verdure": ["carote", "zucca", "cipolle"], "grammiFamiglia": 580, "come": "100 g di carota tritata finissima nell'impasto delle polpette; 200 g di carote e 200 g di zucca cotte nel sugo e frullate con la passata.", "trucco": "Carota e zucca sono arancioni come il pomodoro: frullate rendono il sugo solo più dolce e vellutato, e le polpette sono coperte di salsa."}, "lattosio": "sostituito", "notaLattosio": "Solo il latte per ammollare il pane, in versione senza lattosio; parmigiano facoltativo sulla pasta (naturalmente senza lattosio).", "notaBimbi": "Polpette cotte al vapore e morbide: per il bimbo di 1 anno sbriciolale; controlla le lische del merluzzo passando le dita sui filetti prima di frullarli. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "filetti di merluzzo surgelati (600 g): in frigo la sera prima", "gradimentoBimbiStimato": 5, "moltiplicatore": 1.5, "ingredienti": [{"nome": "merluzzo filetti", "qta": 600, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": ""}, {"nome": "pane", "qta": 60, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "raffermo"}, {"nome": "latte senza lattosio", "qta": 60, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "prezzemolo", "qta": 10, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo sui piatti degli adulti"}, {"nome": "limoni", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo la scorza, meglio biologico"}, {"nome": "uova", "qta": 2, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 300, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "100 g impasto + 200 g sugo"}, {"nome": "zucca", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "cipolle", "qta": 80, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "passata di pomodoro", "qta": 900, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "pasta corta", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "da condire con metà sugo"}], "accompagnamentoConsigliato": "pasta corta condita con metà del sugo (già inclusa negli ingredienti)", "perche": "Ricetta molto recensita, tutto al Varoma in un'unica cottura: polpette morbide di pesce e un sugo che nasconde facilmente carote e zucca, con la pasta diventa una cena completa.", "usataNelMese": false}, "r796435": {"id": "r796435", "fonte": "cookidoo", "titolo": "Crocchette di pesce", "url": "https://cookidoo.it/recipes/recipe/it-IT/r796435", "tm6": true, "valutazioneCookidoo": [4.7, 39], "tempoMin": 30, "porzioniRicetta": "6 pezzi", "categoria": "pesce", "ruolo": "principale", "cereale": "nessuno", "ingredientiOriginali": ["60 g di carota", "30 g olio extravergine di oliva", "300 g di filetti di merluzzo", "3 uova", "20 g di amido di mais (maizena)", "20 g di pangrattato", "1 pizzico di sale", "olio di arachidi", "farina tipo 00"], "passi": ["La sera prima, dopo cena (circa 30 minuti), con il merluzzo già scongelato: metti nel boccale 200 g di carote e 100 g di porro (parte bianca) a pezzi e trita 10 sec./vel. 7.", "Aggiungi 60 g di olio e cuoci 6 min./120°C/vel. 1 senza misurino, così la verdura perde l'acqua.", "Unisci 600 g di filetti di merluzzo ben scolati e controllati per le lische: 10 sec./vel. 4.", "Aggiungi 2 uova, 40 g di amido di mais e 60 g di pangrattato, senza sale: 5 sec./vel. 4 (se il composto è morbido aggiungi altri 20 g di pangrattato). Forma 12 pesciolini, coprili e tienili in frigo fino alla sera dopo.", "La sera della cena accendi il forno ventilato a 200°C e avvia nel Bimby il purè bianco di patate, cavolfiore e porro (c-pure-patate-cavolfiore); intanto passa i pesciolini in 2 uova sbattute e poi in 120 g di pangrattato.", "Disponili su una teglia con carta forno, versa sopra un filo d'olio (20 g) e cuoci 18-20 minuti girandoli a metà, finché sono dorati fuori e cotti al centro.", "Servi con il purè: ai bimbi pesciolini e purè senza sale (per il piccolo spezzettati); gli adulti salano nel piatto se serve."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Ricetta x2 (600 g di merluzzo, 12 pesciolini): l'impasto sta nel boccale in una volta sola.", "Più verdura: 200 g di carote e 100 g di porro (parte bianca) tritati 10 sec./vel. 7 e cotti con 60 g di olio 6 min./120°C/vel. 1 senza misurino, così perdono l'acqua; poi si prosegue con il pesce.", "Pangrattato nell'impasto portato a 60 g (più 20 g se serve) per la verdura in più.", "In forno invece che fritte: teglia con carta forno, filo d'olio sopra, 200°C ventilato per 18-20 minuti girandole a metà. Panatura solo uovo sbattuto e pangrattato (niente farina né olio di arachidi).", "Niente sale nell'impasto (l'originale ne mette un pizzico): gli adulti salano nel piatto dopo aver servito i bimbi.", "Per stare nei 45 minuti: i pesciolini si formano la sera prima dopo cena (circa 30 minuti) e restano coperti in frigo; la sera della cena servono solo panatura e 20 minuti di forno, mentre il purè cuoce nel Bimby (circa 40 minuti in tutto).", "Il merluzzo, se surgelato, va messo in frigo la sera di due giorni prima: la sera prima deve essere già scongelato per l'impasto. In alternativa compralo fresco."], "verduraNascosta": {"verdure": ["carote", "porri"], "grammiFamiglia": 300, "come": "Carote e porro tritati finissimi e stufati dentro l'impasto dei pesciolini, poi impanati.", "trucco": "La panatura dorata copre i puntini arancioni e la forma di pesciolino li fa mangiare per gioco; con il purè bianco di cavolfiore si superano i 400 g di verdura."}, "lattosio": "no", "notaLattosio": "Nessun latticino.", "notaBimbi": "Per il bimbo di 1 anno spezzetta il pesciolino; controlla le lische del merluzzo prima di frullarlo; uovo ben cotto con 20 minuti di forno. Impasto senza sale per entrambi i bimbi. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo. Usa pangrattato semplice, senza semi. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "merluzzo già scongelato (600 g: se surgelato, in frigo dalla sera di due giorni prima, oppure compralo fresco); stasera dopo cena forma i 12 pesciolini (passi 1-4, circa 30 minuti) e tienili coperti in frigo", "gradimentoBimbiStimato": 5, "moltiplicatore": 2, "ingredienti": [{"nome": "merluzzo filetti", "qta": 600, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "anche surgelato: in frigo due sere prima (la sera prima si lavora già scongelato)"}, {"nome": "carote", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "porri", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "parte bianca"}, {"nome": "olio extravergine di oliva", "qta": 80, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "60 g impasto + 20 g per il forno"}, {"nome": "uova", "qta": 4, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": "2 impasto + 2 panatura"}, {"nome": "amido di mais", "qta": 40, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "pangrattato", "qta": 200, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "60 g impasto (+20 g se serve) + 120 g panatura"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "c-pure-patate-cavolfiore", "perche": "Pesciolini dorati con carota e porro dentro, votati 4,7: il classico 'bastoncino' fatto in casa, preparabile in anticipo e cotto in forno.", "usataNelMese": false}, "r130472": {"id": "r130472", "fonte": "cookidoo", "titolo": "Risotto salmone e finocchio", "url": "https://cookidoo.it/recipes/recipe/it-IT/r130472", "tm6": true, "valutazioneCookidoo": [4.5, 125], "tempoMin": 35, "porzioniRicetta": "6 porzioni", "categoria": "pesce", "ruolo": "completo", "cereale": "riso", "ingredientiOriginali": ["40 g di Parmigiano reggiano", "50 g di scalogno", "150 g di bulbo di finocchio", "20 g di olio di oliva", "320 g di riso per risotto", "100 g di vino bianco", "700 g di acqua", "1 cucchiaino colmo di dado Bimby per brodo di pesce", "½ - 1 cucchiaino di sale", "1 cucchiaino di pepe nero macinato fresco", "1 cucchiaio di scorza di limone tritata", "350 g di filetto di salmone fresco senza pelle e senza lische", "30 di burro", "1 cucchiaio di aneto fresco"], "passi": ["Il giorno prima (domenica sera) sposta il salmone surgelato (550 g) dal congelatore al frigo. Stasera tamponalo, togli la pelle se c'è, cerca le lische con le dita e taglialo a cubetti di 2 cm; tienilo in frigo.", "Prepara le verdure: pulisci il finocchio e taglia 200 g a pezzi; taglia a rondelle 100 g di porro (solo parte bianca) e lavalo bene. Sbuccia il sedano rapa e taglia 100 g a cubetti; sbuccia 50 g di scalogno.", "Lava il limone, grattugia la scorza (solo la parte gialla, circa 1 cucchiaio) e spremi 1 cucchiaio di succo. Tienili da parte.", "Nel boccale asciutto grattugia 40 g di Parmigiano a pezzi: 10 sec./vel. 10. Trasferiscilo in una ciotolina.", "Metti nel boccale scalogno, finocchio, porro e sedano rapa: trita 10 sec./vel. 7, fino a una quasi crema. Riunisci sul fondo con la spatola.", "Aggiungi 20 g di olio e soffriggi 5 min./120°C/vel. 1.", "Aggiungi 320 g di riso carnaroli e tosta 3 min./120°C/antiorario/vel. 1.", "Al posto del vino aggiungi 100 g di acqua e il cucchiaio di succo di limone: 1 min./100°C/antiorario/vel. 1 senza misurino. Mescola a fondo con la spatola per staccare il riso.", "Aggiungi 700 g di acqua, 1 cucchiaino raso di dado vegetale senza sale e la scorza di limone, senza sale. Mescola con la spatola per bagnare bene il riso, metti il cestello sul coperchio al posto del misurino e cuoci 13 min./100°C/antiorario/vel. 1.", "Intanto scalda 10 g di olio in una padella antiaderente, aggiungi il salmone, copri e cuoci a fuoco medio 6-7 minuti, girando i cubetti una volta: devono essere cotti anche al centro.", "A fine cottura, se il risotto è asciutto, aggiungi 50 g di acqua calda. Aggiungi 30 g di burro senza lattosio e il Parmigiano e manteca mescolando con la spatola.", "Unisci il salmone, mescola delicatamente con la spatola e lascia riposare il risotto 2 minuti nel boccale.", "Preleva le porzioni dei bimbi, senza sale, pepe né aneto. Per il bimbo di 1 anno sbriciola il salmone con la forchetta, ricontrolla le lische e lascia intiepidire.", "Solo adesso sala a piacere il risotto degli adulti; pepe e aneto tritato solo sui loro piatti.", "Servi subito. Per il pranzo di domani metti da parte 1 porzione adulto in un contenitore chiuso e, appena intiepidita, riponila in frigo; scaldala con 2-3 cucchiai di acqua, mescolando."], "modifiche": ["Più verdura invisibile: trita 50 g di scalogno con 200 g di finocchio, 100 g di porro (solo parte bianca) e 100 g di sedano rapa 10 sec./vel. 7 (devono diventare quasi una crema) e soffriggi 5 min./120°C/vel. 1.", "Salmone 550 g invece di 350 g, a cubetti di 2 cm, cotto in padella a parte (10 g di olio, coperto, 6-7 minuti) e unito alla mantecatura: nel boccale resta solo il risotto (circa 1,6 kg), senza rischio di fuoriuscite, e il salmone non si sfalda.", "Vino sostituito con 100 g di acqua + 1 cucchiaio di succo di limone (piatto per i bimbi).", "Pepe e aneto solo sui piatti degli adulti; dado: 1 cucchiaino raso di dado vegetale senza sale (r829527); sale solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Burro senza lattosio per mantecare; aggiungi 50 g di acqua se con la verdura in più il risotto resta asciutto."], "verduraNascosta": {"verdure": ["finocchi", "porri", "sedano rapa"], "grammiFamiglia": 400, "come": "Finocchio, porro e sedano rapa tritati finissimi nel soffritto: cuociono con il riso e si sciolgono nella crema del risotto.", "trucco": "Sono tutte verdure bianche come il riso; limone e parmigiano coprono il gusto dolce di anice del finocchio."}, "lattosio": "sostituito", "notaLattosio": "Burro senza lattosio per mantecare; parmigiano naturalmente senza lattosio.", "notaBimbi": "Risotto cremoso adatto anche al piccolo; controlla le lische del salmone a crudo; porzione bimbi senza pepe e aneto.", "scongelare": "filetto di salmone surgelato (550 g), se non lo compri fresco", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "scalogno", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "finocchi", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito (un finocchio medio pulito pesa circa 200 g)"}, {"nome": "porri", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo parte bianca"}, {"nome": "sedano rapa", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito: compra circa il 35% in più (buccia spessa)"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "20 g soffritto + 10 g per il salmone"}, {"nome": "riso carnaroli", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "limoni", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "scorza e un cucchiaio di succo"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver prelevato le porzioni dei bimbi"}, {"nome": "salmone filetto", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "senza pelle e lische; compralo surgelato (si usa 2 giorni dopo la spesa)"}, {"nome": "burro senza lattosio", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "aneto", "qta": null, "unita": "q.b.", "reparto": "frutta_verdura", "dispensa": true, "nota": "facoltativo, solo adulti"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}], "accompagnamentoConsigliato": "", "perche": "Piatto unico da 35 minuti, ben recensito: il finocchio c'è già nella ricetta e si aggiungono porro e sedano rapa bianchi che nel risotto spariscono.", "passiCompleti": true, "usataNelMese": true}, "r768162": {"id": "r768162", "fonte": "cookidoo", "titolo": "Pasta con crema di cavolfiore e gamberi (senza lattosio)", "url": "https://cookidoo.it/recipes/recipe/it-IT/r768162", "tm6": true, "valutazioneCookidoo": [4.5, 28], "tempoMin": 30, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["3 spicchi di aglio", "150 g di cipolle", "25 g di olio di oliva", "300 g di cimette di cavolfiore", "2 cucchiaini di dado per brodo di pollo", "250 g di bevanda a base di avena", "10 g di succo di limone, spremuto fresco", "¼ di cucchiaino di pepe nero macinato", "250 g di gamberi crudi, sbucciati e senza intestino", "300 g di pasta secca corta", "40 g di margarina", "1 cucchiaino di amido di mais (maizena)", "prezzemolo fresco"], "passi": ["Metti sul fuoco una pentola d'acqua per la pasta, SENZA sale. Taglia 400 g di cimette di cavolfiore e spremi il limone: ti servono 10 g di succo.", "Asciuga con carta da cucina i 550 g di gamberi (scongelati in frigo da ieri sera) e, se serve, la platessa.", "Metti nel boccale 1 spicchio di aglio sbucciato e 150 g di cipolle a pezzi: 3 sec./vel. 5. Riunisci sul fondo con la spatola.", "Aggiungi 25 g di olio e insaporisci: 3 min./120°C/vel. 1.", "Unisci il cavolfiore, 1 cucchiaino raso di dado vegetale senza sale, 250 g di bevanda d'avena e il succo di limone, SENZA sale né pepe: 20 min./100°C/vel. 1, con il misurino e senza Varoma.", "Quando l'acqua bolle, cuoci 320 g di pasta corta per il tempo indicato sulla confezione.", "Solo se un bimbo non ha mai mangiato gamberi: in una padella antiaderente cuoci 70 g di platessa (140 g se sono tutti e due) con 5 g di olio, coperta, 4-5 minuti. Mettila in un piattino e pulisci la padella con carta da cucina.", "Nella padella scalda 10 g di olio e salta i gamberi 3-4 minuti, SENZA sale, finché sono opachi e ben cotti anche dentro.", "Stempera 1 cucchiaino di amido di mais in 2 cucchiai di acqua fredda. Versalo nel boccale con 30 g di olio: 1 min./vel. 10, con il misurino.", "Scola la pasta e condiscila con tutta la crema di cavolfiore, senza gamberi.", "Preleva le porzioni dei bimbi, prima di unire i gamberi. Chi li ha già mangiati: qualche gambero tagliato a pezzettini. Chi non li ha mai mangiati: la platessa sbriciolata, controllando le lische. Per il bimbo di 1 anno tutto a pezzetti piccolissimi.", "Unisci i gamberi al resto della pasta e mescola.", "Metti da parte 1 porzione adulto per il pranzo di domani in un contenitore ermetico: in frigo appena intiepidita, entro 1 ora; domani scaldala in padella con 2-3 cucchiai di acqua, a fuoco dolce. Poi servi gli adulti: sale, pepe e prezzemolo tritato solo nei loro piatti."], "modifiche": ["Gamberi 550 g invece di 250 g, saltati in padella con 10 g di olio 3-4 minuti finché sono opachi e ben cotti; per i bimbi tagliali a pezzettini.", "Cavolfiore 400 g di cimette (1 cavolfiore intero da circa 700 g) e 1 solo spicchio di aglio (più delicato per i bimbi).", "Dado di pollo sostituito da 1 cucchiaino raso di dado vegetale senza sale (granulare senza sale aggiunto o fatto in casa senza sale; non iposodico, che il sale lo contiene); acqua della pasta senza sale; sale e pepe solo per gli adulti.", "Margarina sostituita da 30 g di olio extravergine; la bevanda d'avena resta, quindi il piatto rimane senza latticini.", "Pasta 320 g; prezzemolo solo sui piatti degli adulti; per i bimbi taglia i gamberi a pezzettini dentro la crema.", "Crema cotta come da ricetta a 100°C senza Varoma: con soli 250 g di bevanda d'avena la temperatura Varoma la farebbe schiumare e attaccare.", "Gamberi = crostacei, per entrambi i bimbi: chi non li ha mai mangiati non li prova a cena; per lui 70 g di platessa cotta prima dei gamberi nella stessa padella pulita (140 g se sono tutti e due)."], "verduraNascosta": {"verdure": ["cavolfiore", "cipolle"], "grammiFamiglia": 550, "come": "Cavolfiore e cipolla cotti nella bevanda d'avena e frullati a vel. 10: una crema bianca che condisce la pasta.", "trucco": "Sembra una pasta 'panna e gamberi': la crema bianca non ha pezzi e il limone copre il gusto del cavolo."}, "lattosio": "no", "notaLattosio": "Già senza latticini: bevanda d'avena e olio al posto della margarina.", "notaBimbi": "Gamberi = crostacei, vale per entrambi i bimbi: chi non li ha mai mangiati non li prova a cena (un'eventuale reazione arriverebbe di notte), e per lui cuoci 70 g di platessa prima dei gamberi nella stessa padella pulita (140 g se sono tutti e due), con un filo d'olio, coperta, 4-5 minuti, e sbriciolala nella sua pasta con la crema. I gamberi proponili a pranzo in un altro giorno. Chi li ha già mangiati li ha ben cotti e tagliati a pezzettini. Acqua della pasta e crema senza sale.", "scongelare": "gamberi sgusciati surgelati (550 g) e, se serve, la platessa (70 g per ogni bimbo che non ha mai mangiato gamberi): in frigo la sera prima", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "cipolle", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 70, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "25 g soffritto + 30 g al posto della margarina + 10 g per i gamberi + 5 g per la platessa (se serve)"}, {"nome": "cavolfiore", "qta": 400, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso delle cimette: compra 1 cavolfiore da circa 700 g"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale: granulare senza sale aggiunto o fatto in casa senza sale, 1 cucchiaino raso"}, {"nome": "bevanda di avena", "qta": 250, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "limoni", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "10 g di succo"}, {"nome": "gamberi sgusciati", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "crudi, anche surgelati"}, {"nome": "pasta corta", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "amido di mais", "qta": 1, "unita": "cucchiaini", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "prezzemolo", "qta": null, "unita": "q.b.", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo adulti"}, {"nome": "platessa filetti", "qta": 70, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "anche surgelata: 1 filetto da 70-80 g (2 se nessuno dei bimbi ha provato i gamberi); non comprarla se li hanno già mangiati"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, al piatto"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto"}], "accompagnamentoConsigliato": "", "perche": "Primo cremoso in 30 minuti già senza lattosio, con quasi mezzo chilo di cavolfiore frullato invisibile nella crema bianca.", "passiCompleti": true, "usataNelMese": true}, "r420994": {"id": "r420994", "fonte": "cookidoo", "titolo": "Burger di nasello e gamberi", "url": "https://cookidoo.it/recipes/recipe/it-IT/r420994", "tm6": true, "valutazioneCookidoo": [4.6, 25], "tempoMin": 30, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "principale", "cereale": "pane", "ingredientiOriginali": ["50 g di cipolla", "50 g di pane", "1 spicchio di aglio", "2 - 3 rametti di prezzemolo fresco", "40 g di latte", "400 g di filetti di nasello", "100 g di gamberi crudi sgusciati", "1 cucchiaino di sale", "1 pizzico di pepe bianco macinato", "1 - 2 cucchiai olio extravergine di oliva", "panini per hamburger", "insalata"], "passi": ["Nasello e gamberi devono essere scongelati (in frigo da ieri sera). Asciugali con carta da cucina e passa le dita sui filetti di nasello per togliere tutte le lische. Accendi il forno a 200°C.", "Pela e taglia a pezzi di 3 cm 75 g di cipolla, 150 g di carote e 100 g di porro (parte bianca). Sbuccia 1 spicchio di aglio e spezzetta 75 g di pane.", "Metti nel boccale cipolla, aglio, carote, porro e pane: trita 5 sec./vel. 8 e riunisci sul fondo con la spatola.", "Aggiungi 60 g di latte senza lattosio e 450 g di nasello a pezzi, senza sale né pepe: 6 sec./vel. 6.", "Se un bimbo non ha mai mangiato gamberi, preleva ora circa 120 g di impasto di solo nasello e mettilo in una ciotolina a parte. Se li hanno già mangiati tutti e due, salta questo passo.", "Aggiungi 150 g di gamberi sgusciati: 5 sec./vel. 6. Se l'impasto è troppo morbido da modellare, unisci 30 g di pangrattato: 10 sec./antiorario/vel. 3.", "Trasferisci l'impasto in una ciotola e sciacqua il boccale. Avvia ora il purè: apri in alto la scheda 'Purè di patate e carote al rosmarino', segui i passi 1-3 e poi torna qui.", "Fodera una teglia con carta forno e ungila con 30 g di olio. Con le mani bagnate forma per primi i mini-burger di solo nasello (se servono) e mettili in un angolo separato della teglia.", "Lavati le mani e forma con l'impasto ai gamberi 6 burger per gli adulti e, per i bimbi, burger piccoli fino a finire l'impasto (in tutto una dozzina, compresi quelli di solo nasello).", "Quando al purè mancano circa 15 minuti, inforna i burger a 200°C per 15 minuti, girandoli a metà cottura: dorati fuori, bianchi e sodi dentro. Se il purè non è ancora pronto, tienili nel forno spento. (In alternativa: padella antiaderente, 4-5 minuti per lato, prima i mini-burger di solo nasello.)", "Preleva le porzioni dei bimbi con il purè, senza sale né ketchup; a chi non ha mai mangiato gamberi dai solo i mini-burger di solo nasello. Per il bimbo di 1 anno sbriciola il burger con la forchetta, controlla che non ci siano lische e lascia intiepidire.", "Solo ora aggiungi sale e pepe sui burger degli adulti e servili con il purè.", "Metti da parte 2 burger con 1 porzione di purè per il pranzo di domani, in un contenitore chiuso in frigo: scaldali al microonde coperti o in padella con il coperchio, finché sono ben caldi al centro."], "modifiche": ["Ricetta x1,5 con pesce ribilanciato: 450 g di nasello + 150 g di gamberi, 6 burger per gli adulti e 12 mini-burger per i bimbi.", "Verdura nell'impasto: trita con cipolla, pane e aglio 150 g di carote e 100 g di porro (parte bianca) 5 sec./vel. 8; aggiungi 30 g di pangrattato se l'impasto è morbido.", "Latte senza lattosio; prezzemolo eliminato (niente erbe verdi nell'impasto comune); niente sale nell'impasto: sale e pepe solo sui burger degli adulti.", "Impasto di solo nasello (circa 120 g) prelevato prima dei gamberi per il bimbo che non li ha mai mangiati: i suoi mini-burger si formano per primi e cuociono separati dagli altri.", "Cottura in forno a 200°C per 15 minuti su un'unica teglia con carta forno e 30 g di olio (in alternativa in padella, 4-5 minuti per lato): tutti i burger cuociono insieme mentre il Bimby fa il purè.", "Niente insalata né panini: si serve con il purè di patate e carote (r751023)."], "verduraNascosta": {"verdure": ["carote", "porri"], "grammiFamiglia": 250, "come": "Carote e porro tritati finissimi con pane e cipolla e frullati con il pesce: il burger resta compatto e dorato.", "trucco": "Mini-burger ben dorati: i puntini arancioni sembrano la crosticina; con il purè arancione la cena supera i 400 g di verdura."}, "lattosio": "sostituito", "notaLattosio": "Latte senza lattosio nell'impasto.", "notaBimbi": "Burger morbido. Gamberi = crostacei (allergene): mai per la prima volta a cena. Se un bimbo non li ha mai mangiati, preleva la sua parte di impasto di solo nasello prima di aggiungere i gamberi (passo 2) e cuoci i suoi mini-burger separati dagli altri. Controlla le lische. Niente sale né ketchup nel piatto dei bimbi. Contiene glutine (pane e pangrattato) e latte senza lattosio.", "scongelare": "filetti di nasello (450 g) e gamberi sgusciati (150 g) surgelati: in frigo la sera prima", "gradimentoBimbiStimato": 5, "moltiplicatore": 1.5, "ingredienti": [{"nome": "cipolle", "qta": 75, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "pane", "qta": 75, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "per l'impasto"}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "latte senza lattosio", "qta": 60, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "nasello filetti", "qta": 450, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "anche surgelato: compralo surgelato (si usa 6 giorni dopo la spesa) oppure fresco giovedì 29; controlla le lische"}, {"nome": "gamberi sgusciati", "qta": 150, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "crudi sgusciati, anche surgelati: comprali surgelati (si usano 6 giorni dopo la spesa)"}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "porri", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "parte bianca"}, {"nome": "pangrattato", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, sui burger cotti"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}], "accompagnamentoConsigliato": "r751023 Purè di patate e carote (venerdì 30)", "perche": "Burger di pesce in formato 'hamburger' che i bimbi adorano, con carote e porro frullati nell'impasto, cotti tutti insieme in forno mentre il Bimby fa il purè.", "passiCompleti": true, "usataNelMese": true}, "r800501": {"id": "r800501", "fonte": "cookidoo", "titolo": "Nuggets di platessa (o sogliola)", "url": "https://cookidoo.it/recipes/recipe/it-IT/r800501", "tm6": true, "valutazioneCookidoo": [4.6, 25], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "principale", "cereale": "nessuno", "ingredientiOriginali": ["60 g di pane bianco in cassetta", "2 rametti di prezzemolo fresco, le foglioline lavate ed asciugate", "1 pizzico di sale", "500 g di filetti di sogliola", "40 g di formaggio fresco spalmabile", "olio per frittura", "1 uovo", "80 g di pangrattato"], "passi": ["Accendi il forno ventilato a 200°C e fodera una teglia con carta forno unta con 15 g di olio.", "Asciuga bene 550 g di filetti di platessa (scongelati in frigo da ieri sera) con carta da cucina, controlla le lische con le dita e tagliali a pezzi. Asciuga bene anche 200 g di cimette di cavolfiore crudo.", "Metti nel boccale 70 g di pane a pezzi e il cavolfiore: 5 sec./vel. 8. Riunisci sul fondo con la spatola.", "Unisci la platessa e 50 g di formaggio spalmabile senza lattosio, SENZA sale: 10 sec./vel. 7. Se l'impasto è troppo morbido, aggiungi 1-2 cucchiai di pangrattato (10 g) e mescola con la spatola.", "Trasferisci l'impasto in una ciotola, sciacqua il boccale e avvia subito il purè di zucca (ricetta abbinata).", "Prepara la panatura: sbatti 2 uova in un piatto fondo e metti 110 g di pangrattato in un piatto piano.", "Con le mani umide forma delle palline grandi come una noce e schiacciale un po' a forma di nugget.", "Passa ogni nugget nell'uovo e poi nel pangrattato e mettilo sulla teglia. Irrora con altri 15 g di olio.", "Cuoci in forno a 200°C per 15-18 minuti, girandoli a metà, finché sono dorati e ben cotti dentro.", "Preleva le porzioni dei bimbi, senza sale. Per il bimbo di 1 anno spezzetta i nuggets e controlla che non ci siano lische; per il bimbo di 3 anni tagliali a metà. Un cucchiaio di purè senza sale per intingere.", "Metti da parte 1 porzione adulto di nuggets per il pranzo di domani in un contenitore ermetico: in frigo appena intiepiditi; domani 5-8 minuti in forno a 200°C, così tornano croccanti. Poi servi gli adulti: sale solo sui loro nuggets, appena sfornati."], "modifiche": ["Sogliola sostituibile con platessa (più economica, stessa consistenza): 550 g di filetti.", "Verdura invisibile: trita con il pane 200 g di cavolfiore crudo a cimette piccole 5 sec./vel. 8, poi prosegui; se l'impasto è morbido aggiungi 1-2 cucchiai di pangrattato.", "Formaggio spalmabile senza lattosio (50 g).", "In forno invece che fritti: teglia con carta forno, filo d'olio, 200°C ventilato 15-18 min girandoli a metà.", "Niente zenzero né prezzemolo nell'impasto (più delicato, senza puntini verdi per i bimbi).", "Panatura per la dose maggiorata: 2 uova sbattute e 110 g di pangrattato.", "Niente sale nell'impasto: si salano solo i nuggets degli adulti, appena sfornati.", "Sera di martedì in 45 minuti: impasto nel Bimby (5 minuti), sciacqua il boccale e avvia subito il purè di zucca (32 minuti, zucca e patate già tagliate lunedì sera); intanto forma, impana e inforna i nuggets."], "verduraNascosta": {"verdure": ["cavolfiore"], "grammiFamiglia": 200, "come": "Cavolfiore crudo tritato finissimo e frullato con pesce e pane: bianco nel bianco, dentro una panatura croccante.", "trucco": "Chiamali 'nuggets' come quelli del fast food: ketchup solo per gli adulti, ai bimbi un cucchiaio di purè di zucca per intingere."}, "lattosio": "sostituito", "notaLattosio": "Formaggio spalmabile senza lattosio; pane comune raffermo o in cassetta senza latte.", "notaBimbi": "Nuggets morbidi dentro; spezzettali per il piccolo. Platessa e sogliola hanno pochissime lische ma controlla comunque. Impasto senza sale: si salano solo i nuggets degli adulti. Nessun allergene tra crostacei, molluschi, frutta a guscio o sesamo.", "scongelare": "filetti di platessa o sogliola surgelati (550 g) e, se le hai prese surgelate, le cimette di cavolfiore (200 g): in frigo la sera prima", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "pane", "qta": 70, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "raffermo, oppure in cassetta senza latte (leggi l'etichetta)"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo sui nuggets degli adulti"}, {"nome": "platessa filetti", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "o sogliola; anche surgelata (si usa 3 giorni dopo la spesa)"}, {"nome": "formaggio spalmabile senza lattosio", "qta": 50, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "cavolfiore", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "200 g di cimette crude: 1/4 di cavolfiore, oppure una busta di cimette surgelate (in frigo lunedì sera, poi asciugale bene)"}, {"nome": "uova", "qta": 2, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": "2 per la panatura di martedì"}, {"nome": "pangrattato", "qta": 120, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "110 g per la panatura + 10 g se l'impasto è morbido; la stessa confezione da 500 g dei passatelli di domenica"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "per il forno: 15 g sulla teglia + 15 g sopra i nuggets"}], "accompagnamentoConsigliato": "r104596", "perche": "Nuggets di pesce morbidi (4,6) in 40 minuti: il formato preferito dai bimbi, con cavolfiore bianco frullato nell'impasto.", "passiCompleti": true, "usataNelMese": true}, "r112239": {"id": "r112239", "fonte": "cookidoo", "titolo": "Polpette di salmone", "url": "https://cookidoo.it/recipes/recipe/it-IT/r112239", "tm6": true, "valutazioneCookidoo": [4.3, 20], "tempoMin": 55, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "completo", "cereale": "patate", "ingredientiOriginali": ["500 g di acqua", "250 g di patate", "½ limone", "50 g di pangrattato", "300 g di filetti di salmone fresco", "2 - 3 fili di erba cipollina fresca", "2 uova", "½ cucchiaino sale", "1 - 2 pizzichi di pepe bianco macinato", "olio per frittura"], "passi": ["Acqua nel boccale e patate a cubetti nel cestello: 30 min./Varoma/vel. 1; svuota il boccale.", "Polverizza scorza di limone e pangrattato: 10 sec./vel. 10.", "Aggiungi salmone, patate, erba cipollina, 1 uovo, sale e pepe: 10 sec./vel. 5.", "Forma polpette di 4-5 cm e passale nell'uovo sbattuto e nel pangrattato.", "Friggi in olio ben caldo fino a doratura e scola su carta assorbente."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Erbe verdi (prezzemolo, basilico, erba cipollina) solo sui piatti degli adulti.", "Ricetta x2 con verdura: 500 g di patate, 200 g di carote e 200 g di polpa di zucca a cubetti nel recipiente del Varoma (nel cestello non ci stanno) con 700 g di acqua nel boccale: 30 min./Varoma/vel. 1.", "Salmone 550 g, 2 uova nell'impasto e 100 g di pangrattato con la scorza di ½ limone; aggiungi pangrattato se l'impasto è molle (la zucca porta umidità). Se il boccale è troppo pieno mescola in due volte.", "Pepe solo per gli adulti; sale ½ cucchiaino in tutto.", "In forno invece che fritte: 200°C ventilato 20 min con un filo d'olio, girandole a metà (il salmone crudo nell'impasto cuoce bene).", "Panatura: 1 uovo sbattuto + 80 g di pangrattato."], "verduraNascosta": {"verdure": ["carote", "zucca"], "grammiFamiglia": 400, "come": "Carote e zucca cotte al vapore con le patate e frullate con il salmone nell'impasto.", "trucco": "L'impasto è già rosa-arancio come il salmone: carota e zucca sono invisibili e la panatura dorata fa il resto."}, "lattosio": "no", "notaLattosio": "Nessun latticino.", "notaBimbi": "Polpette morbide grazie alle patate; controlla le lische del salmone con le dita prima di frullare; uovo ben cotto in forno. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "filetto di salmone surgelato (550 g), se non lo compri fresco", "gradimentoBimbiStimato": 5, "moltiplicatore": 2, "ingredienti": [{"nome": "patate", "qta": 500, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "limoni", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "scorza"}, {"nome": "pangrattato", "qta": 180, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "100 g impasto + 80 g panatura"}, {"nome": "salmone filetto", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "senza pelle e lische"}, {"nome": "erba cipollina", "qta": null, "unita": "q.b.", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo sui piatti degli adulti"}, {"nome": "uova", "qta": 3, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": "2 impasto + 1 panatura"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "per il forno"}], "accompagnamentoConsigliato": "", "perche": "Polpette di salmone e patate (cena completa in un solo impasto) dove carote e zucca spariscono nel colore del salmone; in forno sono più leggere.", "usataNelMese": false}, "r825767": {"id": "r825767", "fonte": "cookidoo", "titolo": "Pasta panna e salmone", "url": "https://cookidoo.it/recipes/recipe/it-IT/r825767", "tm6": true, "valutazioneCookidoo": [4.1, 101], "tempoMin": 35, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": ["40 g di Parmigiano Reggiano", "50 g di burro", "120 g di salmone affumicato", "200 g di panna (min. 30% di grassi)", "5 g di concentrato di pomodoro", "20 g di Cognac", "320 g di pasta secca"], "passi": ["Metti a bollire l'acqua salata per la pasta.", "Grattugia 40 g di Parmigiano: 10 sec./vel. 10 e tieni da parte.", "Trita 250 g di zucca, 100 g di carote e 50 g di porro (parte bianca): 10 sec./vel. 7; aggiungi 30 g di burro senza lattosio e soffriggi 5 min./120°C/vel. 1.", "Aggiungi 200 g di panna senza lattosio, 10 g di concentrato e 100 g di acqua: 12 min./100°C/vel. 1, poi frulla 30 sec./vel. 4-8 aumentando gradualmente.", "Aggiungi 550 g di salmone fresco a cubetti: 6 min./100°C/antiorario/vel. cucchiaio; intanto cuoci 320 g di pasta.", "Scola la pasta tenendo un mestolo d'acqua e condiscila con la salsa e il Parmigiano; preleva le porzioni dei bimbi prima di aggiungere sale."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Salmone affumicato sostituito con 550 g di salmone fresco senza pelle e lische (niente affumicati per i bimbi).", "Base di verdure: trita 250 g di polpa di zucca, 100 g di carote e 50 g di porro 10 sec./vel. 7 e soffriggi con 30 g di burro senza lattosio 5 min./120°C/vel. 1; aggiungi 200 g di panna senza lattosio, 10 g di concentrato e 100 g di acqua, cuoci 12 min./100°C/vel. 1 e frulla 30 sec./vel. 4-8 progressivo.", "Aggiungi il salmone fresco a cubetti e cuoci 6 min./100°C/antiorario/vel. cucchiaio.", "Cognac eliminato.", "Parmigiano 40 g sulla pasta come da ricetta."], "verduraNascosta": {"verdure": ["zucca", "carote", "porri"], "grammiFamiglia": 400, "come": "Zucca, carote e porro frullati con panna e concentrato: la salsa rosa ha lo stesso colore della classica panna e salmone.", "trucco": "Il colore arancio-rosa è identico alla salsa al salmone originale e il sapore resta dolce: nessuno si accorge della zucca."}, "lattosio": "sostituito", "notaLattosio": "Panna e burro in versione senza lattosio; parmigiano naturalmente senza lattosio.", "notaBimbi": "Salmone fresco a cubetti piccoli controllato per le lische; per il bimbo di 1 anno usa una pasta piccola. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "filetto di salmone surgelato (550 g), se non lo compri fresco", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "burro senza lattosio", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "salmone filetto", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "fresco, al posto dell'affumicato"}, {"nome": "panna senza lattosio", "qta": 200, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "da cucina"}, {"nome": "concentrato di pomodoro", "qta": 10, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "1 tubetto basta per tutto il mese"}, {"nome": "zucca", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "carote", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "porri", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "parte bianca"}, {"nome": "pasta corta", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "sale grosso", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "", "perche": "Il classico 'panna e salmone' che piace ai bimbi, rifatto con salmone fresco e panna senza lattosio e una crema di zucca e carote che non si vede.", "usataNelMese": false}, "c-pure-patate-cavolfiore": {"id": "c-pure-patate-cavolfiore", "fonte": "personalizzata", "titolo": "Purè bianco di patate, cavolfiore e porro", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 40, "porzioniRicetta": "4-5 porzioni (dose famiglia)", "categoria": "vegetale", "ruolo": "accompagnamento", "cereale": "patate", "ingredientiOriginali": [], "passi": ["Metti nel boccale 40 g di Parmigiano Reggiano a pezzi: 10 sec./vel. 10. Trasferisci in una ciotola e tieni da parte.", "Metti nel boccale 80 g di porro (solo parte bianca) a pezzi e 300 g di cimette di cavolfiore: trita 10 sec./vel. 6. Posiziona la farfalla e aggiungi 700 g di patate farinose pelate a fette spesse 1 cm, 350 g di latte senza lattosio e 150 g di acqua, SENZA sale.", "Cuoci 30 min./98°C/vel. 1, con il cestello appoggiato sul foro del coperchio al posto del misurino per evitare schizzi.", "Verifica con una forchetta che patate e cavolfiore siano tenerissimi; se serve prosegui 5 min./98°C/vel. 1.", "Aggiungi 30 g di burro senza lattosio (o 30 g di olio extravergine di oliva), il Parmigiano grattugiato e 1 pizzico di noce moscata. Monta 30 sec./vel. 3, sempre con la farfalla (non superare vel. 4 per non rendere il purè colloso).", "Controlla la consistenza: se è troppo denso aggiungi 30-50 g di latte senza lattosio caldo e mescola 10 sec./vel. 3. Togli la farfalla.", "Preleva le porzioni dei bimbi; gli adulti salano nel proprio piatto. Si conserva 1 giorno in frigo; si riscalda 3 min./90°C/vel. 2 con un goccio di latte senza lattosio."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Porro e cavolfiore tritati prima della cottura: nel purè montato con la farfalla non restano anelli di porro né cimette riconoscibili.", "Niente sale in cottura (prima c'era ½ cucchiaino nel boccale): il Parmigiano dà sapore; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi."], "verduraNascosta": {"verdure": ["cavolfiore", "porri"], "grammiFamiglia": 380, "come": "Cavolfiore e porro cotti nel latte insieme alle patate e montati con parmigiano in un purè liscio.", "trucco": "Bianco nel bianco: il cavolfiore sparisce nelle patate e il parmigiano ne copre l'odore; servilo come 'purè classico'."}, "lattosio": "sostituito", "notaLattosio": "Latte e burro senza lattosio (oppure olio al posto del burro); parmigiano naturalmente senza lattosio.", "notaBimbi": "Consistenza perfetta per il bimbo di 1 anno; purè senza sale per entrambi i bimbi (gli adulti salano nel piatto). Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "patate", "qta": 700, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "a pasta farinosa"}, {"nome": "cavolfiore", "qta": 300, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "cimette"}, {"nome": "porri", "qta": 80, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "parte bianca"}, {"nome": "latte senza lattosio", "qta": 400, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "350 g + un goccio per regolare"}, {"nome": "burro senza lattosio", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "oppure olio extravergine"}, {"nome": "noce moscata", "qta": 1, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "", "perche": "Contorno jolly per crocchette, nuggets, burger e pizzaiola di pesce: aggiunge patate e circa 380 g di verdura invisibile e porta quelle cene sopra i 400 g.", "usataNelMese": false}, "c-cous-cous-pollo-crema-arancione": {"id": "c-cous-cous-pollo-crema-arancione", "fonte": "personalizzata", "titolo": "Cous cous cremoso con bocconcini di pollo e crema arancione", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 35, "porzioniRicetta": "famiglia (2 adulti + 1 porzione pranzo + 2 bimbi)", "categoria": "carne_bianca", "ruolo": "completo", "cereale": "cous cous", "ingredientiOriginali": [], "passi": ["Metti nel boccale 30 g di Parmigiano Reggiano a pezzi e grattugia 10 sec./vel. 10. Trasferisci in una ciotolina.", "Metti nel boccale 50 g di cipolla, 200 g di carote e 200 g di polpa di zucca a pezzi: trita 10 sec./vel. 7 e riunisci sul fondo con la spatola.", "Aggiungi 30 g di olio extravergine di oliva e insaporisci 5 min./120°C/vel. 1.", "Aggiungi 350 g di acqua, 1 cucchiaino raso di dado vegetale senza sale e ½ cucchiaino di curcuma: cuoci 12 min./100°C/vel. 1.", "Frulla 30 sec./vel. 5-9 aumentando gradualmente, con il misurino inserito: deve diventare una crema liscia arancione.", "Aggiungi 400 g di petto di pollo a bocconcini di 1,5 cm: cuoci 12 min./100°C/antiorario/vel. cucchiaio con il cestello al posto del misurino. Il pollo deve essere cotto bene al centro, senza parti rosa: se serve prosegui 2-3 min./100°C/antiorario/vel. cucchiaio.", "Intanto metti in una ciotola capiente 300 g di cous cous con 15 g di olio, versa sopra 330 g di acqua bollente senza sale (dal bollitore), copri con un piatto e lascia riposare 5 minuti; poi sgranalo con una forchetta.", "Unisci cous cous, pollo e crema mescolando come un risotto cremoso e completa con il Parmigiano. Preleva le porzioni dei bimbi (per il piccolo sminuzza il pollo); gli adulti salano nel piatto a piacere."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Crema di carote, zucca e cipolla frullata liscia in cui cuoce il pollo: fa da condimento al cous cous.", "Cous cous fine reidratato in ciotola mentre il pollo cuoce: cena pronta in circa 35 minuti.", "Niente sale in cottura né nell'acqua del cous cous; dado vegetale senza sale (1 cucchiaino raso): gli adulti salano nel piatto dopo aver prelevato le porzioni dei bimbi."], "verduraNascosta": {"verdure": ["carote", "zucca", "cipolle"], "grammiFamiglia": 450, "come": "Carote, zucca e cipolla cotte nel brodo e frullate in una crema liscia in cui cuoce il pollo; il cous cous la assorbe tutta.", "trucco": "La curcuma rende tutto 'giallo cous cous': sembra un condimento al formaggio, non una crema di verdure."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano stagionato, naturalmente senza lattosio.", "notaBimbi": "Il cous cous fine è morbido e va bene per il bimbo di 1 anno; pollo a pezzettini piccoli e ben cotto; porzioni dei bimbi senza sale. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "cipolle", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "carote", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "olio extravergine di oliva", "qta": 45, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "30 g soffritto + 15 g per il cous cous"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale, 1 cucchiaino raso"}, {"nome": "curcuma", "qta": 0.5, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "petto di pollo", "qta": 400, "unita": "g", "reparto": "carne", "dispensa": false, "nota": ""}, {"nome": "cous cous", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "Già completa (cous cous + pollo + crema di verdure).", "perche": "Porta il cous cous nel menu (un cereale diverso) con una crema arancione che nasconde 450 g di verdura e pollo morbido, pronto in 35 minuti.", "usataNelMese": false}, "c-risotto-arancione-merluzzo": {"id": "c-risotto-arancione-merluzzo", "fonte": "personalizzata", "titolo": "Risotto arancione con merluzzo", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 35, "porzioniRicetta": "famiglia (2 adulti + 1 porzione pranzo + 2 bimbi)", "categoria": "pesce", "ruolo": "completo", "cereale": "riso", "ingredientiOriginali": [], "passi": ["Metti nel boccale 40 g di Parmigiano Reggiano a pezzi e grattugia 10 sec./vel. 10. Trasferisci in una ciotolina.", "Metti nel boccale 250 g di polpa di zucca, 150 g di carote e 50 g di porro (parte bianca) a pezzi: trita 10 sec./vel. 8, riunisci sul fondo e ripeti 5 sec./vel. 8 fino a un trito finissimo.", "Aggiungi 30 g di olio extravergine di oliva e insaporisci 5 min./120°C/vel. 1.", "Aggiungi 320 g di riso carnaroli e tosta 3 min./120°C/antiorario/vel. 1 senza misurino.", "Aggiungi 850 g di acqua calda e 1 cucchiaino raso di dado vegetale senza sale: cuoci 14 min./100°C/antiorario/vel. 1 con il cestello al posto del misurino. Non aggiungere sale.", "Intanto passa le dita sui 550 g di filetti di merluzzo per togliere le lische, tagliali a cubetti di 2 cm e cuocili senza sale in una padella antiaderente con 10 g di olio, a fuoco medio e coperti, per 6-8 minuti; poi sbriciolali grossolanamente.", "A fine cottura del riso aggiungi 20 g di burro senza lattosio e il Parmigiano: manteca 1 min./antiorario/vel. 1 (senza temperatura). Unisci il merluzzo mescolando delicatamente con la spatola e lascia riposare 2 minuti.", "Preleva le porzioni dei bimbi; gli adulti salano nel proprio piatto se serve e grattugiano sopra la scorza di limone (facoltativa, solo per loro)."], "modifiche": ["Sale: NON salare l'acqua né le cotture comuni, anche dove i passi lo indicano; il sale va solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Zucca, carote e porro tritati finissimi nel soffritto: in cottura diventano la crema arancione del risotto.", "Il merluzzo cuoce a parte in padella e si unisce alla fine: il boccale non si riempie troppo e il pesce resta a scaglie morbide.", "Niente sale in cottura né sul pesce: dado vegetale senza sale (1 cucchiaino raso) e sale solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Scorza di limone solo sui piatti degli adulti."], "verduraNascosta": {"verdure": ["zucca", "carote", "porri"], "grammiFamiglia": 450, "come": "Zucca, carote e porro tritati finissimi nel soffritto: cuocendo con il riso si sciolgono in una crema arancione.", "trucco": "Il risotto arancione sembra 'al formaggio' e il merluzzo bianco sbriciolato si confonde con i chicchi."}, "lattosio": "sostituito", "notaLattosio": "Burro senza lattosio (oppure 20 g di olio); Parmigiano stagionato naturalmente senza lattosio.", "notaBimbi": "Merluzzo controllato per le lische e sbriciolato; risotto morbido adatto al bimbo di 1 anno; porzioni dei bimbi senza sale. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo. Porzioni dei bimbi prelevate prima di salare.", "scongelare": "filetti di merluzzo surgelati (550 g): in frigo la sera prima", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "zucca", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso della polpa pulita: compra circa il 40% in più di zucca intera"}, {"nome": "carote", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "porri", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "parte bianca"}, {"nome": "olio extravergine di oliva", "qta": 40, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "30 g soffritto + 10 g padella"}, {"nome": "riso carnaroli", "qta": 320, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale, 1 cucchiaino raso"}, {"nome": "merluzzo filetti", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "anche surgelati"}, {"nome": "burro senza lattosio", "qta": 20, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "limoni", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "scorza, solo per gli adulti (facoltativa)"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti"}], "accompagnamentoConsigliato": "Già completa (riso + merluzzo + verdura nel risotto).", "perche": "Cena di pesce leggera e veloce per il venerdì: il soffritto di zucca, carote e porro diventa la crema del risotto e il merluzzo cotto a parte non riempie troppo il boccale.", "usataNelMese": false}, "c-patate-al-forno-rosmarino": {"id": "c-patate-al-forno-rosmarino", "fonte": "personalizzata", "titolo": "Patate al forno con panatura di Parmigiano e rosmarino", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 45, "porzioniRicetta": "famiglia (circa 800 g di patate)", "categoria": "vegetale", "ruolo": "accompagnamento", "cereale": "patate", "ingredientiOriginali": [], "passi": ["La sera prima (domenica): pela 800 g di patate, tagliale a cubotti di 1,5-2 cm e tienile in frigo in una ciotola, coperte d'acqua fredda.", "Accendi il forno ventilato a 200°C e fodera una teglia grande con carta forno.", "Metti nel boccale 20 g di Parmigiano Reggiano a pezzi e 20 g di pangrattato: 10 sec./vel. 10. Trasferisci la panatura in una ciotola grande (il boccale resta asciutto e pronto per la frittata).", "Scola bene le patate e asciugale con un canovaccio pulito. Mettile nella ciotola con 30 g di olio extravergine, SENZA sale, aggiungi la panatura e mescola bene con le mani.", "Distribuisci le patate sulla teglia in un solo strato, tenendo un angolo (circa un quarto) per i bimbi. Sul resto, per gli adulti e il pranzo di domani, appoggia 2 rametti di rosmarino interi e spolvera ½ cucchiaino di sale.", "Inforna subito sul ripiano basso per 35-40 minuti, girandole a metà cottura senza mescolare i due lati, finché sono dorate fuori e tenere dentro. Se negli ultimi 5-7 minuti il forno passa al grill per la frittata, le patate restano sotto.", "Togli i rametti di rosmarino prima di servire. Per il bimbo di 1 anno scegli i pezzi più morbidi dell'angolo senza sale e schiacciali con la forchetta."], "modifiche": ["Nessun ingrediente arriva dal sugo base arancione (r54703): nella cena di lunedì 5 il sugo base è tutto sulla frittata gusto pizza (550 g). Le patate restano un contorno di solo amido, senza sugo.", "Niente sale sulle patate in comune: angolo dei bimbi senza sale, ½ cucchiaino di sale solo sulle patate degli adulti.", "Rosmarino a rametti interi solo sulle patate degli adulti e tolto prima di servire: nei piatti dei bimbi nessun ago verde. La panatura in comune è solo Parmigiano e pangrattato.", "Patate pelate e tagliate a cubotti di 1,5-2 cm la sera prima e tenute in frigo coperte d'acqua fredda: lunedì basta scolarle, asciugarle e infornarle subito nel forno già caldo. Con 35-40 minuti di cottura la cena sta nei 45 minuti insieme alla frittata (pelarle e tagliarle al momento aggiungerebbe circa 10 minuti: 55 in tutto)."], "verduraNascosta": {"verdure": [], "grammiFamiglia": 0, "come": "Nessuna verdura: è il contorno di amido della frittata gusto pizza, che da sola porta circa 450 g di verdura nascosta (sugo base arancione e patate dolci nell'impasto).", "trucco": "La crosticina dorata di Parmigiano e pangrattato le fa sembrare patatine; il rosmarino profuma solo le patate degli adulti."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano stagionato.", "notaBimbi": "Angolo dei bimbi senza sale e senza rosmarino. Per il bimbo di 1 anno pezzi morbidi schiacciati con la forchetta (niente pezzi croccanti interi).", "scongelare": "nulla dal freezer; stasera pela 800 g di patate, tagliale a cubotti di 1,5-2 cm e tienile in frigo coperte d'acqua fredda per domani", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "patate", "qta": 800, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "parmigiano reggiano", "qta": 20, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "pangrattato", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "rosmarino", "qta": 2, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "rametti, solo sulle patate degli adulti"}, {"nome": "sale fino", "qta": 0.5, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo sulle patate degli adulti"}], "accompagnamentoConsigliato": "Frittata gusto pizza (r211966) di lunedì 5: stesso forno, le frittate si gratinano sul ripiano alto negli ultimi minuti.", "perche": "Contorno che cuoce in forno mentre il Bimby fa la frittata al vapore: la cena di lunedì resta intorno ai 45 minuti, con un angolo di patate senza sale e senza erbe per i bimbi.", "usataNelMese": true}, "r377348": {"id": "r377348", "fonte": "cookidoo", "titolo": "Filetti di branzino alla pizzaiola con cous cous", "url": "https://cookidoo.it/recipes/recipe/it-IT/r377348", "tm6": true, "valutazioneCookidoo": [4.4, 159], "tempoMin": 35, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "completo", "cereale": "cous cous", "ingredientiOriginali": ["1 mazzetto di basilico fresco", "1 spicchio di aglio", "40 g olio extravergine di oliva", "4 filetti di branzino", "160 g di passata di pomodoro", "4 pizzichi di sale", "4 pizzichi di origano secco", "500 g di acqua"], "passi": ["Il giorno prima (giovedì sera) sposta i filetti di branzino surgelati (550 g) dal congelatore al frigo. Stasera tamponali con carta da cucina e passa le dita per sentire eventuali lische.", "Prepara le verdure: sbuccia il sedano rapa e taglia 250 g a cubetti di 2 cm; togli il torsolo al cavolo cappuccio e taglia 150 g a pezzi. Sbuccia 50 g di cipolla e, se vuoi, ½ spicchio di aglio.", "Metti nel boccale cipolla e aglio: trita 5 sec./vel. 5. Aggiungi sedano rapa e cavolo cappuccio, trita 10 sec./vel. 6 e riunisci sul fondo con la spatola.", "Aggiungi 30 g di olio e insaporisci 5 min./120°C/vel. 1.", "Aggiungi 400 g di passata di pomodoro e 150 g di acqua, senza sale: cuoci 8 min./100°C/vel. 1.", "Intanto ungi con 10 g di olio il recipiente e il vassoio del Varoma e distribuisci i filetti di branzino con la pelle verso il basso, senza sovrapporli (una parte nel recipiente, una sul vassoio).", "Posiziona il Varoma sul boccale, chiudilo e cuoci 15 min./Varoma/vel. 1. Intanto accendi il bollitore.", "Prepara il cous cous: in una ciotola capiente metti 300 g di cous cous e 15 g di olio, versa 330 g di acqua bollente senza sale, copri con un piatto e lascia 5 minuti. Poi sgrana con la forchetta.", "A fine cottura togli il Varoma e tienilo chiuso perché il pesce resti caldo. Con il misurino inserito frulla il sugo 40 sec./vel. 5-10 aumentando gradualmente: diventa una pizzaiola liscia e densa.", "Togli la pelle al branzino e controlla bene le lische con le dita su tutti i filetti.", "Preleva le porzioni dei bimbi, senza sale né erbe: sbriciola il pesce nella pizzaiola e mescolalo al cous cous. Per il bimbo di 1 anno sbriciolalo finissimo, ricontrolla le lische e lascia intiepidire.", "Agli adulti il filetto intero coperto di pizzaiola, con il cous cous accanto: sala e completa con qualche foglia di basilico spezzata e un pizzico di origano.", "Servi subito. Per il pranzo di domani metti da parte 1 porzione adulto (cous cous, pesce e sugo) in un contenitore chiuso e, appena intiepidita, riponila in frigo; scaldala coperta con 1 cucchiaio di acqua."], "modifiche": ["Pizzaiola 'ricca': invece di 40 g di passata per cartoccio, nel boccale cuoce un sugo con 400 g di passata, 250 g di sedano rapa e 150 g di cavolo cappuccio tritati, poi frullato liscio.", "Niente cartocci: i 550 g di filetti per la famiglia cuociono sul Varoma sopra il sugo (15 minuti, dopo 8 minuti di cottura del solo sugo, così le verdure sono ben tenere e il pesce non si asciuga).", "Niente peperoncino; aglio facoltativo e frullato nel sugo; basilico e origano solo sui piatti degli adulti (niente puntini verdi per i bimbi).", "Cena completa con 300 g di cous cous preparato con acqua bollente senza sale mentre il pesce cuoce.", "Niente sale nel sugo né nel cous cous: si sala solo dopo aver preso le porzioni dei bimbi."], "verduraNascosta": {"verdure": ["sedano rapa", "cavolo cappuccio", "cipolle"], "grammiFamiglia": 450, "come": "Sedano rapa e cavolo cappuccio tritati, stufati e cotti nel pomodoro sotto il Varoma, poi frullati: la pizzaiola diventa più densa e dolce.", "trucco": "Il sugo è rosso e liscio come una normale pizzaiola e il cous cous lo assorbe: nessun pezzetto riconoscibile."}, "lattosio": "no", "notaLattosio": "Nessun latticino.", "notaBimbi": "Branzino senza pelle, lische controllate con le dita e sbriciolato nel sugo; cous cous morbido, adatto al bimbo di 1 anno. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo (il cous cous contiene glutine). Sugo e cous cous senza sale: sala solo le porzioni degli adulti.", "scongelare": "filetti di branzino surgelati, 550 g (se li usi surgelati)", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.3, "ingredienti": [{"nome": "cipolle", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "aglio", "qta": 0.5, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": "facoltativo"}, {"nome": "sedano rapa", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito: compra circa il 35% in più (buccia spessa)"}, {"nome": "cavolo cappuccio", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "bianco, senza torsolo"}, {"nome": "olio extravergine di oliva", "qta": 55, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "30 g soffritto + 10 g Varoma + 15 g cous cous"}, {"nome": "passata di pomodoro", "qta": 400, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "branzino filetti", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "anche surgelati; chiedi filetti spinati"}, {"nome": "cous cous", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "origano", "qta": 2, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "basilico", "qta": 5, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo adulti, sul piatto"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver preso le porzioni dei bimbi"}], "accompagnamentoConsigliato": "Già completa (cous cous + branzino + verdura nel sugo).", "perche": "Branzino, pesce usato solo qui nel mese, cotto al Varoma sopra una pizzaiola che nasconde 400 g di sedano rapa e cavolo cappuccio (nessuna zucca, nessuna carota). Pronta in 35 minuti di venerdì e il cous cous non pesa sul conteggio della pasta.", "passiCompleti": true, "usataNelMese": true}, "r628835": {"id": "r628835", "fonte": "cookidoo", "titolo": "Filetti di trota con purè verde di patate e broccoli", "url": "https://cookidoo.it/recipes/recipe/it-IT/r628835", "tm6": true, "valutazioneCookidoo": [4.3, 20], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "completo", "cereale": "patate", "ingredientiOriginali": ["60 g olio extravergine di oliva", "2 - 3 spicchi di aglio", "250 g di cimette di broccoli", "375 g di acqua", "4 di filetti di trota con la pelle", "4 pizzichi di pepe nero macinato", "30 g di panna acida", "1 cucchiaino di sale"], "passi": ["Il giorno prima (martedì sera) sposta dal congelatore al frigo la vaschetta A di crema di broccoli e porri (circa 650 g) e, se li usi surgelati, i filetti di trota (550 g). Stasera tampona la trota con carta da cucina.", "Sbuccia 850 g di patate (circa 760 g pelate) e tagliale a cubetti di 2 cm.", "Nel boccale asciutto grattugia 30 g di Parmigiano a pezzi: 10 sec./vel. 10. Trasferiscilo in una ciotolina.", "Metti nel boccale 20 g di olio e 1 spicchio di aglio sbucciato: trita 3 sec./vel. 7, riunisci sul fondo e insaporisci 3 min./120°C/vel. 1. Versa l'olio all'aglio in una ciotolina: è il condimento degli adulti.", "Metti nel boccale 600 g di acqua, senza sale, e chiudi con il coperchio. Metti le patate nel recipiente del Varoma, posizionalo e cuoci 12 min./Varoma/vel. 1.", "Intanto ungi il vassoio del Varoma con 5 g di olio e disponi i filetti di trota con la pelle verso il basso, senza sovrapporli.", "Finiti i 12 minuti inserisci il vassoio con la trota sopra le patate, chiudi e cuoci 15 min./Varoma/vel. 1. Poi togli il Varoma e tienilo chiuso perché resti caldo.", "Versa in una tazza circa 100 g di acqua di cottura e svuota il boccale. Metti nel boccale la crema della vaschetta A e scalda 4 min./90°C/vel. 2 (se era ancora un po' congelata, qualche minuto in più).", "Aggiungi le patate, il Parmigiano e 10 g di olio. Inserisci la farfalla e amalgama 20 sec./vel. 3 fino a un purè verde morbido; se è troppo denso aggiungi un po' dell'acqua di cottura e mescola ancora qualche secondo. Togli la farfalla.", "Togli la pelle alla trota e cerca le lische passando bene le dita su tutti i filetti: la trota ha lische sottili lungo il centro.", "Preleva le porzioni dei bimbi, senza sale, e sbriciola la trota nel loro purè. Per il bimbo di 1 anno sbriciolala finissima, ricontrolla le lische e lascia intiepidire.", "Agli adulti il filetto intero sul purè, condito con l'olio all'aglio, sale, pepe e qualche goccia di limone.", "Servi subito. Per il pranzo di domani metti da parte 1 porzione adulto (purè e trota) in un contenitore chiuso e, appena intiepidita, riponila in frigo; scaldala coperta con 1-2 cucchiai di acqua."], "modifiche": ["Base della domenica: usa la vaschetta A di crema di broccoli e porri (r399588, circa 650 g, dal congelatore al frigo martedì sera, con circa 520 g di broccoli, porri e spinaci) al posto dei 250 g di broccoli rosolati e cotti nel boccale: si scalda 4 minuti e diventa il purè verde con le patate.", "Aggiunte 760 g di patate pelate nel recipiente del Varoma (sopra l'acqua, senza sale): con la crema diventano un purè verde che fa da base della cena.", "Trota a 550 g per la famiglia, messa sul vassoio dopo 12 minuti di cottura delle patate, così non si secca.", "Panna acida eliminata: la cremosità viene dalla crema di broccoli, da 30 g di Parmigiano e da 10 g di olio; niente latte.", "Olio all'aglio (20 g con 1 spicchio, invece di 60 g con 2-3 spicchi), pepe, sale e limone solo per gli adulti, dopo aver preparato i piatti dei bimbi.", "Purè amalgamato con la farfalla a vel. 3 per non renderlo colloso."], "verduraNascosta": {"verdure": ["broccoli", "porri", "spinaci"], "grammiFamiglia": 520, "come": "La vaschetta A di crema di broccoli, porri e spinaci (circa 520 g di verdura) si scalda nel boccale e si amalgama alle patate cotte al vapore: diventa un purè uniforme, verde chiaro.", "trucco": "Chiamalo 'purè di Shrek': nessun pezzetto di broccolo, solo un purè verde e cremoso con il pesce sbriciolato dentro."}, "lattosio": "no", "notaLattosio": "Panna acida dell'originale eliminata e niente latte; solo Parmigiano Reggiano stagionato, naturalmente senza lattosio.", "notaBimbi": "La trota ha lische sottili lungo il filetto: passala con le dita prima di sbriciolarla nel purè. Purè morbido, perfetto anche per il bimbo di 1 anno; olio all'aglio, sale, pepe e limone solo agli adulti. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo.", "scongelare": "vaschetta A di crema di broccoli (circa 650 g) e filetti di trota surgelati, 550 g (se li usi surgelati)", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.4, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 35, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "20 g olio all'aglio + 5 g vassoio + 10 g purè"}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo per l'olio degli adulti"}, {"nome": "patate", "qta": 850, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "farinose, da purè: circa 760 g pelate"}, {"nome": "trota filetti", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "anche surgelati; con la pelle, trota iridea o salmonata"}, {"nome": "limoni", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo adulti, facoltativo"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver preparato i piatti dei bimbi"}], "accompagnamentoConsigliato": "Già completa (purè verde di patate + trota); frutta a fine pasto.", "perche": "Trota, pesce nuovo e poco costoso, tutta al Varoma in 40 minuti; la crema di broccoli della domenica diventa un purè verde con più di 500 g di verdura, senza cuocere broccoli in settimana.", "passiCompleti": true, "usataNelMese": true}, "r822769": {"id": "r822769", "fonte": "cookidoo", "titolo": "Nasello al vapore con riso cremoso bianco", "url": "https://cookidoo.it/recipes/recipe/it-IT/r822769", "tm6": true, "valutazioneCookidoo": [4.3, 41], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "completo", "cereale": "riso", "ingredientiOriginali": ["1000 g di acqua", "5 g di sale", "250 g di riso basmati", "400 g di verdure miste", "500 g di filetti di nasello", "1 cucchiaio di olio extravergine di oliva"], "passi": ["Il giorno prima sposta i filetti di nasello surgelati (550 g) dal congelatore al frigo. Stasera tamponali con carta da cucina e passa le dita sui filetti per sentire eventuali lische.", "Prepara le verdure: stacca 250 g di foglie interne chiare di verza, togli la costa e tagliale a pezzi di 3-4 cm. Pela 200 g di topinambur e tagliali a fettine sottili (3-4 mm).", "Accendi il bollitore con almeno 1,2 litri di acqua. Intanto, nel boccale asciutto, grattugia 40 g di Parmigiano a pezzi: 10 sec./vel. 10 e trasferiscilo in una ciotolina.", "Metti nel boccale 1200 g di acqua calda del bollitore, senza sale, e chiudi con il coperchio. Metti verza e topinambur nel recipiente del Varoma, posizionalo e cuoci 10 min./Varoma/vel. 1 (con acqua fredda di rubinetto 15 min.).", "Intanto pesa 300 g di riso basmati nel cestello e sciacqualo sotto l'acqua corrente finché l'acqua esce quasi limpida.", "Ungi il vassoio del Varoma con 5 g di olio e disponi i filetti di nasello in un solo strato. Se non ci stanno tutti, metti i più sottili sopra la verza nel recipiente.", "Finiti i 10 minuti togli il Varoma. Inserisci con cautela il cestello con il riso nell'acqua che bolle e chiudi il coperchio. Riposiziona il Varoma con sopra il vassoio del pesce e cuoci 15 min./Varoma/vel. 4.", "Togli il Varoma e tienilo chiuso. Estrai il cestello con il gancio della spatola, versa il riso in una ciotola grande e condiscilo con 10 g di olio.", "Versa in una tazza circa 150 g di acqua di cottura (un mestolo e mezzo) e svuota il boccale.", "Metti nel boccale verza e topinambur cotti, 120 g dell'acqua di cottura tenuta da parte, il Parmigiano e 15 g di olio. Con il misurino inserito frulla 40 sec./vel. 5-10 aumentando gradualmente, fino a una crema chiara e liscia (se è troppo densa aggiungi l'acqua rimasta).", "Sbriciola il nasello con la forchetta in un piatto, passando bene le dita per trovare ogni lisca.", "Unisci al riso la crema di verdure e il nasello sbriciolato e mescola bene: diventa un riso cremoso bianco.", "Preleva le porzioni dei bimbi, senza sale e senza limone. Per il bimbo di 1 anno schiaccia ancora il pesce con la forchetta, ricontrolla le lische, aggiungi 1 cucchiaio di acqua calda se serve e lascia intiepidire.", "Solo adesso sala il riso degli adulti (anche la porzione per domani) e grattugia sui loro piatti la scorza di mezzo limone.", "Servi subito. Per il pranzo di domani metti da parte 1 porzione adulto in un contenitore chiuso: appena intiepidita riponila in frigo e domani scaldala con 1-2 cucchiai di acqua."], "modifiche": ["Le 'verdure miste' diventano 250 g di verza (solo le foglie interne chiare, perché la crema resti chiara) e 200 g di topinambur, cotti al vapore e frullati in una crema con 40 g di Parmigiano e acqua di cottura.", "Riso portato a 300 g (il massimo comodo per il cestello) e acqua a 1200 g, calda dal bollitore e senza i 5 g di sale; nasello 550 g per la famiglia.", "Ordine di cottura rivisto: prima 10 minuti di sole verdure, poi riso nel cestello e pesce sul vassoio per 15 minuti. Così riso, pesce e verdure sono pronti insieme, il nasello non si asciuga e le verdure sono abbastanza tenere da frullare lisce.", "Invece di servire riso, pesce e verdure separati, tutto viene mescolato in un riso cremoso con il nasello sbriciolato.", "Sale solo dopo aver preso le porzioni dei bimbi; limone solo per gli adulti."], "verduraNascosta": {"verdure": ["verza", "topinambur"], "grammiFamiglia": 450, "come": "Verza e topinambur cotti al vapore e frullati con Parmigiano e acqua di cottura: diventano la crema che lega il riso.", "trucco": "Crema chiara su riso bianco e pesce bianco: sembra un riso 'al formaggio', senza puntini colorati (per questo si usano solo le foglie interne della verza)."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano stagionato, naturalmente senza lattosio.", "notaBimbi": "Nasello controllato per le lische e sbriciolato; riso morbido e cremoso, adatto al bimbo di 1 anno. Nessun allergene tra crostacei, molluschi, frutta a guscio o sesamo. Il topinambur in quantità moderata può dare un po' di gonfiore: la dose (circa 20 g nella porzione del piccolo) è pensata per non esagerare.", "scongelare": "filetti di nasello surgelati (550 g): in frigo la sera prima", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.2, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "a pezzi"}, {"nome": "riso basmati", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "verza", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo foglie interne chiare, senza costa: compra mezza verza piccola (le foglie esterne scure non servono)"}, {"nome": "topinambur", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pelato: comprane circa 250 g"}, {"nome": "nasello filetti", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "anche surgelato: compralo surgelato (si usa 5 giorni dopo la spesa del sabato)"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "5 g vassoio + 10 g riso + 15 g crema"}, {"nome": "limoni", "qta": 0.5, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "scorza, solo adulti: lo stesso limone di domenica"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo dopo aver preso le porzioni dei bimbi"}], "accompagnamentoConsigliato": "Già completa (riso + nasello + crema di verdure); frutta a fine pasto.", "perche": "Tutto in un'unica cottura (verdure e pesce nel Varoma, riso nel cestello) in circa 40 minuti; usa due verdure che nel mese compaiono solo qui (verza e topinambur) e nessuna zucca, carota o porro, già al limite delle 7 cene.", "passiCompleti": true, "usataNelMese": true}, "c-polenta-ragu-casa-crema-arancione": {"id": "c-polenta-ragu-casa-crema-arancione", "fonte": "personalizzata", "titolo": "Polenta morbida con il ragù di casa e crema arancione", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 35, "porzioniRicetta": "famiglia (2 adulti + 1 porzione pranzo + 2 bimbi)", "categoria": "carne_rossa", "ruolo": "completo", "cereale": "polenta", "ingredientiOriginali": [], "passi": ["La sera prima sposta dal congelatore al frigo circa 600 g di ragù classico di casa.", "Metti nel boccale 40 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10. Trasferisci in una ciotolina.", "Metti nel boccale 40 g di cipolla e trita 3 sec./vel. 5. Riunisci sul fondo con la spatola, aggiungi 20 g di olio e insaporisci 3 min./120°C/vel. 1.", "Aggiungi 260 g di patate dolci pelate e 160 g di sedano rapa pulito, a pezzi, e trita 10 sec./vel. 6. Aggiungi 200 g di acqua e cuoci 15 min./100°C/vel. 1.", "Frulla 40 sec./vel. 5-10 aumentando gradualmente fino a una crema liscia, senza pezzetti.", "Aggiungi il ragù di casa e scalda 8 min./100°C/antiorario/vel. 1, con il cestello sul coperchio al posto del misurino (5 minuti in più se il ragù è ancora in parte congelato). Non aggiungere sale.", "Intanto, mentre cuoce la crema, porta a bollore in una pentola capiente 1,5 litri di acqua senza sale, versa a pioggia 300 g di polenta istantanea mescolando con la frusta e cuoci 5-8 minuti (secondo la confezione) mescolando spesso. Spegni e unisci il Parmigiano e 10 g di olio: deve restare morbida e cremosa; se si rassoda aggiungi un mestolino di acqua calda.", "Preleva polenta e ragù per i due bimbi e mettili nei loro piatti. Poi aggiungi 1-2 pizzichi di sale alla polenta rimasta, mescola e servi gli adulti con il ragù arancione sopra.", "Porzione per il pranzo di domani: metti da parte 1 porzione adulto di polenta e ragù; la polenta si rassoda in frigo, il giorno dopo scaldala a fette al microonde o in padella con sopra il ragù."], "modifiche": ["Ispirata a 'Polenta con ragù' di Cookidoo (r637545): al posto del ragù cotto sul momento si usa il ragù classico di casa (circa 600 g), scongelato in frigo la sera prima.", "Il ragù viene allungato con una crema di patate dolci e sedano rapa (420 g di verdura più 40 g di cipolla) frullata liscia: più sugo, stesso colore del ragù.", "Polenta istantanea cotta in pentola mentre il Bimby prepara la crema e scalda il ragù: cena pronta in circa 35 minuti.", "Acqua della polenta a 1,5 litri per 300 g, così resta morbida e adatta anche al bimbo di 1 anno.", "Niente sale nell'acqua né nel ragù: 1-2 pizzichi di sale solo nella polenta degli adulti, dopo aver prelevato le porzioni dei bimbi."], "verduraNascosta": {"verdure": ["patate dolci", "sedano rapa", "cipolle"], "grammiFamiglia": 460, "come": "Patate dolci e sedano rapa cotti e frullati in una crema liscia, in cui si scalda il ragù di casa; il ragù arancione si mescola poi alla polenta.", "trucco": "Il ragù diventa solo più abbondante e vellutato: il colore resta quello del ragù e sulla polenta non si distingue nulla. Le patate dolci addolciscono il sugo."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano stagionato, naturalmente privo di lattosio. Il ragù di casa è quello che prepari tu: se nella tua ricetta c'è latte, usi già quello senza lattosio.", "notaBimbi": "Polenta morbida e ragù allungato con la crema: consistenza adatta anche al bimbo di 1 anno (se nel ragù ci sono pezzetti più grandi, schiacciali con la forchetta). Acqua della polenta senza sale e niente sale nel ragù, che è già saporito. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo.", "scongelare": "ragù classico di casa, circa 600 g", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "ragù classico di casa", "qta": 600, "unita": "g", "reparto": "surgelati", "dispensa": false, "casa": true, "nota": "dal tuo freezer"}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "cipolle", "qta": 40, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "20 g per il soffritto + 10 g nella polenta"}, {"nome": "patate dolci", "qta": 260, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pelato: compra circa 320 g"}, {"nome": "sedano rapa", "qta": 160, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito: compra circa il 35% in più (buccia spessa)"}, {"nome": "polenta istantanea", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nella polenta degli adulti, dopo aver prelevato quella dei bimbi"}], "accompagnamentoConsigliato": "Già completa (polenta + ragù di casa + 420 g di verdura nella crema).", "perche": "Il modo più veloce per usare il ragù di casa in una sera feriale senza pasta: la polenta istantanea si cuoce in pentola mentre il Bimby scalda il ragù nella crema di patate dolci e sedano rapa. Polenta morbida e sugo abbondante sono tra i piatti preferiti dei bimbi.", "usataNelMese": false}, "r48883": {"id": "r48883", "fonte": "cookidoo", "titolo": "Gnocchi alla romana gratinati sul ragù di casa", "url": "https://cookidoo.it/recipes/recipe/it-IT/r48883", "tm6": true, "valutazioneCookidoo": [4.7, 552], "tempoMin": 80, "porzioniRicetta": "6 porzioni", "categoria": "carne_rossa", "ruolo": "completo", "cereale": "semolino", "ingredientiOriginali": ["70 g di Parmigiano Reggiano", "1000 g di latte", "1 cucchiaino di sale", "1 pizzico di noce moscata grattugiata", "60 g di burro", "250 g di semolino di grano", "2 tuorli"], "passi": ["Sera prima (circa 40 minuti): sposta in frigo il ragù di casa. Metti nel boccale 80 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10; trasferisci in una ciotola.", "Metti nel boccale 250 g di finocchi puliti a pezzi e 300 g di latte senza lattosio: cuoci 15 min./98°C/vel. 1 con il cestello al posto del misurino, poi frulla 1 min./vel. 5-10 aumentando gradualmente fino a una crema liscissima.", "Aggiungi 650 g di latte senza lattosio, 20 g di burro senza lattosio e 1 pizzico di noce moscata: scalda 8 min./90°C/vel. 2 (niente sale: basta il Parmigiano).", "Con le lame in movimento a vel. 4 versa a pioggia dal foro del coperchio 300 g di semolino, poi cuoci 7 min./90°C/vel. 3. Aggiungi 2 tuorli e 50 g di Parmigiano: 20 sec./vel. 4, poi 2 min./90°C/vel. 3. Stendi su carta forno bagnata a 1,5 cm di spessore, lascia raffreddare, copri e tieni in frigo fino alla sera dopo.", "Sera della cena: preriscalda il forno a 200°C ventilato. Metti nel boccale sciacquato 30 g di cipolla e 180 g di cavolo cappuccio bianco a pezzi: trita 8 sec./vel. 6, riunisci sul fondo, aggiungi 10 g di olio e insaporisci 3 min./120°C/vel. 1.", "Aggiungi 100 g di acqua e cuoci 10 min./100°C/vel. 1, poi frulla 30 sec./vel. 5-9 aumentando gradualmente. Aggiungi 600 g di ragù classico di casa scongelato e scalda 6 min./100°C/antiorario/vel. 1.", "Intanto taglia il semolino a dischi (con un bicchiere di 5-6 cm) o a rombi. Versa il ragù in una pirofila di circa 30x20 cm, disponi sopra gli gnocchi leggermente sovrapposti (anche i ritagli), cospargi con il Parmigiano rimasto e 20 g di burro senza lattosio a fiocchetti.", "Cuoci in forno 15-20 minuti a 200°C, finché gratinati. Lascia intiepidire 5 minuti; preleva le porzioni dei bimbi e sala solo quelle degli adulti, se serve."], "modifiche": ["Latte e burro senza lattosio; niente sale (il Parmigiano basta, gli adulti salano nel piatto).", "Dosi per la famiglia: 300 g di semolino (x1,2), 950 g di latte in tutto (meno dell'originale perché la crema di finocchi porta la sua acqua), 80 g di Parmigiano, 40 g di burro.", "250 g di finocchi cotti nel latte e frullati prima di aggiungere il semolino: gli gnocchi restano bianchi e morbidi.", "Tuorli aggiunti a fine cottura e cotti ancora 2 minuti a 90°C, poi in forno: ben cotti anche per il bimbo di 1 anno.", "Da contorno a cena completa: gli gnocchi vengono gratinati sopra 600 g di ragù classico di casa, allungato con una crema di cavolo cappuccio e cipolla (180 g + 30 g). Nessuna base della domenica.", "Per stare nei 45 minuti nelle sere feriali: il semolino si prepara la sera prima (circa 40 minuti, passi 1-4) e rassoda in frigo; la sera della cena bastano circa 40 minuti (crema, ragù e gratinatura)."], "verduraNascosta": {"verdure": ["finocchi", "cavolo cappuccio", "cipolle"], "grammiFamiglia": 460, "come": "Finocchi cotti nel latte e frullati dentro l'impasto di semolino; cavolo cappuccio e cipolla frullati in crema e scaldati nel ragù di casa.", "trucco": "Gli gnocchi alla romana restano bianchi e dorati in superficie e il ragù sotto è quello di sempre: nessuna traccia di verdura."}, "lattosio": "sostituito", "notaLattosio": "Latte e burro senza lattosio; Parmigiano stagionato naturalmente senza lattosio. Se nel tuo ragù di casa hai messo latte normale, tienine conto.", "notaBimbi": "Tuorli ben cotti (2 minuti a 90°C nel semolino e poi in forno). Gnocchi morbidissimi: per il bimbo di 1 anno tagliali a pezzetti e mescolali al ragù. Nessun sale aggiunto. Se il tuo ragù contiene pancetta o salsiccia, ai bimbi dai più gnocchi e meno ragù. Nessun allergene tra quelli da segnalare. I 2 albumi avanzati si conservano in frigo 2 giorni per una frittata.", "scongelare": "ragù classico di casa, circa 600 g", "gradimentoBimbiStimato": 5, "moltiplicatore": 1.2, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 80, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "finocchi", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito (circa 1 finocchio grande)"}, {"nome": "latte senza lattosio", "qta": 950, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "burro senza lattosio", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "20 g nell'impasto + 20 g a fiocchetti"}, {"nome": "noce moscata", "qta": 1, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "semolino", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "di grano duro"}, {"nome": "uova", "qta": 2, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": "solo i tuorli"}, {"nome": "cipolle", "qta": 30, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "cavolo cappuccio", "qta": 180, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "bianco"}, {"nome": "olio extravergine di oliva", "qta": 10, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "ragù classico di casa", "qta": 600, "unita": "g", "reparto": "surgelati", "dispensa": false, "casa": true, "nota": "dal tuo freezer"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto, se serve"}], "accompagnamentoConsigliato": "Già completa (semolino + ragù di casa + verdura nascosta); frutta a fine pasto.", "perche": "Gli gnocchi alla romana sono tra le ricette più amate di Cookidoo (4,7 su 552) e piacciono moltissimo ai bimbi; gratinati sul ragù di casa diventano un piatto unico con un cereale nuovo (semolino), senza pasta, e con 460 g di verdura nascosta. Il semolino si prepara la sera prima.", "usataNelMese": false}, "c-gnocchi-ragu-casa-bietole-finocchi": {"id": "c-gnocchi-ragu-casa-bietole-finocchi", "fonte": "personalizzata", "titolo": "Gnocchi di patate al ragù di casa con verdure nascoste", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 30, "porzioniRicetta": "famiglia (2 adulti + 1 porzione pranzo + 2 bimbi)", "categoria": "carne_rossa", "ruolo": "completo", "cereale": "gnocchi", "ingredientiOriginali": [], "passi": ["La sera prima sposta in frigo il ragù classico di casa, circa 600 g, e 200 g di bieta surgelata.", "Metti nel boccale 40 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10; trasferisci in una ciotolina.", "Metti nel boccale 30 g di cipolla, 200 g di finocchi a pezzi e 200 g di bieta scongelata e strizzata: trita 10 sec./vel. 6 e riunisci sul fondo con la spatola.", "Aggiungi 15 g di olio e insaporisci 5 min./120°C/vel. 1.", "Aggiungi 100 g di acqua e cuoci 12 min./100°C/vel. 1, poi frulla 40 sec./vel. 5-10 aumentando gradualmente, fino a una crema liscia senza fili.", "Aggiungi il ragù di casa e scalda 8 min./100°C/antiorario/vel. 1 con il cestello sul coperchio al posto del misurino (5 minuti in più se il ragù è ancora in parte congelato).", "Intanto porta a bollore una pentola grande di acqua SENZA sale e cuoci 1 kg di gnocchi di patate, in due volte se la pentola è piccola, finché salgono a galla; scolali con la schiumarola.", "Condisci gli gnocchi con il ragù e il Parmigiano e preleva le porzioni dei bimbi; poi sale solo sui piatti degli adulti, se serve."], "modifiche": ["Gnocchi di patate pronti (freschi, 1 kg) per stare nei 30 minuti: il Bimby fa il sugo mentre gli gnocchi cuociono in pentola.", "Verdura nascosta nel ragù: 200 g di finocchi e 200 g di bieta surgelata (scongelata e strizzata) (più 30 g di cipolla) stufati, cotti e frullati lisci; con più finocchio (bianco) e meno bietola il sugo resta del colore del ragù.", "Ragù classico di casa (600 g) scaldato direttamente nella crema di verdure: niente altro sugo.", "Niente sale nell'acqua degli gnocchi né nel sugo: il ragù di casa è già saporito; sale solo per gli adulti, al piatto.", "Bieta surgelata (200 g, foglie a cubetti) al posto delle foglie fresche: la spesa è sabato 3 e le bietole fresche in frigo durano solo 3-4 giorni. Passa in frigo mercoledì sera con il ragù; strizzala bene prima di tritarla."], "verduraNascosta": {"verdure": ["bietole", "finocchi", "cipolle"], "grammiFamiglia": 430, "come": "Finocchi, bietole e cipolla stufati, cotti e frullati lisci; il ragù di casa si scalda direttamente nella crema.", "trucco": "Il finocchio frullato è bianco e dolce e il verde delle bietole sparisce nel rosso-marrone del ragù: sembra solo un ragù più abbondante e cremoso."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano stagionato, naturalmente senza lattosio. Il ragù è quello di casa: se nella tua ricetta c'è latte, conta che sia senza lattosio.", "notaBimbi": "Gnocchi morbidi: per il bimbo di 1 anno tagliali in 4. Acqua di cottura senza sale e ragù di casa già saporito: niente sale nei piatti dei bimbi.", "scongelare": "ragù classico di casa, circa 600 g, e 200 g di bieta surgelata", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "ragù classico di casa", "qta": 600, "unita": "g", "reparto": "surgelati", "dispensa": false, "casa": true, "nota": "dal tuo freezer"}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "cipolle", "qta": 30, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "finocchi", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito"}, {"nome": "bieta surgelata", "qta": 200, "unita": "g", "reparto": "surgelati", "dispensa": false, "nota": "foglie a cubetti; in frigo mercoledì sera con il ragù"}, {"nome": "olio extravergine di oliva", "qta": 15, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "gnocchi di patate", "qta": 1000, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "freschi, 1 kg (o 2 confezioni da 500 g)"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, se serve"}], "accompagnamentoConsigliato": "Già completa (gnocchi + ragù di casa + verdura nel sugo).", "perche": "Cena feriale da 30 minuti con il ragù di casa e senza pasta: gli gnocchi al ragù sono un classico che i bimbi adorano, e 400 g di finocchi e bietole spariscono nel sugo. Ispirata a 'Gnocchi al ragù' di Cookidoo (r759956, 4,4) usando gnocchi pronti.", "usataNelMese": true}, "c-farro-pesto-casa-cannellini-broccoli": {"id": "c-farro-pesto-casa-cannellini-broccoli", "fonte": "personalizzata", "titolo": "Farro al pesto di casa con crema di cannellini e broccoli", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 40, "porzioniRicetta": "famiglia (2 adulti + 1 porzione pranzo + 2 bimbi)", "categoria": "legumi", "ruolo": "completo", "cereale": "farro", "ingredientiOriginali": [], "passi": ["La sera prima (sabato 24) sposta dal congelatore al frigo circa 150 g di pesto alla genovese di casa.", "Metti nel boccale asciutto 40 g di Parmigiano Reggiano a pezzi e grattugia 10 sec./vel. 10; trasferisci in una ciotolina.", "Metti nel boccale 1200 g di acqua senza sale e inserisci il cestello con 300 g di farro perlato sciacquato. Chiudi, togli il misurino e avvia 27 min./Varoma/vel. 4.", "Mentre l'acqua scalda (entro i primi 5 minuti) dividi i broccoli in cimette piccole (circa 3 cm) fino a 200 g e mettile nel recipiente del Varoma; sopra metti 250 g di foglie di cavolo nero lavate, senza costa e spezzettate. Posiziona il Varoma chiuso sul coperchio e lascia finire la cottura. A fine tempo il farro deve essere tenero e broccoli e cavolo nero morbidissimi: se serve prolunga 3-5 min./Varoma/vel. 4.", "Togli il Varoma, estrai il cestello con la spatola e versa il farro in una ciotola capiente con 10 g di olio; sgranalo con una forchetta. Tieni da parte 200 g di acqua di cottura e svuota il boccale.", "Metti nel boccale broccoli e cavolo nero cotti, 570 g di cannellini lessati sciacquati e sgocciolati, 20 g del Parmigiano grattugiato e 150 g di acqua di cottura: frulla 1 min./vel. 5-9 aumentando gradualmente, fino a una crema verde liscia (se restano pellicine di cavolo nero frulla altri 30 sec./vel. 9).", "Preleva comunque la crema del bimbo di 1 anno prima del pesto (circa 150 g): il pesto di casa è salato, al massimo 1 cucchiaino nel suo piatto se ha già provato i pinoli. Se il bimbo di 3 anni non ha ancora mangiato pinoli, preleva anche la sua crema senza pesto (circa 200 g). Condisci con queste creme il farro dei bimbi. Aggiungi al resto della crema il pesto di casa e mescola 15 sec./vel. 4, senza scaldare, così resta profumato.", "Versa la crema al pesto sul farro e mescola bene, allungando con poca acqua di cottura se è densa. Servi prima i bimbi (per il bimbo di 1 anno schiaccia il farro con la forchetta nella crema), poi gli adulti con il Parmigiano rimasto; sale solo agli adulti e solo se serve, perché pesto e Parmigiano sono già saporiti."], "modifiche": ["Cannellini portati da 500 a 570 g lessati (dose legumi della famiglia, circa 190 g secchi) e frullati nella crema: nessun legume intero da schiacciare.", "Verdure: 200 g di cimette di broccoli e 250 g di foglie di cavolo nero senza costa (verdura di stagione che si sposa con il pesto) al posto di 350 g di broccoli e 100 g di spinaci, per non servire la terza crema verde di broccoli e spinaci in 5 cene.", "Un solo ciclo di 27 minuti: il Varoma con broccoli e cavolo nero si posiziona mentre l'acqua scalda, invece di aprirlo a metà cottura per aggiungere le foglie.", "Pesto di casa: 150 g (come nella nota del giorno), spostato in frigo sabato sera e aggiunto alla crema a freddo, senza scaldarlo.", "Parmigiano portato da 20 a 40 g: 20 g nella crema e 20 g per servire.", "Acqua del farro senza sale e niente sale nella crema: sale solo agli adulti, se serve.", "Crema del bimbo di 1 anno prelevata sempre prima del pesto (il pesto di casa è salato: al massimo 1 cucchiaino nel suo piatto, e solo se ha già provato i pinoli); quella del bimbo di 3 anni prelevata prima del pesto se non ha mai mangiato pinoli (allergene frutta a guscio da non proporre per la prima volta a cena).", "Capienza: circa 1,2 kg nel boccale per la frullata, 1,35 kg con il pesto; farro nel cestello (300 g) e verdure nel Varoma (450 g)."], "verduraNascosta": {"verdure": ["broccoli", "cavolo nero"], "grammiFamiglia": 450, "come": "Broccoli e cavolo nero cotti al vapore sopra il farro e frullati lisci con cannellini e Parmigiano in una crema a cui si aggiunge il pesto di casa.", "trucco": "Il verde è quello del pesto: i bimbi vedono un 'farro al pesto' cremoso, senza cimette né foglie. Chiamalo 'farro di Hulk' e servilo con tanto Parmigiano."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano e il formaggio stagionato del pesto, naturalmente senza lattosio; nessun altro latticino.", "notaBimbi": "Il pesto di casa contiene pinoli (allergene frutta a guscio) ed è già salato (sale grosso e formaggio stagionato): la crema del bimbo di 1 anno si preleva sempre prima del pesto (passo 7) e nel suo piatto va al massimo 1 cucchiaino di pesto, solo se ha già provato i pinoli. Se il bimbo di 3 anni non ha mai mangiato pinoli, non proporli per la prima volta a cena: preleva anche la sua crema prima del pesto. Cannellini frullati lisci, adatti a entrambi i bimbi; farro ben cotto, da schiacciare con la forchetta per il bimbo di 1 anno. Niente sale nei piatti dei bimbi. Contiene glutine (farro).", "scongelare": "pesto alla genovese di casa, circa 150 g", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "pesto alla genovese di casa", "qta": 150, "unita": "g", "reparto": "surgelati", "dispensa": false, "casa": true, "nota": "dal tuo freezer"}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "farro perlato", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "broccoli", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso delle cimette (circa 1 broccolo piccolo da 350 g)"}, {"nome": "cavolo nero", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso delle foglie senza costa (circa 1 mazzo da 400 g)"}, {"nome": "fagioli cannellini lessati", "qta": 570, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "peso sgocciolato e sciacquati (circa 2 barattoli e mezzo da 400 g), oppure 190 g secchi lessati senza sale"}, {"nome": "olio extravergine di oliva", "qta": 10, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, se serve"}], "accompagnamentoConsigliato": "Già completa (farro + cannellini + verdura nella crema al pesto); frutta a fine pasto.", "perche": "Seconda cena col pesto di casa, in una cena di legumi senza pasta: farro nel cestello e broccoli con cavolo nero nel Varoma in un'unica cottura, poi cannellini e verdure frullati col pesto in una crema verde. Ispirata a 'Farro al pesto e fagiolini' di Cookidoo (r717538, 4,7): i fagiolini, fuori stagione e visibili, sono sostituiti da broccoli e cavolo nero frullati.", "usataNelMese": true}, "r52640": {"id": "r52640", "fonte": "cookidoo", "titolo": "Involtini di sogliola al pesto di casa con riso verde", "url": "https://cookidoo.it/recipes/recipe/it-IT/r52640", "tm6": true, "valutazioneCookidoo": [4.2, 48], "tempoMin": 35, "porzioniRicetta": "4 porzioni", "categoria": "pesce", "ruolo": "completo", "cereale": "riso", "ingredientiOriginali": ["300 g di fagiolini verdi freschi", "4 filetti di pesce", "4 cucchiai di pesto", "1 pizzico di sale", "400 g di acqua"], "passi": ["Taglia 400 g di cimette di cavolo romanesco (1 cavolo da circa 800 g) e lavale. Tira fuori dal frigo il pesto di casa (150 g).", "Metti nel boccale asciutto 20 g di Parmigiano Reggiano a pezzi: 10 sec./vel. 10. Trasferiscilo in una ciotolina.", "Asciuga 550 g di filetti di sogliola con carta da cucina e stendili sul tagliere, controllando le lische. Tieni da parte 2 filetti senza pesto per ogni bimbo che non ha mai mangiato pinoli.", "Sugli altri filetti spalma un velo di pesto (60 g in tutto), SENZA sale, e arrotola ogni filetto su se stesso.", "Fodera il vassoio del Varoma con carta forno bagnata e strizzata, senza coprire le aperture frontali. Disponi gli involtini, quelli senza pesto da un lato.", "Metti le cimette di romanesco nel recipiente del Varoma.", "Metti nel boccale 1200 g di acqua, SENZA sale. Inserisci il cestello e pesaci 300 g di riso basmati.", "Posiziona il recipiente con il romanesco, sopra il vassoio con gli involtini, e chiudi il Varoma. Cuoci: 20 min./Varoma/vel. 4, finché il romanesco è tenero e la sogliola bianca e opaca.", "Togli il Varoma e tieni gli involtini coperti al caldo. Estrai il cestello con la spatola e versa il riso in una ciotola grande.", "Tieni da parte 150 g di acqua di cottura e svuota il boccale.", "Metti nel boccale il romanesco, 100 g di acqua di cottura, il Parmigiano e 10 g di olio: 40 sec./vel. 5-9 aumentando gradualmente. Se è troppo densa, aggiungi altra acqua di cottura.", "Solo se un bimbo non ha mai mangiato pinoli: preleva adesso circa 100 g di crema verde SENZA pesto per ciascuno e mescolala con la sua porzione di riso.", "Lascia intiepidire la crema 2 minuti, poi aggiungi 90 g di pesto: 10 sec./vel. 3. Mescola la crema con il resto del riso.", "Preleva le porzioni dei bimbi: riso verde (o quello senza pesto) e involtini (senza pesto per chi non ha mai provato i pinoli). Sbriciola la sogliola con la forchetta controllando bene le lische; per il bimbo di 1 anno pezzetti piccolissimi mescolati al riso.", "Metti da parte 1 porzione adulto per il pranzo di domani (riso verde e involtini) in un contenitore ermetico: in frigo appena intiepidita, da mangiare domani; scaldala al microonde coperta o in padella con 2 cucchiai di acqua. Poi servi gli adulti: sale solo nei loro piatti, se serve."], "modifiche": ["Fagiolini (fuori stagione e 'verdura visibile') sostituiti da 400 g di cavolo romanesco al vapore, frullato in una crema con Parmigiano e pesto: diventa il condimento del riso.", "Pesto = 150 g di pesto alla genovese di casa (60 g negli involtini, 90 g nella crema), aggiunto alla crema tiepida per non scurire il basilico.", "Cena completa: 300 g di riso basmati cotti nel cestello nello stesso tempo degli involtini e del romanesco, poi mescolati con la crema verde.", "Pesce = 550 g di filetti di sogliola (x1,4 rispetto ai 4 filetti della ricetta), sottili e perfetti da arrotolare; vanno benissimo surgelati.", "Per ogni bimbo che non ha ancora provato i pinoli (il bimbo di 1 anno e, se vale anche per lui, quello di 3 anni): 2 involtini senza pesto e circa 100 g di crema di romanesco prelevata prima del pesto.", "Niente sale nell'acqua né nella crema: il pesto è già saporito; sale solo per gli adulti, al piatto."], "verduraNascosta": {"verdure": ["cavolo romanesco"], "grammiFamiglia": 400, "come": "Il romanesco cotto al vapore viene frullato con Parmigiano, acqua di cottura e pesto: diventa la crema che condisce il riso.", "trucco": "Il 'riso verde al pesto' ha il colore del basilico: nessuna cimetta visibile, sembra solo riso al pesto."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano e i formaggi stagionati del pesto, naturalmente senza lattosio.", "notaBimbi": "ALLERGENE: il pesto contiene pinoli (frutta a guscio). Non proporli per la prima volta a cena: se il bimbo di 1 anno non li ha ancora mangiati a pranzo, dagli i 2 involtini senza pesto e il riso con la crema di romanesco prelevata prima del pesto. Vale anche per il bimbo di 3 anni, se non ha mai mangiato pinoli. Sogliola quasi senza lische, da sbriciolare e controllare; niente sale nei piatti dei bimbi.", "scongelare": "pesto alla genovese di casa, circa 150 g; filetti di sogliola surgelati (550 g), in frigo su un piatto", "gradimentoBimbiStimato": 4, "moltiplicatore": 1.4, "ingredienti": [{"nome": "pesto alla genovese di casa", "qta": 150, "unita": "g", "reparto": "surgelati", "dispensa": false, "casa": true, "nota": "dal tuo freezer"}, {"nome": "parmigiano reggiano", "qta": 20, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "sogliola filetti", "qta": 550, "unita": "g", "reparto": "pesce", "dispensa": false, "nota": "anche surgelato"}, {"nome": "riso basmati", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "cavolo romanesco", "qta": 400, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso delle cimette (1 cavolo da circa 800 g)"}, {"nome": "olio extravergine di oliva", "qta": 10, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, se serve"}], "accompagnamentoConsigliato": "Già completa (riso + sogliola + verdura nella crema al pesto).", "perche": "Abbina il pesto di casa al pesce: involtini di sogliola al Varoma con riso e romanesco nella stessa cottura, pronti in 35 minuti e senza pasta, con una versione senza pinoli per il più piccolo.", "passiCompleti": true, "usataNelMese": true}, "r903868": {"id": "r903868", "fonte": "cookidoo", "titolo": "Zuppa di cavolo, porri e ceci", "url": "https://cookidoo.it/recipes/recipe/it-IT/r903868", "tm6": true, "valutazioneCookidoo": [4.7, 74], "tempoMin": 30, "porzioniRicetta": "2 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "pane", "ingredientiOriginali": ["40 g di Parmigiano Reggiano, a pezzi", "60 g di porro", "100 g di pomodori perino", "15 g di olio extravergine di oliva", "200 g di cavolo verza", "250 g di ceci in scatola", "500 g di acqua", "30 g di dado per brodo vegetale", "fette di pane"], "passi": ["Accendi il forno a 200°C. Grattugia 60 g di Parmigiano Reggiano a pezzi 10 sec./vel. 10 e tienilo da parte.", "(mod.) Metti nel boccale 150 g di porri a rondelle: trita 3 sec./vel. 5 e riunisci sul fondo. Aggiungi 150 g di passata di pomodoro e 30 g di olio: insaporisci 3 min./120°C/vel. 1.", "(mod.) Aggiungi 350 g di verza a listarelle (senza la costa centrale dura), 540 g di ceci lessati sciacquati, 650 g di acqua e 1 cucchiaino raso di dado vegetale senza sale, niente sale: cuoci 18 min./100°C/vel. 1 con il cestello al posto del misurino.", "(mod.) Intanto taglia 190 g di pane a cubetti e tostalo in forno a 200°C per 8-10 minuti, finché è dorato; tieni da parte 1 fetta morbida, senza crosta, per il bimbo di 1 anno.", "(mod.) Frulla 1 min./vel. 5-10 aumentando gradualmente fino a una crema liscia; se è troppo densa aggiungi 50-100 g di acqua calda e frulla 10 sec./vel. 5.", "(mod.) Preleva subito le porzioni di entrambi i bimbi, senza sale: al bimbo di 1 anno il pane morbido spezzettato e ammollato nella crema al posto dei crostini. Poi sala solo i piatti degli adulti.", "Servi la crema con i crostini e il Parmigiano grattugiato.", "Pranzo di domani: metti da parte 1 porzione adulto di crema in un contenitore chiuso in frigo e i crostini in un sacchetto a parte; la crema si addensa, scaldala con un po' di acqua."], "modifiche": ["Ricetta x2 per la famiglia, con l'acqua ridotta a 650 g per restare sotto i 2,2 L del boccale.", "Porri portati a 150 g e verza a 350 g: la verdura nascosta arriva a 500 g.", "Pomodori perini sostituiti da 150 g di passata (a ottobre non sono di stagione).", "Dado ridotto da 30 g a 1 cucchiaino raso di dado vegetale senza sale (fatto in casa o senza sale aggiunto): la dose originale è troppo salata per i bimbi.", "Niente sale in cottura: sale solo nei piatti degli adulti, dopo aver prelevato le porzioni di entrambi i bimbi.", "Zuppa frullata in crema liscia (nell'originale verza e ceci restano a pezzi).", "Ceci portati a 540 g lessati (circa 190 g secchi) per 3,85 porzioni.", "Crostini tostati in forno senza olio; al bimbo di 1 anno pane morbido ammollato nella crema al posto dei crostini croccanti."], "verduraNascosta": {"verdure": ["verza", "porri"], "grammiFamiglia": 500, "come": "Verza e porri cuociono con i ceci e la passata e vengono frullati in una crema liscia color nocciola-rosato.", "trucco": "Pomodoro e Parmigiano coprono il gusto di cavolo. Presentala come 'crema di ceci con i crostini croccanti' e lascia che i bimbi ci tuffino i crostini da soli."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano stagionato, naturalmente privo di lattosio.", "notaBimbi": "Crema liscia senza pezzi, adatta anche al bimbo di 1 anno: porzioni di entrambi i bimbi prelevate prima del sale; al piccolo pane morbido ammollato nella crema al posto dei crostini croccanti. Ceci completamente frullati. La verza cotta a lungo è più digeribile. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo (usa pane senza semi; contiene glutine).", "scongelare": "", "gradimentoBimbiStimato": 3, "moltiplicatore": 2, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 60, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "porri", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito, parte bianca e verde chiaro (circa 2 porri)"}, {"nome": "passata di pomodoro", "qta": 150, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "verza", "qta": 350, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "circa mezza verza piccola"}, {"nome": "ceci lessati", "qta": 540, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "circa 2 barattoli e ¼ sgocciolati, oppure 190 g secchi lessati"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale (fatto in casa o senza sale aggiunto), raso"}, {"nome": "pane", "qta": 190, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "va benissimo raffermo; senza semi di sesamo"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver prelevato le porzioni dei bimbi"}], "accompagnamentoConsigliato": "Piatto unico: crema di ceci e crostini. Frutta di stagione a fine pasto.", "perche": "Ricetta molto votata e pronta in 30 minuti: ceci e verza diventano una crema liscia da mangiare con i crostini. Porta verza e porri al posto di zucca e carote.", "usataNelMese": false}, "r700542": {"id": "r700542", "fonte": "cookidoo", "titolo": "Vellutata di patate dolci, lenticchie rosse e latte di cocco", "url": "https://cookidoo.it/recipes/recipe/it-IT/r700542", "tm6": true, "valutazioneCookidoo": [4.7, 183], "tempoMin": 40, "porzioniRicetta": "6 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "bulgur", "ingredientiOriginali": ["30 g di olio extravergine di oliva", "400 g di patata americana dolce", "1 spicchio di aglio", "1 cucchiaino di sale", "70 g di lenticchie rosse, secche", "1 cucchiaio dado per brodo vegetale", "400 g di latte di cocco", "1 cucchiaino di cumino in polvere", "1 peperoncino piccante rosso, fresco", "2 rametti di coriandolo fresco", "400 g di acqua", "20 g di succo di lime, spremuto fresco", "10 g di fiocchi di cocco", "1 lime"], "passi": ["Prepara le verdure: sbuccia 450 g di patate dolci e tagliale a pezzi di 3 cm. Taglia a rondelle 150 g di porro (solo parte bianca e verde chiaro) e lavalo bene per togliere la terra. Sbuccia 1 spicchio di aglio.", "Metti nel boccale l'aglio, il porro e le patate dolci: trita 5 sec./vel. 5 e riunisci sul fondo con la spatola.", "Aggiungi 30 g di olio e insaporisci 5 min./120°C/vel. 1.", "Intanto sciacqua 190 g di lenticchie rosse decorticate in un colino sotto l'acqua corrente (non serve ammollo).", "Aggiungi nel boccale le lenticchie, ½ cucchiaino di cumino in polvere, 1 cucchiaino di dado vegetale senza sale e 750 g di acqua, senza sale. Metti il cestello sul coperchio al posto del misurino e cuoci 25 min./100°C/vel. 1.", "Intanto prepara il bulgur: in un pentolino porta a bollore 600 g di acqua, senza sale. Versa 300 g di bulgur, spegni, copri e lascialo gonfiare 15-20 minuti (se la confezione indica una cottura, cuocilo coperto 10-12 minuti a fuoco basso).", "A fine cottura patate dolci e lenticchie devono essere tenerissime (se no, altri 5 min./100°C/vel. 1). Agita bene la lattina di latte di cocco e tieni da parte 100 g in una tazzina.", "Versa nel boccale gli altri 300 g di latte di cocco. Con il misurino inserito frulla 1 min./vel. 5-10 aumentando gradualmente, fino a una crema liscia senza filamenti di porro.", "Sgrana il bulgur con una forchetta.", "Preleva le porzioni dei bimbi, senza sale né limone, e mescola in ognuna 2-3 cucchiai di bulgur. Per il bimbo di 1 anno controlla che il bulgur sia ben morbido e lascia intiepidire: le lenticchie sono già sciolte nella crema, non c'è niente da schiacciare.", "Solo adesso sala la vellutata rimasta nel boccale (è per gli adulti e per il pranzo di domani) e mescola 10 sec./vel. 3.", "Servi gli adulti nelle ciotole con il bulgur mescolato dentro. Completa con una spirale del latte di cocco tenuto da parte e, a piacere, qualche goccia di limone o lime.", "Per il pranzo di domani metti 1 porzione adulto di vellutata e una di bulgur in due contenitori separati, così il bulgur non assorbe tutta la crema. Appena intiepiditi riponili in frigo; scalda la vellutata con un po' di acqua e unisci il bulgur al momento."], "modifiche": ["Niente peperoncino, coriandolo né fiocchi di cocco; lime (o limone) facoltativo e solo nelle ciotole degli adulti, non in cottura.", "Lenticchie rosse decorticate da 70 a 190 g (dose legumi della famiglia, circa 570 g da cotte): la vellutata da primo diventa un piatto proteico. Sono decorticate: niente ammollo e si sciolgono nella crema.", "Patate dolci da 400 a 450 g e aggiunti 150 g di porri (solo parte bianca e verde chiaro), frullati nella crema: 600 g di verdura nascosta.", "Acqua da 400 a 750 g per cuocere le lenticchie in più; cottura allungata a 25 minuti per la quantità maggiore.", "Latte di cocco aggiunto a fine cottura, prima di frullare: in cottura nel boccale ci sono circa 1,6 kg (la schiuma delle lenticchie non esce dal coperchio) e al momento di frullare circa 1,9 kg, sotto la capienza del boccale da 2,2 L. 300 g nella crema, i 100 g rimasti per la spirale finale solo nelle ciotole degli adulti (il latte di cocco intero è ricco di grassi saturi; va bene anche quello light).", "Cumino ridotto a ½ cucchiaino. Sale eliminato dalla cottura e dado limitato a 1 cucchiaino di dado vegetale senza sale: si sala solo la parte degli adulti dopo aver prelevato le porzioni dei due bimbi.", "Aggiunti 300 g di bulgur come cereale (con 600 g di acqua senza sale), fatto gonfiare in un pentolino mentre cuoce la vellutata e mescolato nelle ciotole (come nella zuppa turca di lenticchie): diventa un piatto unico."], "verduraNascosta": {"verdure": ["patate dolci", "porri"], "grammiFamiglia": 600, "come": "Patate dolci e porri cuociono con le lenticchie rosse e vengono frullati con il latte di cocco in una vellutata arancio chiaro, dolce e liscia.", "trucco": "Il latte di cocco la rende dolce e vellutata; il bulgur a chicchi piccoli sembra riso e trasforma la crema in un piatto unico da mangiare col cucchiaio."}, "lattosio": "no", "notaLattosio": "Nessun latticino: il latte di cocco è vegetale.", "notaBimbi": "Crema liscia e dolce, adatta a entrambi i bimbi: le loro porzioni si prelevano prima del sale e del limone. Le lenticchie rosse decorticate si sciolgono nella crema frullata, quindi non ci sono legumi interi da schiacciare. Per il bimbo di 1 anno bulgur ben gonfio e morbido, mescolato nella crema, e vellutata tiepida. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo, ma controlla l'etichetta del bulgur: se indica tracce di sesamo e i bimbi non l'hanno mai provato, scegline un altro. Il bulgur è grano (glutine, come la pasta). La spirale di latte di cocco è solo per gli adulti. Il cocco non è frutta a guscio per le norme UE sugli allergeni, ma se i bimbi non l'hanno mai assaggiato fallo provare prima a pranzo, non per la prima volta a cena.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "bulgur", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "medio o fine"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "porri", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "solo parte bianca e verde chiaro (circa 1 porro grande)"}, {"nome": "patate dolci", "qta": 450, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito (circa 2 patate dolci medie)"}, {"nome": "lenticchie rosse decorticate", "qta": 190, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "secche, niente ammollo"}, {"nome": "cumino", "qta": 0.5, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "in polvere"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale aggiunto (fatto in casa)"}, {"nome": "latte di cocco", "qta": 400, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "1 lattina da cucina (non la bevanda), vegetale e senza lattosio; va bene anche light: 300 g nella crema, 100 g per la spirale nelle ciotole degli adulti"}, {"nome": "limoni", "qta": null, "unita": "q.b.", "reparto": "frutta_verdura", "dispensa": false, "nota": "lo stesso limone di giovedì, facoltativo, solo per gli adulti (va bene anche 1 lime)"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nella vellutata degli adulti, dopo aver prelevato le porzioni dei bimbi"}], "accompagnamentoConsigliato": "Piatto unico; per chi ha più fame qualche fetta di pane tostato.", "perche": "Vellutata molto votata e pronta in circa 40 minuti senza nulla da preparare il giorno prima: con più lenticchie rosse e il bulgur diventa una cena completa, dolce e cremosa, e porta patate dolci e porri dando una pausa a zucca e carote, già al limite delle 7 cene nel mese.", "passiCompleti": true, "usataNelMese": true}, "r70733": {"id": "r70733", "fonte": "cookidoo", "titolo": "Zuppa di verza con bastoncini di pollo", "url": "https://cookidoo.it/recipes/recipe/it-IT/r70733", "tm6": true, "valutazioneCookidoo": [3.9, 65], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "carne_bianca", "ruolo": "completo", "cereale": "pane", "ingredientiOriginali": ["1 spicchio di aglio", "100 g di pangrattato", "1 mazzetto di erbe aromatiche secche miste", "20 g di pecorino", "400 g di petto di pollo", "1 cipolla", "30 g olio extravergine di oliva", "100 g di pancetta affumicata a cubetti", "500 g di cavolo verza", "5 di pomodorini ciliegia", "500 g di brodo vegetale"], "passi": ["Preriscalda il forno a 200°C ventilato e fodera una teglia con carta forno. Metti nel boccale 100 g di pangrattato e 30 g di Parmigiano a pezzi: trita 15 sec./vel. 8 e trasferisci in un piatto fondo.", "Senza lavare il boccale, metti 80 g di cipolla a pezzi e trita 5 sec./vel. 5. Riunisci sul fondo con la spatola, aggiungi 20 g di olio e insaporisci 3 min./120°C/vel. 1 (niente pancetta).", "Aggiungi 500 g di foglie di verza a pezzi (senza torsolo e coste dure) e trita 5 sec./vel. 5, così occupa meno spazio. Aggiungi 350 g di patate a cubetti di 2 cm, 50 g di passata di pomodoro, 600 g di acqua e 1 cucchiaino di dado vegetale senza sale: cuoci 25 min./100°C/vel. 1 con il cestello sul coperchio al posto del misurino.", "Intanto taglia 400 g di petto di pollo a bastoncini (circa 1,5 x 6 cm), passali in 1 uovo sbattuto con 1 cucchiaio di acqua e poi nel pangrattato al Parmigiano, premendo bene. Disponili sulla teglia, irrora con 20 g di olio e cuoci in forno 15-18 minuti girandoli a metà, finché sono dorati fuori e bianchi e cotti al centro.", "A fine cottura frulla la zuppa 1 min./vel. 5-10 aumentando gradualmente, fino a una crema liscia senza filamenti di verza (se è troppo densa aggiungi un po' di acqua calda e frulla ancora 10 sec./vel. 5).", "Preleva la crema dei due bimbi, poi aggiusta di sale solo quella degli adulti.", "Servi la crema nelle ciotole e i bastoncini a parte, da intingere nella crema come in una salsa, con il pane per la scarpetta."], "modifiche": ["Bastoncini di pollo cotti in forno a 200°C ventilato invece che nel Varoma: restano croccanti come i fish finger e piacciono di più ai bimbi; cuociono mentre il Bimby fa la zuppa.", "Panatura: 1 uovo sbattuto con 1 cucchiaio di acqua prima del pangrattato, così aderisce; pecorino sostituito da 30 g di Parmigiano (meno salato); erbe aromatiche secche e aglio omessi (gusto delicato, niente puntini verdi).", "Pancetta affumicata eliminata (niente affumicati per i bimbi).", "Cipolla (80 g) e verza (500 g) tritate nel boccale prima della cottura, così la verza sta nel boccale; aggiunti 350 g di patate e zuppa frullata in una crema liscia.", "Brodo vegetale sostituito da 600 g di acqua e 1 cucchiaino di dado vegetale senza sale; pomodorini (fuori stagione) sostituiti da 50 g di passata.", "Niente sale in cottura né sui bastoncini: sale solo nella crema degli adulti, dopo aver prelevato le porzioni dei bimbi.", "Pane (200 g) per la scarpetta: la cena diventa completa. Nessuna base della domenica."], "verduraNascosta": {"verdure": ["verza", "cipolle"], "grammiFamiglia": 580, "come": "Verza e cipolla cuociono con le patate e vengono frullate in una crema chiara e densa, servita come zuppa e come salsa per i bastoncini.", "trucco": "I bastoncini dorati da intingere spostano l'attenzione: la crema diventa la 'salsa magica' e le patate ne addolciscono il gusto."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano stagionato, naturalmente privo di lattosio; pane comune senza latte (leggi l'etichetta se è pane in cassetta).", "notaBimbi": "Per il bimbo di 1 anno taglia i bastoncini a pezzetti, controlla che il pollo sia bianco e cotto al centro e ammorbidisci la panatura nella crema. Uovo della panatura ben cotto in forno. Crema liscia e senza sale per entrambi i bimbi (prelevata prima di salare). Nessun allergene tra quelli da segnalare.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "pangrattato", "qta": 100, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "parmigiano reggiano", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "petto di pollo", "qta": 400, "unita": "g", "reparto": "carne", "dispensa": false, "nota": "intero, da tagliare a bastoncini; se la cena cade a più di 2 giorni dalla spesa congelalo subito già tagliato e mettilo in frigo la sera prima"}, {"nome": "uova", "qta": 1, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": "per la panatura"}, {"nome": "olio extravergine di oliva", "qta": 40, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "20 g per il soffritto + 20 g sui bastoncini"}, {"nome": "cipolle", "qta": 80, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "1 cipolla piccola"}, {"nome": "verza", "qta": 500, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "circa mezza verza media: peso delle foglie senza torsolo"}, {"nome": "patate", "qta": 350, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "passata di pomodoro", "qta": 50, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale"}, {"nome": "pane", "qta": 200, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "per la scarpetta"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nella crema degli adulti, dopo aver prelevato quella dei bimbi"}], "accompagnamentoConsigliato": "Pane (200 g) per la scarpetta; i bastoncini fanno da secondo.", "perche": "I bastoncini di pollo al forno sono tra i piatti più graditi ai bimbi: qui arrivano con una crema di verza e patate da intingere, che porta mezzo chilo di verza senza farla vedere. Si fa in 40 minuti senza basi della domenica: i bastoncini cuociono in forno mentre il Bimby fa la zuppa.", "usataNelMese": false}, "r827280": {"id": "r827280", "fonte": "cookidoo", "titolo": "Polenta con ragù di pollo e verdure nascoste", "url": "https://cookidoo.it/recipes/recipe/it-IT/r827280", "tm6": true, "valutazioneCookidoo": [4.4, 47], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "carne_bianca", "ruolo": "completo", "cereale": "polenta", "ingredientiOriginali": ["50 g queso cheddar", "200 g de verduras variadas", "50 g de aceite de oliva", "600 g de carne picada de pollo", "40 g de vino tinto", "½ cucharadita de sal", "2 - 3 pellizcos de pimienta molida", "20 g de tomate concentrado", "1 pastilla de caldo de verduras", "100 g de tomate frito", "500 g de agua", "1 cucharadita sal", "400 g de leche", "150 g de polenta", "60 g de mantequilla"], "passi": ["Il macinato di pollo deve essere già scongelato (in frigo da ieri sera). Lava finocchio, cavolo cappuccio e verza; togli la base del finocchio, il torsolo del cavolo, le foglie esterne dure e le coste della verza.", "Pesa 150 g di finocchio, 150 g di cavolo cappuccio e 100 g di foglie interne di verza e tagliali a pezzi di 3-4 cm.", "Metti nel boccale asciutto 40 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10. Trasferiscilo in una ciotolina e tienilo da parte per la polenta.", "Metti nel boccale (non serve lavarlo) finocchio, cavolo cappuccio e verza: trita 10 sec./vel. 7. Riunisci sul fondo con la spatola e trita ancora 5 sec./vel. 8, fino a un trito finissimo senza pezzetti riconoscibili.", "Aggiungi 30 g di olio e soffriggi 7 min./120°C/vel. 1 senza misurino, così l'acqua delle verdure evapora.", "Aggiungi 400 g di macinato di pollo, sgranalo con la spatola e rosola 5 min./120°C/antiorario/vel. 1 senza misurino. Niente vino.", "Aggiungi 20 g di concentrato di pomodoro, 200 g di passata, 150 g di acqua e ½ cucchiaino di dado vegetale senza sale (nessun altro sale). Cuoci 20 min./100°C/antiorario/vel. 1 con il cestello sul coperchio al posto del misurino.", "Quando il ragù è a metà cottura prepara la polenta: in una pentola capiente porta a bollore 1100 g di acqua e 400 g di latte senza lattosio, senza sale, a fiamma media. Controlla che il latte non trabocchi.", "Abbassa la fiamma e versa a pioggia 300 g di polenta istantanea mescolando con la frusta. Cuoci 5-8 minuti (secondo la confezione), mescolando spesso con un cucchiaio di legno.", "Controlla il ragù a fine cottura: se è troppo liquido togli il cestello e prosegui 3 min./Varoma/antiorario/vel. 1; se restano grumi di carne mescola 5 sec./antiorario/vel. 4.", "Spegni la polenta e unisci 30 g di burro senza lattosio e il Parmigiano grattugiato, mescolando bene. Deve restare morbida e cremosa: se si rassoda aggiungi un mestolino di acqua calda.", "Preleva le porzioni dei bimbi: polenta nel piatto e ragù sopra, senza sale. Per il bimbo di 1 anno schiaccia con la forchetta eventuali pezzetti, mescola ragù e polenta e lascia intiepidire.", "Solo ora aggiungi 1-2 pizzichi di sale alla polenta e al ragù rimasti per gli adulti (pepe a piacere) e mescola.", "Servi la polenta nei piatti con il ragù sopra. Metti da parte 1 porzione adulto per il pranzo di domani in un contenitore chiuso e, appena intiepidita, in frigo: la polenta si rassoda, scaldala a fette in padella o al microonde con il ragù sopra."], "modifiche": ["Verduras variadas (200 g) raddoppiate e scelte fra quelle di ottobre: 150 g di finocchio, 150 g di cavolo cappuccio e 100 g di verza (foglie interne senza costa, al posto del porro per non superare le 7 cene di porri nel mese), tritati finissimi a vel. 8 e soffritti senza misurino per farli sparire nel ragù.", "Vino rosso eliminato; tomate frito sostituito da 200 g di passata di pomodoro più 150 g di acqua.", "Macinato di pollo ridotto da 600 a 400 g (dose carne della famiglia) e olio da 50 a 30 g.", "Niente sale nel ragù e nella polenta (prima ½ + 1 cucchiaino di sale e 1 dado intero): solo ½ cucchiaino di dado vegetale senza sale; sale e pepe solo agli adulti dopo aver servito i bimbi.", "Cheddar sostituito da 40 g di Parmigiano Reggiano; latte e burro senza lattosio, burro ridotto da 60 a 30 g.", "Polenta istantanea portata da 150 a 300 g (dose cereali della famiglia) con 1100 g di acqua e 400 g di latte, cotta in pentola mentre il Bimby cuoce il ragù: nel boccale, dopo il ragù, servirebbero altri 15 minuti e la cena supererebbe i 45 minuti.", "Macinato di pollo: la spesa è sabato 24 e la cena martedì 27, quindi congelalo il giorno della spesa e spostalo in frigo lunedì sera (oppure compralo fresco lunedì o martedì).", "Ricetta spagnola disponibile su Cookidoo Italia: passi tradotti e adattati."], "verduraNascosta": {"verdure": ["finocchi", "cavolo cappuccio", "verza"], "grammiFamiglia": 400, "come": "Finocchio, cavolo cappuccio e verza tritati finissimi a vel. 8, soffritti e cotti 20 minuti nel ragù di pollo al pomodoro, dove spariscono.", "trucco": "Nel ragù rosato il trito non si distingue dalla carne; la polenta cremosa col formaggio è la 'pappa gialla' che piace a tutti."}, "lattosio": "sostituito", "notaLattosio": "Latte e burro senza lattosio; Parmigiano Reggiano stagionato naturalmente privo di lattosio.", "notaBimbi": "Ragù di carne macinata ben cotta con trito finissimo e polenta morbida: adatti anche al bimbo di 1 anno (se trova qualche pezzetto, schiaccia con la forchetta). Niente sale né nel ragù né nella polenta dei bimbi. Il cavolo cotto a lungo è digeribile e il suo gusto si perde nel pomodoro. Nessun allergene della lista.", "scongelare": "macinato di pollo (400 g), se congelato il giorno della spesa: in frigo la sera prima", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "finocchi", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito (un finocchio medio pulito pesa circa 200 g)"}, {"nome": "cavolo cappuccio", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "bianco, circa ¼ di cavolo piccolo"}, {"nome": "verza", "qta": 100, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "foglie interne senza costa"}, {"nome": "olio extravergine di oliva", "qta": 30, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "macinato di pollo", "qta": 400, "unita": "g", "reparto": "carne", "dispensa": false, "nota": "o di tacchino; comprato sabato, congelalo subito (o compralo fresco lunedì o martedì)"}, {"nome": "concentrato di pomodoro", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "passata di pomodoro", "qta": 200, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": ""}, {"nome": "dado vegetale", "qta": 0.5, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale"}, {"nome": "latte senza lattosio", "qta": 400, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "polenta istantanea", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "burro senza lattosio", "qta": 30, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver servito i bimbi"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, facoltativo"}], "accompagnamentoConsigliato": "Completo così (polenta cremosa e ragù di pollo); frutta a fine pasto.", "perche": "Un ragù di pollo in 40 minuti con finocchio, cavolo cappuccio e verza che spariscono nel pomodoro, su una polenta cremosa cotta in pentola mentre il Bimby lavora. Alternativa leggera al ragù di manzo, con la polenta come cereale.", "passiCompleti": true, "usataNelMese": true}, "c-gnocchi-ragu-casa-sedano-rapa": {"id": "c-gnocchi-ragu-casa-sedano-rapa", "fonte": "personalizzata", "titolo": "Gnocchi al ragù di casa con crema di sedano rapa e verza", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 30, "porzioniRicetta": "3,85 porzioni (famiglia: 2 adulti + 1 porzione pranzo + 2 bimbi)", "categoria": "carne_rossa", "ruolo": "completo", "cereale": "gnocchi", "ingredientiOriginali": [], "passi": ["La sera prima sposta dal congelatore al frigo la vaschetta di ragù classico di casa (circa 600 g).", "Metti nel boccale 40 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10; trasferisci in una ciotolina.", "Metti nel boccale 250 g di sedano rapa pelato a pezzi e 150 g di foglie di verza senza la costa centrale, a pezzi: trita 6 sec./vel. 6 e riunisci sul fondo con la spatola.", "Aggiungi 10 g di olio e 150 g di acqua: cuoci 15 min./100°C/vel. 1 con il cestello al posto del misurino, finché il sedano rapa è tenerissimo. Intanto metti sul fuoco una pentola capiente di acqua senza sale per gli gnocchi.", "Frulla 40 sec./vel. 5-10 aumentando gradualmente fino a una crema liscia. Tieni da parte in una tazza 2-3 cucchiai di crema per la porzione del bimbo di 1 anno.", "Aggiungi nel boccale il ragù di casa scongelato: scalda 8 min./100°C/antiorario/vel. 1 con il cestello al posto del misurino (5 minuti in più se il ragù è ancora in parte congelato). Crema e ragù diventano un sugo unico.", "Negli ultimi 5 minuti cuoci 1 kg di gnocchi di patate nell'acqua bollente senza sale finché salgono a galla (2-3 minuti; in 2 volte se la pentola è piccola) e scolali con la schiumarola.", "Condisci gli gnocchi con il ragù e il Parmigiano. Preleva le porzioni dei bimbi (in quella del piccolo mescola la crema tenuta da parte, per diluire il sale del ragù), poi sala gli adulti solo se serve."], "modifiche": ["Verza al posto dei porri: i porri sono già in 7 cene del mese. La crema resta chiara e dolce e nel ragù non si riconosce.", "Niente sale nella crema né nell'acqua degli gnocchi: il ragù di casa è già saporito; gli adulti salano nel piatto se serve.", "Ragù scaldato in senso antiorario a velocità 1, così la carne non si sminuzza. Nessuna base della domenica."], "verduraNascosta": {"verdure": ["sedano rapa", "verza"], "grammiFamiglia": 400, "come": "Sedano rapa e verza cotti e frullati in una crema liscia in cui si scalda il ragù di casa: diventa un unico sugo, più abbondante e vellutato.", "trucco": "Il sedano rapa sa di sedano del soffritto e la verza cotta è dolce: nel ragù non si riconoscono e il colore resta quello di sempre."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano stagionato, naturalmente senza lattosio. Se nel tuo ragù di casa hai messo latte normale (come nella bolognese classica), tienine conto.", "notaBimbi": "Gnocchi morbidi: per il bimbo di 1 anno tagliali a metà o in 4, non darli interi. Acqua di cottura senza sale e nessun sale aggiunto; nel piatto del piccolo mescola al ragù la crema tenuta da parte. Se il tuo ragù contiene pancetta o salsiccia, ai bimbi dai più crema e meno ragù. Nessun allergene tra quelli da segnalare.", "scongelare": "ragù classico di casa, circa 600 g", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "ragù classico di casa", "qta": 600, "unita": "g", "reparto": "surgelati", "dispensa": false, "casa": true, "nota": "dal tuo freezer"}, {"nome": "sedano rapa", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito"}, {"nome": "verza", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "foglie senza la costa centrale"}, {"nome": "olio extravergine di oliva", "qta": 10, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "gnocchi di patate", "qta": 1000, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "freschi, 1 kg (o 2 confezioni da 500 g)"}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto, se serve"}], "accompagnamentoConsigliato": "Già completa (gnocchi + ragù di casa + verdura nel sugo); frutta a fine pasto.", "perche": "Una delle 2 cene con il ragù di casa, senza pasta (già al limite nel mese): in circa 30 minuti, con 400 g di sedano rapa e verza fusi nel sugo.", "usataNelMese": false}, "r125528": {"id": "r125528", "fonte": "cookidoo", "titolo": "Passatelli", "url": "https://cookidoo.it/recipes/recipe/it-IT/r125528", "tm6": true, "valutazioneCookidoo": [4.5, 323], "tempoMin": 50, "porzioniRicetta": "4 porzioni", "categoria": "uova", "ruolo": "completo", "cereale": "pane", "ingredientiOriginali": ["200 g di Parmigiano Reggiano", "200 g di pangrattato", "4 uova", "2 pizzichi di noce moscata in polvere"], "passi": ["Metti nel boccale 200 g di Parmigiano Reggiano a pezzi: 15 sec./vel. 10.", "Aggiungi 250 g di pangrattato fine, 7 uova, 2 pizzichi di noce moscata e, se vuoi, la scorza finissima di ½ limone (solo la parte gialla), SENZA sale: 2 min./Spiga.", "Trasferisci l'impasto sul piano, compattalo con le mani in un panetto, avvolgilo nella pellicola e mettilo in frigo per 30 minuti. Lava il boccale.", "Intanto pulisci le verdure del brodo: 200 g di porri (parte bianca e verde chiaro, ben lavati), 250 g di sedano rapa pelato, 150 g di finocchio e 150 g di patate pelate, tutto a pezzi.", "Metti le verdure nel boccale con 20 g di olio: 5 sec./vel. 5. Riunisci sul fondo con la spatola.", "Insaporisci: 5 min./120°C/vel. 1.", "Aggiungi 900 g di acqua e 1 cucchiaino di dado vegetale senza sale, SENZA sale: 25 min./100°C/vel. 1, con il cestello sul coperchio al posto del misurino.", "Rimetti il misurino e frulla: 1 min./vel. 5-10 aumentando gradualmente, fino a un brodo liscio senza filamenti.", "Metti da parte in un pentolino circa 350 g (2-3 mestoli) di brodo cremoso per i bimbi, senza allungarlo, e tienilo al caldo a fuoco bassissimo.", "Versa il resto del brodo in una pentola larga, aggiungi circa 600 g di acqua calda e porta a leggero bollore. Deve restare fluido come un brodo.", "Fai una prova: schiaccia 2-3 passatelli nel brodo. Se si sfaldano, aggiungi all'impasto 2-3 cucchiai di pangrattato e impasta con le mani.", "Forma i passatelli con lo schiacciapatate a fori larghi direttamente sopra la pentola, tagliandoli con un coltello ogni 4-5 cm.", "Cuocili 2-3 minuti a fuoco dolce, finché salgono a galla. Spegni e lasciali riposare 2 minuti.", "Preleva le porzioni dei bimbi: passatelli presi con la schiumarola e conditi con il brodo cremoso del pentolino. Per il bimbo di 1 anno tagliali a pezzetti di 1 cm e fai intiepidire.", "Metti da parte 1 porzione adulto per il pranzo di domani: passatelli scolati con la schiumarola e brodo in due contenitori separati, in frigo appena tiepidi; domani scalda il brodo e aggiungi i passatelli all'ultimo minuto. Poi servi gli adulti: sale e pepe solo nei loro piatti, se serve."], "modifiche": ["Impasto più ricco di uova, in proporzioni vicine a quelle tradizionali romagnole: 7 uova, 250 g di pangrattato (più 2-3 cucchiai per correggere) e 200 g di Parmigiano, circa 835 g di impasto (circa ×1,4 in peso sull'originale, circa 215 g per porzione adulto): è un piatto unico. Meno Parmigiano e più uova rispetto alla dose originale moltiplicata: meno sale per i bimbi e le uova come proteina principale.", "Passatelli cotti in un brodo cremoso di porri, sedano rapa, finocchio e patate frullati, al posto del brodo di carne, allungato in pentola perché resti fluido.", "Brodo nel boccale con 900 g di acqua (circa 1,7 kg in tutto, comodo nella capienza del boccale anche mentre si frulla) e altri 600 g di acqua calda aggiunti in pentola.", "Prima di allungare il brodo metti da parte 2-3 mestoli di brodo cremoso per i bimbi: così la verdura frullata arriva davvero nei loro piatti.", "Niente sale nell'impasto né nel brodo: basta il Parmigiano; al massimo 1 cucchiaino di dado vegetale senza sale. Chi vuole sala il proprio piatto dopo aver servito i bimbi.", "Scorza di limone facoltativa, grattugiata finissima solo nella parte gialla.", "Il brodo cuoce mentre l'impasto riposa in frigo: circa 50 minuti in tutto, adatto alla domenica sera. La purea di zucca si fa al mattino, quindi il Bimby è libero."], "verduraNascosta": {"verdure": ["porri", "sedano rapa", "finocchi"], "grammiFamiglia": 600, "come": "Porri, sedano rapa e finocchio (con un po' di patata) vengono cotti e frullati: diventano il brodo chiaro e leggermente cremoso in cui cuociono i passatelli; per i bimbi se ne mettono da parte 2-3 mestoli prima di allungarlo, così la loro porzione ha più verdura.", "trucco": "Sembra un normale brodo un po' più 'ricco' e il sapore di Parmigiano dei passatelli copre tutto: nessun pezzetto, nessun puntino verde."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano stagionato, naturalmente privo di lattosio.", "notaBimbi": "Uova ben cotte nei passatelli bolliti. Contiene glutine (pangrattato); nessun allergene tra crostacei, molluschi, frutta a guscio o sesamo, ma controlla l'etichetta del pangrattato: se indica tracce di sesamo e i bimbi non l'hanno mai provato, scegline un altro. Le porzioni dei bimbi si condiscono con il brodo cremoso non allungato messo da parte (più verdura). Per il bimbo di 1 anno taglia i passatelli a pezzetti di 1 cm. Brodo e impasto senza sale, adatti anche a lui.", "scongelare": "", "gradimentoBimbiStimato": 5, "moltiplicatore": 1.4, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 200, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "a pezzi, stagionato"}, {"nome": "pangrattato", "qta": 250, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "fine, 1 confezione da 500 g (serve anche per i nuggets di martedì); tienine 2-3 cucchiai in più per correggere l'impasto"}, {"nome": "uova", "qta": 7, "unita": "pz", "reparto": "latticini_uova", "dispensa": false, "nota": "7 per l'impasto dei passatelli di domenica (altre 2 servono per la panatura dei nuggets di martedì)"}, {"nome": "noce moscata", "qta": 2, "unita": "pizzichi", "reparto": "spezie_condimenti", "dispensa": true, "nota": ""}, {"nome": "limoni", "qta": 0.5, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "1 limone basta per tutta la settimana: scorza di ½ domenica (facoltativa), scorza per gli adulti giovedì, qualche goccia venerdì"}, {"nome": "porri", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "parte bianca e verde chiaro"}, {"nome": "sedano rapa", "qta": 250, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito: compra circa il 35% in più (buccia spessa)"}, {"nome": "finocchi", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "circa ½ finocchio"}, {"nome": "patate", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale aggiunto (fatto in casa)"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo nei piatti degli adulti, dopo aver servito i bimbi"}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, nel piatto"}], "accompagnamentoConsigliato": "Piatto unico; frutta a fine pasto. Serve lo schiacciapatate a fori larghi (o il ferro per passatelli).", "perche": "Piatto a base di uova diverso dalle solite frittate e amatissimo dai bimbi; il brodo di verdure frullate porta 600 g di porri, sedano rapa e finocchio. Impasto con 7 uova, 250 g di pangrattato e 200 g di Parmigiano: le uova sono la proteina principale, con meno formaggio (e meno sale) rispetto alla dose originale moltiplicata.", "passiCompleti": true, "usataNelMese": true}, "r399588": {"id": "r399588", "fonte": "cookidoo", "titolo": "Crema di broccoli e porri", "url": "https://cookidoo.it/recipes/recipe/it-IT/r399588", "tm6": true, "valutazioneCookidoo": [4.4, 562], "tempoMin": 45, "porzioniRicetta": "2 porzioni (qui x2,5: circa 1,5 kg di crema densa, base per 2 cene)", "categoria": "vegetale", "ruolo": "base", "cereale": "nessuno", "ingredientiOriginali": ["150 g di porri", "1 spicchio di aglio", "30 g di olio extravergine di oliva", "300 g di cimette di broccoli", "400 g acqua", "1 cucchiaino di dado per brodo vegetale", "1 pizzico di sale", "1 pizzico di peperoncino piccante rosso"], "passi": ["Domenica 18 al mattino pulisci i porri: togli radici e verde scuro, tagliali per il lungo e lavali bene tra le foglie. Tagliane 300 g a rondelle e sbuccia 1 spicchio di aglio (facoltativo).", "Dividi i broccoli in cimette, pela i gambi con il pelapatate e tagliali a rondelle sottili: 750 g in tutto. Lavali e mettili nel recipiente del Varoma, gambi sotto e cimette sopra (se serve usa anche il vassoio).", "Metti nel boccale porri e aglio: trita 5 sec./vel. 5 e riunisci sul fondo con la spatola.", "Aggiungi 40 g di olio e insaporisci 5 min./120°C/vel. 1.", "Aggiungi 600 g di acqua e 1 cucchiaino raso di dado vegetale senza sale (niente sale né peperoncino). Se usi spinaci surgelati, aggiungi ora nel boccale i 150 g di spinaci.", "Posiziona il Varoma con i broccoli e cuoci 22 min./Varoma/vel. 1.", "Controlla un gambo con la forchetta: deve essere molto tenero (se no, altri 5 min./Varoma/vel. 1). Togli il Varoma con attenzione.", "Aggiungi nel boccale 150 g di spinaci freschi lavati e cuoci 3 min./100°C/vel. 1. Se hai già messo gli spinaci surgelati, salta questo passo.", "Aggiungi metà dei broccoli e trita 10 sec./vel. 5, così nel boccale si fa spazio.", "Aggiungi il resto dei broccoli e, con il misurino inserito, frulla 1 min./vel. 5-10 aumentando gradualmente: crema liscia e densa come un purè morbido (circa 1,5 kg). Se è troppo densa aggiungi acqua calda a cucchiai.", "Dividi in 2 vaschette con etichetta e data: A circa 650 g ('mer 21 - trota, purè verde') e B il resto, circa 850 g ('gio 22 - pasta e piselli').", "Raffreddale in fretta: vaschette basse in una bacinella di acqua fredda, al massimo 1 ora fuori dal frigo. Poi metti A e B in congelatore.", "Martedì 20 sera sposta la vaschetta A dal congelatore al frigo, mercoledì 21 sera la vaschetta B. Riscalda ogni vaschetta una volta sola, nel Bimby, come indicato nelle due ricette."], "modifiche": ["Dose x2,5 come base per 2 cene: 300 g di porri, 750 g di broccoli e 150 g di spinaci, circa 1,2 kg di verdura in tutto.", "Broccoli cotti al Varoma sopra il brodo di porri invece che nel boccale con 1 kg di acqua: tutto resta nella capienza del boccale da 2,2 L (circa 1,6 kg al momento di frullare) e la crema viene densa, adatta sia al purè sia come sugo.", "Aggiunti 150 g di spinaci, cotti 3 minuti nel brodo alla fine: crema più verde e più verdura.", "Sale e peperoncino eliminati; 1 solo cucchiaino raso di dado vegetale senza sale per tutta la scorta: adatta al bimbo di 1 anno.", "Resa circa 1,5 kg divisa in 2 vaschette, entrambe in congelatore (in frigo non devono restare più di 3 giorni): A circa 650 g (circa 520 g di verdura) per il purè verde della trota di mercoledì 21, in frigo martedì sera; B circa 850 g (circa 680 g di verdura) per la pasta e piselli di giovedì 22, in frigo mercoledì sera. Se la resa è maggiore, l'eccesso va nella vaschetta B.", "Base usata solo in queste 2 cene del mese."], "verduraNascosta": {"verdure": ["broccoli", "porri", "spinaci"], "grammiFamiglia": 1200, "come": "Totale della scorta: broccoli, porri e spinaci cotti e frullati in una crema densa e liscia. La vaschetta A (circa 520 g di verdura) diventa il purè verde con le patate; la vaschetta B (circa 680 g di verdura) si frulla con i piselli e condisce la pasta.", "trucco": "Densa come un purè e senza filamenti (gambi pelati, frullata a vel. 10): mescolata a patate o piselli sembra solo un purè o una crema 'verde Hulk'."}, "lattosio": "no", "notaLattosio": "Nessun latticino.", "notaBimbi": "Senza sale né peperoncino, liscia e senza filamenti: adatta anche al bimbo di 1 anno. Contiene spinaci: raffreddala in fretta, congela subito le due vaschette, scongelale in frigo la sera prima e riscaldale una volta sola. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo.", "scongelare": "", "gradimentoBimbiStimato": 4, "moltiplicatore": 2.5, "ingredienti": [{"nome": "porri", "qta": 300, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito, parte bianca e verde chiaro: circa 2-3 porri"}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": "facoltativo"}, {"nome": "olio extravergine di oliva", "qta": 40, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "broccoli", "qta": 750, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso di cimette e gambi pelati: compra circa 1,1 kg di broccoli interi (3 broccoli)"}, {"nome": "spinaci", "qta": 150, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "freschi, già lavati (oppure 150 g surgelati)"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale, raso"}], "accompagnamentoConsigliato": "Base della domenica 18: circa 650 g nel purè verde della trota (mercoledì 21) e circa 850 g nella pasta e piselli (giovedì 22).", "perche": "Crema verde molto votata (4,4 su 562), alternativa al sugo arancione: la domenica mattina in 45 minuti porta circa 1,2 kg di broccoli, porri e spinaci, più di 500 g in ciascuna delle 2 cene della settimana.", "passiCompleti": true, "usataNelMese": false}, "c-orzo-cremoso-ceci-cavolfiore": {"id": "c-orzo-cremoso-ceci-cavolfiore", "fonte": "cookidoo", "titolo": "Orzo cremoso ai ceci e cavolfiore", "url": "https://cookidoo.it/recipes/recipe/it-IT/r662092", "tm6": true, "valutazioneCookidoo": [4.6, 230], "tempoMin": 40, "porzioniRicetta": "4 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "orzo", "ingredientiOriginali": ["70 g di patate americane dolci", "70 g di barbabietola", "olio extravergine di oliva", "fiocchi di sale", "1 scalogno", "1 spicchio di aglio", "30 g di olio extravergine di oliva", "400 g di cimette di cavolfiore", "1 cucchiaino di sale", "240 g di ceci bianchi in scatola", "2 cucchiai di semi misti", "600 g di brodo vegetale", "1 pizzico di pepe bianco macinato"], "passi": ["La vaschetta 2 di besciamella al cavolfiore deve essere in frigo da ieri sera. Per prima cosa metti sul fuoco una pentola con circa 3 litri di acqua, senza sale, con il coperchio.", "Sciacqua 300 g di orzo perlato in un colino. Quando l'acqua bolle versalo e cuocilo 25-30 minuti (secondo la confezione), mescolando ogni tanto, finché è tenero.", "Intanto metti nel boccale asciutto 40 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10. Trasferiscilo in una ciotolina: 20 g vanno nella crema, 20 g sui piatti degli adulti.", "Sciacqua sotto l'acqua fredda 570 g di ceci lessati (circa 2 barattoli e mezzo da 400 g) e lasciali sgocciolare nel colino.", "Metti nel boccale 30 g di scalogno e 1 spicchio di aglio sbucciati: trita 3 sec./vel. 6 e riunisci sul fondo con la spatola.", "Aggiungi 20 g di olio e insaporisci 3 min./120°C/vel. 1.", "Aggiungi i ceci, 150 g di acqua e 1 cucchiaino raso di dado vegetale senza sale: 5 min./100°C/antiorario/vel. 1.", "Mescola con una frusta la besciamella (circa 800 g) e versala tutta nel boccale con 20 g di Parmigiano. Frulla 1 min./vel. 5-9 aumentando gradualmente, fino a una crema liscia.", "Scalda la crema 5 min./90°C/vel. 2.", "Scola l'orzo tenendo da parte un mestolo di acqua di cottura e rimettilo nella pentola, a fuoco bassissimo.", "Versa la crema sull'orzo e manteca 2 minuti mescolando: deve essere morbido come un risotto. Se è troppo denso allunga con l'acqua di cottura.", "Preleva le porzioni dei bimbi, senza sale. Per il bimbo di 1 anno schiaccia un po' l'orzo con la forchetta e lascia intiepidire.", "Solo ora aggiungi sale e pepe bianco nei piatti degli adulti e completa con i 20 g di Parmigiano rimasti.", "Servi subito. Metti da parte 1 porzione adulto per il pranzo di domani in un contenitore chiuso in frigo: si addensa, quindi scaldala in un pentolino o al microonde con 2-3 cucchiai di acqua."], "modifiche": ["Il cavolfiore arriva dalla besciamella al cavolfiore di domenica 25 (c-besciamella-cavolfiore-senza-lattosio): usa tutta la vaschetta 2, circa 800 g con 400 g di cavolfiore, scongelata in frigo mercoledì sera. Tolti dalla spesa i 400 g di cavolfiore; il brodo scende da 600 a 150 g di acqua perché la besciamella è già fluida e la cottura da 25 a 5 minuti in antiorario: i ceci sono già cotti e devono solo scaldarsi senza attaccarsi al fondo.", "Ceci portati da 240 a 570 g lessati (dose legumi della famiglia, circa 190 g secchi): scaldati con scalogno e aglio e poi frullati con la besciamella, nessun legume intero.", "Usata come crema per mantecare 300 g di orzo perlato, lessato in pentola in acqua senza sale e messo sul fuoco per primo, invece che come zuppa. Orzo e non pasta: venerdì 9 c'è già la pasta con crema di cavolfiore (e gamberi), così i due piatti non si ripetono.", "Olio da 30 a 20 g (la besciamella ha già il burro); aggiunti 40 g di Parmigiano: 20 g nella crema e 20 g per servire.", "Eliminati chips di patata dolce e barbabietola (verdura visibile) e semi misti (possibile sesamo e rischio soffocamento).", "Non è più vegana (la besciamella contiene latte e burro senza lattosio e Parmigiano): titolo adattato in 'Orzo cremoso ai ceci e cavolfiore'.", "Niente sale in cottura (prima 1 cucchiaino e fiocchi di sale): 1 cucchiaino raso di dado vegetale senza sale; sale e pepe bianco solo agli adulti, dopo aver servito i bimbi.", "Capienza: circa 1,6 kg nel boccale per la frullata e il riscaldamento finale, sotto il limite di 2,2 L; l'orzo cuoce a parte in pentola."], "verduraNascosta": {"verdure": ["cavolfiore", "scalogno"], "grammiFamiglia": 430, "come": "La besciamella al cavolfiore di domenica (400 g di cavolfiore) è frullata con i ceci e un soffritto di scalogno e aglio in una crema bianca che manteca l'orzo.", "trucco": "Bianco su bianco: sembra un orzotto panna e formaggio. Finisci con una grattata di Parmigiano sopra."}, "lattosio": "sostituito", "notaLattosio": "La besciamella di base è fatta con latte e burro senza lattosio; Parmigiano Reggiano stagionato naturalmente senza lattosio.", "notaBimbi": "Crema liscia senza pezzi e ceci frullati: adatta a entrambi i bimbi; orzo ben cotto, per il bimbo di 1 anno schiaccialo un po' con la forchetta. Besciamella, dado e acqua dell'orzo sono senza sale: niente sale nei loro piatti. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo (contiene glutine e latte senza lattosio).", "scongelare": "besciamella al cavolfiore di domenica, vaschetta 2 (circa 800 g): dal congelatore al frigo", "gradimentoBimbiStimato": 4, "moltiplicatore": 1, "ingredienti": [{"nome": "scalogno", "qta": 30, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": ""}, {"nome": "ceci lessati", "qta": 570, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "peso sgocciolato e sciacquati (circa 2 barattoli e mezzo da 400 g), oppure 190 g secchi lessati senza sale"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale (fatto in casa o senza sale aggiunto), raso"}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "orzo perlato", "qta": 300, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "lessato in pentola"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver servito i bimbi"}, {"nome": "pepe bianco", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}], "accompagnamentoConsigliato": "Piatto unico; frutta a fine pasto.", "perche": "Crema ben votata (4,6 su 230) usata per mantecare l'orzo: con la besciamella di domenica il cavolfiore è già cotto, i ceci si scaldano e si frullano mentre l'orzo cuoce in pentola, e la cena è pronta in 40 minuti con 400 g di cavolfiore invisibile. Con l'orzo al posto della pasta non ripete la pasta con crema di cavolfiore di venerdì 9.", "passiCompleti": true, "usataNelMese": true}, "c-pasta-ragu-casa-crema-arancione": {"id": "c-pasta-ragu-casa-crema-arancione", "fonte": "personalizzata", "titolo": "Pasta al ragù di casa con crema arancione", "url": null, "tm6": true, "valutazioneCookidoo": null, "tempoMin": 35, "porzioniRicetta": "famiglia (2 adulti + 1 porzione pranzo + 2 bimbi)", "categoria": "carne_rossa", "ruolo": "completo", "cereale": "pasta", "ingredientiOriginali": [], "passi": ["La sera prima sposta dal congelatore al frigo circa 600 g di ragù classico di casa.", "Metti sul fuoco una pentola capiente con circa 3 litri di acqua per la pasta, senza sale. Metti nel boccale 40 g di Parmigiano a pezzi e grattugia 10 sec./vel. 10. Trasferisci in una ciotolina.", "Metti nel boccale 40 g di cipolla e trita 3 sec./vel. 5. Riunisci sul fondo con la spatola, aggiungi 20 g di olio e insaporisci 3 min./120°C/vel. 1.", "Aggiungi 260 g di patate dolci pelate e 160 g di sedano rapa pulito, a pezzi, e trita 10 sec./vel. 6. Aggiungi 200 g di acqua e cuoci 15 min./100°C/vel. 1.", "Frulla 40 sec./vel. 5-10 aumentando gradualmente fino a una crema liscia, senza pezzetti.", "Aggiungi il ragù di casa e scalda 8 min./100°C/antiorario/vel. 1, con il cestello sul coperchio al posto del misurino (5 minuti in più se il ragù è ancora in parte congelato). Non aggiungere sale.", "Intanto, quando l'acqua bolle, cuoci 315 g di pasta corta (mezze penne, fusilli o conchiglie) senza sale, per il tempo indicato sulla confezione. Scolala al dente tenendo da parte un mestolo di acqua di cottura.", "Condisci la pasta con il ragù arancione, allungando con poca acqua di cottura se serve. Preleva le porzioni dei bimbi (per il bimbo di 1 anno pasta ben cotta tagliata a pezzetti), poi servi gli adulti con il Parmigiano; sale solo nei piatti degli adulti, se serve.", "Porzione per il pranzo di domani: metti da parte 1 porzione adulto di pasta condita in un contenitore chiuso in frigo; scaldala al microonde con 1-2 cucchiai di acqua."], "modifiche": ["Al posto di un ragù cotto sul momento si usa il ragù classico di casa (circa 600 g), scongelato in frigo la sera prima.", "Il ragù viene allungato con una crema di patate dolci e sedano rapa (420 g di verdura più 40 g di cipolla) frullata liscia: più sugo, stesso colore del ragù.", "Condisce 315 g di pasta corta (dose cereali della famiglia) cotta in pentola mentre il Bimby prepara la crema e scalda il ragù: cena pronta in circa 35 minuti. Pasta e non polenta, perché martedì 27 c'è già la polenta con il ragù di pollo.", "Niente sale nell'acqua della pasta né nel ragù: sale solo nei piatti degli adulti, dopo aver prelevato le porzioni dei bimbi."], "verduraNascosta": {"verdure": ["patate dolci", "sedano rapa", "cipolle"], "grammiFamiglia": 460, "come": "Patate dolci e sedano rapa cotti e frullati in una crema liscia, in cui si scalda il ragù di casa: il ragù arancione condisce la pasta.", "trucco": "Il ragù diventa solo più abbondante e vellutato: il colore resta quello del ragù e sulla pasta non si distingue nulla. Le patate dolci addolciscono il sugo."}, "lattosio": "no", "notaLattosio": "Solo Parmigiano Reggiano stagionato, naturalmente privo di lattosio. Il ragù di casa è quello che prepari tu: se nella tua ricetta c'è latte, usi già quello senza lattosio.", "notaBimbi": "Ragù allungato con la crema e pasta ben cotta: per il bimbo di 1 anno tagliala a pezzetti (se nel ragù ci sono pezzetti più grandi, schiacciali con la forchetta). Acqua della pasta senza sale e niente sale nel ragù, che è già saporito. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo (contiene glutine).", "scongelare": "ragù classico di casa, circa 600 g", "gradimentoBimbiStimato": 5, "moltiplicatore": 1, "ingredienti": [{"nome": "ragù classico di casa", "qta": 600, "unita": "g", "reparto": "surgelati", "dispensa": false, "casa": true, "nota": "dal tuo freezer"}, {"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": ""}, {"nome": "cipolle", "qta": 40, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "olio extravergine di oliva", "qta": 20, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "per il soffritto"}, {"nome": "patate dolci", "qta": 260, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pelato: compra circa 320 g"}, {"nome": "sedano rapa", "qta": 160, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito: compra circa il 35% in più (buccia spessa)"}, {"nome": "pasta corta", "qta": 315, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": "mezze penne, fusilli o conchiglie"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver prelevato le porzioni dei bimbi"}], "accompagnamentoConsigliato": "Già completa (pasta + ragù di casa + 420 g di verdura nella crema); frutta a fine pasto.", "perche": "Il modo più semplice per usare il ragù di casa in una sera feriale: la pasta cuoce in pentola mentre il Bimby scalda il ragù nella crema di patate dolci e sedano rapa. La pasta al ragù è tra i piatti preferiti dei bimbi, e con la pasta al posto della polenta questa cena non ripete la polenta al ragù di pollo di martedì 27.", "usataNelMese": true}, "c-zuppa-orzo-borlotti": {"id": "c-zuppa-orzo-borlotti", "fonte": "cookidoo", "titolo": "Zuppa di orzo e borlotti", "url": "https://cookidoo.it/recipes/recipe/it-IT/r148082", "tm6": true, "valutazioneCookidoo": [4.8, 934], "tempoMin": 55, "porzioniRicetta": "4 porzioni", "categoria": "legumi", "ruolo": "completo", "cereale": "orzo", "ingredientiOriginali": ["70 g di cipolla", "70 g di carota", "1 spicchio di aglio", "2 foglie di salvia fresca", "1 rametto di rosmarino fresco", "30 g di olio extravergine di oliva", "100 g di pancetta affumicata", "700 g acqua", "1 cucchiaino di sale", "160 g di farro perlato", "120 g di fagioli cannellini in scatola", "120 g di fagioli borlotti in scatola", "pepe nero macinato"], "passi": ["Prepara le verdure: sbuccia il sedano rapa e taglia 220 g a cubetti di 2 cm; pulisci il finocchio e taglia 200 g a pezzi. Sbuccia 50 g di cipolla e, se vuoi, 1 spicchio di aglio.", "Scola 560 g di borlotti lessati, sciacquali sotto l'acqua corrente e dividili in due ciotole da 280 g. Lava e asciuga 1 rametto di rosmarino e 2 foglie di salvia.", "Nel boccale pulito e asciutto grattugia 40 g di Parmigiano a pezzi: 10 sec./vel. 10. Trasferiscilo in una ciotolina.", "Metti nel boccale cipolla, aglio, sedano rapa e finocchio: trita 8 sec./vel. 6 e riunisci sul fondo con la spatola.", "Aggiungi 30 g di olio, il rametto di rosmarino intero e le 2 foglie di salvia intere (niente pancetta): insaporisci 5 min./120°C/antiorario/vel. 1.", "Togli rosmarino e salvia con una pinza, controllando che non restino foglie. Metti a scaldare il bollitore: a fine cottura ti serviranno circa 350 g di acqua calda.", "Aggiungi nel boccale la prima ciotola di borlotti (280 g) e 200 g di acqua. Con il misurino inserito frulla 40 sec./vel. 5-10 aumentando gradualmente, fino a una crema liscia.", "Sciacqua 250 g di orzo perlato in un colino e mettilo nel boccale con 450 g di acqua e 1 cucchiaino raso di dado vegetale senza sale, senza sale. Metti il cestello sul coperchio al posto del misurino e cuoci 30 min./100°C/antiorario/vel. 1.", "Dopo 15 minuti metti in pausa, apri e mescola bene raschiando il fondo con la spatola, perché l'orzo tende ad attaccarsi. Se è già molto densa aggiungi 100 g di acqua calda, richiudi e riprendi la cottura.", "A fine cottura assaggia un chicco: l'orzo deve essere tenero (se è ancora duro prosegui 5 min./100°C/antiorario/vel. 1). Versa la zuppa in una zuppiera.", "Aggiungi 250 g di acqua bollente del bollitore e la seconda ciotola di borlotti interi (280 g). Mescola e lascia riposare 5 minuti; se è troppo densa allunga con poca acqua calda.", "Preleva le porzioni dei bimbi, senza sale né pepe, e schiaccia bene con la forchetta tutti i borlotti interi (sotto i 4 anni un fagiolo intero può andare di traverso). Per il bimbo di 1 anno puoi anche frullare qualche secondo la sua porzione con il minipimer; lascia intiepidire.", "Solo adesso sala e pepa la zuppa degli adulti (compresa la porzione per domani) e mescola.", "Servi con un filo di olio crudo (circa 10 g in tutto) e il Parmigiano grattugiato; ai bimbi va bene il Parmigiano, non il pepe.", "Per il pranzo di domani metti da parte 1 porzione adulto in un contenitore chiuso e, appena intiepidita, riponila in frigo. Domani sarà più densa: scaldala allungandola con un po' di acqua."], "modifiche": ["Farro perlato sostituito da 250 g di orzo perlato (nell'originale 160 g di farro), con la stessa cottura di 30 minuti mescolando a metà: il farro è già nella cena di domenica 25 (farro al pesto), così le due domeniche non ripetono lo stesso cereale.", "Solo borlotti al posto di borlotti e cannellini: 560 g lessati (dose legumi della famiglia), 280 g frullati nella base e 280 g interi aggiunti a fine cottura. I cannellini sono già nella crema del farro al pesto di domenica 25.", "Pancetta affumicata eliminata (niente affumicati per i bimbi): il sapore arriva dall'olio aromatizzato con rosmarino e salvia.", "Rosmarino e salvia messi interi nel soffritto e tolti prima di frullare: profumano la zuppa ma nel piatto non c'è nessuna erba visibile.", "Carota sostituita da 220 g di sedano rapa e 200 g di finocchio (le carote sono già in 7 cene del mese), tritati, soffritti e frullati con i borlotti: base cremosa senza pezzi di verdura.", "Acqua divisa per rispettare la capienza del boccale: 200 g per frullare i borlotti e 450 g per la cottura dell'orzo (nel boccale circa 1,7 kg, lontano dal limite dei 2,2 L anche con la schiuma di orzo e fagioli); altri 250 g di acqua bollente e i borlotti interi si aggiungono nella zuppiera a fine cottura.", "Sale eliminato dalla cottura e solo 1 cucchiaino raso di dado vegetale senza sale; legumi in scatola sciacquati. Sale e pepe solo nei piatti degli adulti, dopo aver prelevato quelli dei bimbi."], "verduraNascosta": {"verdure": ["sedano rapa", "finocchi"], "grammiFamiglia": 420, "come": "Sedano rapa e finocchio (con la cipolla) vengono tritati, soffritti e frullati con metà dei borlotti: diventano la crema densa in cui cuoce l'orzo.", "trucco": "Il marrone dei borlotti frullati copre tutto e il finocchio cotto non sa di anice: sembra una classica minestra di fagioli. I chicchi d'orzo piacciono ai bimbi come 'perline'."}, "lattosio": "no", "notaLattosio": "Nessun latticino in cottura; Parmigiano Reggiano stagionato (naturalmente senza lattosio) solo a tavola.", "notaBimbi": "Borlotti interi schiacciati con la forchetta per entrambi i bimbi (sotto i 4 anni rischio soffocamento); orzo ben cotto, per il bimbo di 1 anno si può frullare qualche secondo la sua porzione. Porzioni dei bimbi prelevate prima di sale e pepe. Rosmarino e salvia tolti prima di frullare: nessuna erba visibile. Nessun allergene tra crostacei, molluschi, frutta a guscio e sesamo (contiene glutine).", "scongelare": "", "gradimentoBimbiStimato": 3, "moltiplicatore": 1.5, "ingredienti": [{"nome": "parmigiano reggiano", "qta": 40, "unita": "g", "reparto": "latticini_uova", "dispensa": false, "nota": "per servire"}, {"nome": "cipolle", "qta": 50, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": ""}, {"nome": "aglio", "qta": 1, "unita": "spicchi", "reparto": "frutta_verdura", "dispensa": false, "nota": "facoltativo"}, {"nome": "sedano rapa", "qta": 220, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito: compra circa il 35% in più (buccia spessa)"}, {"nome": "finocchi", "qta": 200, "unita": "g", "reparto": "frutta_verdura", "dispensa": false, "nota": "peso pulito, circa 1 finocchio piccolo"}, {"nome": "rosmarino", "qta": 1, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "rametto, solo per insaporire"}, {"nome": "salvia", "qta": 2, "unita": "pz", "reparto": "frutta_verdura", "dispensa": false, "nota": "foglie, solo per insaporire"}, {"nome": "olio extravergine di oliva", "qta": 40, "unita": "g", "reparto": "dispensa", "dispensa": true, "nota": "30 g in cottura + filo a crudo"}, {"nome": "fagioli borlotti lessati", "qta": 560, "unita": "g", "reparto": "dispensa", "dispensa": false, "nota": "280 g frullati nella base + 280 g interi; peso sgocciolato e sciacquati (circa 2 barattoli e mezzo da 400 g), oppure 190 g secchi lessati senza sale"}, {"nome": "dado vegetale", "qta": 1, "unita": "cucchiaini", "reparto": "spezie_condimenti", "dispensa": true, "nota": "senza sale, raso"}, {"nome": "orzo perlato", "qta": 250, "unita": "g", "reparto": "pane_pasta_cereali", "dispensa": false, "nota": ""}, {"nome": "pepe nero", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti"}, {"nome": "sale fino", "qta": null, "unita": "q.b.", "reparto": "spezie_condimenti", "dispensa": true, "nota": "solo adulti, dopo aver prelevato le porzioni dei bimbi"}], "accompagnamentoConsigliato": "Piatto unico; frutta a fine pasto.", "perche": "La zuppa di legumi più votata della ricerca (934 recensioni): senza pancetta, con sedano rapa e finocchio frullati nella base e con orzo e soli borlotti diventa una cena completa diversa dal farro al pesto con cannellini di domenica 25. Domenica 18: al mattino il Bimby fa la crema di broccoli (base della settimana), la sera questa zuppa in circa 55 minuti, quasi tutti di cottura.", "passiCompleti": true, "usataNelMese": true}}}};
